function gauss(r) { let u = 0; while (u === 0) u = r(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * r()); }
function bsLE(a, t) { let lo = 0, hi = a.length - 1, ans = -1; while (lo <= hi) { const m = (lo + hi) >> 1; if (a[m] <= t) { ans = m; lo = m + 1; } else hi = m - 1; } return ans; }
function bsGE(a, t) { let lo = 0, hi = a.length - 1, ans = a.length; while (lo <= hi) { const m = (lo + hi) >> 1; if (a[m] >= t) { ans = m; hi = m - 1; } else lo = m + 1; } return ans; }
const P = s => Date.parse(s.length === 7 ? s + '-28' : s);

/* ---------- formatting ---------- */
const MINUS = '−';
const nf = (v, dp = 2) => (v == null || !isFinite(v)) ? '—' : Number(v).toLocaleString('en-US', { minimumFractionDigits: dp, maximumFractionDigits: dp });
const sgn = (v, dp = 2, suf = '') => (v == null || !isFinite(v)) ? '—' : (v > 0 ? '+' : v < 0 ? MINUS : '') + nf(Math.abs(v), dp) + suf;
const pc = (v, dp = 2) => sgn(v, dp, '%');
const bpf = (v, dp = 1) => sgn(v, dp, ' bp');
const cls = v => v == null ? 'fl' : v > 0 ? 'up' : v < 0 ? 'dn' : 'fl';
