function toast(msg, bad) { const t = document.createElement('div'); t.className = 'toast' + (bad ? ' bad' : ''); t.setAttribute('role', 'status'); t.textContent = msg; $('#toasts').append(t); setTimeout(() => t.remove(), 3400); }
async function copyText(txt, fallback) { try { await navigator.clipboard.writeText(txt); toast('Copied to clipboard'); } catch (e) { if (fallback) { fallback.focus(); fallback.select(); } toast('Clipboard blocked here — the text is selected, press Ctrl/Cmd+C', true); } }

function modal(title, body, { wide, actions = [] } = {}) {
  const w = document.createElement('div'); w.className = 'mw';
  w.innerHTML = `<div class="md ${wide ? 'wide' : ''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h3>${esc(title)}</h3><button class="ib" data-x aria-label="Close">×</button></header><div class="mb"></div><footer class="mf"></footer></div>`;
  const mb = $('.mb', w); if (typeof body === 'string') mb.innerHTML = body; else mb.append(body);
  const close = () => { w.remove(); document.removeEventListener('keydown', k); };
  const k = e => { if (e.key === 'Escape') close(); };
  document.addEventListener('keydown', k);
  w.addEventListener('mousedown', e => { if (e.target === w) close(); });
  $('[data-x]', w).onclick = close;
  for (const a of actions) { const b = document.createElement('button'); b.className = 'btn ' + (a.cls || ''); b.textContent = a.label; b.onclick = () => a.fn(close, mb); $('.mf', w).append(b); }
  document.body.append(w); setTimeout(() => { const f = $('input,select,textarea,button.pri', w); if (f) f.focus(); }, 20);
  return { el: w, mb, close };
}
function confirmBox(msg, fn, label = 'Delete') { modal('Please confirm', `<p style="margin:0">${esc(msg)}</p>`, { actions: [{ label: 'Cancel', fn: c => c() }, { label, cls: 'pri', fn: c => { c(); fn(); } }] }); }
