  table($('#sl', pg), { rows: S.screens, sort: { k: 'c', d: -1 }, empty: '<b>No saved screens</b>Build one in the Stock Screener and press Save.', cols: [{ k: 'n', h: 'Screen', v: r => r.name, f: r => `<a class="tk" data-go="screener" data-p="${r.id}" style="font-family:var(--f-ui);font-size:13.5px">${esc(r.name)}</a>` }, { k: 'f', h: 'Criteria', f: r => `<span class="sub" style="max-width:420px;display:block">${esc(screenSummary(r.f))}</span>` }, { k: 'm', h: 'Matches now', a: 'r', v: r => runScreen(r.f).length, f: r => runScreen(r.f).length }, { k: 'c', h: 'Created', v: r => r.created, f: r => fdt(r.created) }, { k: 'x', h: '', f: r => `<button class="btn sm ghost" data-del="${r.id}">Delete</button>` }] });
  on(pg, 'click', '[data-del]', (e, b) => confirmBox('Delete this screen?', () => { S.screens = S.screens.filter(s => s.id !== b.dataset.del); save(); render(); }));
