    $('#wmet', pg).innerHTML = c.metrics.map(id => `<div class="si"><i style="background:${PAL[all.indexOf(id) % 8]}"></i><span class="nm">${lnk(id)} <span class="muted">${esc(BY[id].short || BY[id].name)}</span></span><button data-rmid="${id}" aria-label="Remove">×</button></div>`).join('') || '<div class="note">Yields and economic series plot as levels in their own panes.</div>';
    $('#wcomp', pg).innerHTML = c.comps.map((k, i) => `<div class="si"><span class="nm">${esc(COMPS[k][0])} <span class="muted">${COMPS[k][1] === 'ov' ? 'overlay' : 'pane'}</span></span><button data-cu="${i}" ${i ? '' : 'disabled'} aria-label="Move up">↑</button><button data-cd="${i}" ${i < c.comps.length - 1 ? '' : 'disabled'} aria-label="Move down">↓</button><button data-cr="${i}" aria-label="Remove">×</button></div>`).join('') || '<div class="note">Indicators apply to the primary series.</div>';
    $('#wtpl', pg).innerHTML = TPL.concat(S.templates).map(t => `<option value="${t.id}">${esc(t.name)}${t.id.startsWith('t-') ? '' : ' (mine)'}</option>`).join('');
    $('#wsaved', pg).innerHTML = S.graphs.map(g => `<div class="si"><span class="nm"><a class="tk" data-og="${g.id}" style="font-family:var(--f-ui)">${esc(g.name)}</a></span>${g.id === GW.gid ? '<span class="badge acc">Open</span>' : ''}<button data-dg="${g.id}" aria-label="Delete saved graph">×</button></div>`).join('') || '<div class="note">Nothing saved yet.</div>';
