  const doSave = asNew => { const name = $('#wname', pg).value.trim() || 'Untitled graph'; if ((asNew || !GW.gid) && S.graphs.length >= plan().graphs) { toast('Saved-graph limit reached for your plan', true); return; } if (asNew || !GW.gid) { const g = { id: uid(), name: asNew && GW.gid ? name + ' (copy)' : name, cfg: JSON.parse(JSON.stringify(c)), updated: Date.now() }; S.graphs.unshift(g); GW.gid = g.id; GW.name = g.name; $('#wname', pg).value = g.name; } else { const g = S.graphs.find(x => x.id === GW.gid); g.name = name; g.cfg = JSON.parse(JSON.stringify(c)); g.updated = Date.now(); GW.name = name; } GW.saved = JSON.stringify(c); save(); sideDraw(); toast('Graph saved'); try { history.replaceState(null, '', '#graphs.' + GW.gid); } catch (e) { } };
  $('#wsave', pg).onclick = () => doSave(false); $('#wsaveas', pg).onclick = () => doSave(true);
