  on(pg, 'click', '[data-og]', (e, b) => { const g = S.graphs.find(x => x.id === b.dataset.og); GW = { gid: g.id, name: g.name, cfg: { ...WS_DEF, ...JSON.parse(JSON.stringify(g.cfg)) }, undo: [], redo: [] }; GW.saved = JSON.stringify(GW.cfg); render(); });
