    `<div class="grid"><section class="panel c6"><header class="ph"><span class="pt">Profile</span></header><form class="pb" id="pf" style="display:flex;flex-direction:column;gap:8px"><label class="f"><span>Name</span><input class="inp" id="pn" value="${esc(USER.name)}" maxlength="60"></label>${USER.cloud ? `<p class="note" style="margin:0">Signed in with your Claude account. Your name comes from Claude; watchlists, graphs and notes are saved in this browser, while organization membership and shared items live in the shared workspace.</p>` : `<label class="f"><span>Email (profile key)</span><input class="inp" value="${esc(USER.email)}" disabled></label>`}<label class="f"><span>Role in workspace</span><select class="inp" id="pr">${['Owner', 'Analyst', 'Portfolio manager', 'Advisor', 'Viewer'].map(r => `<option ${r === USER.role ? 'selected' : ''}>${r}</option>`).join('')}</select></label><div class="row"><button class="btn pri" type="submit">Save profile</button>${USER.cloud ? '' : '<button class="btn" type="button" id="so">Sign out</button>'}</div></form></section>
    <section class="panel c6"><header class="ph"><span class="pt">Workspace & display</span></header><div class="pb" style="display:flex;flex-direction:column;gap:10px"><label class="f"><span>Workspace name</span><input class="inp" id="wn" value="${esc(S.workspace)}" maxlength="60"></label><div class="row"><span class="note" style="width:120px">Language</span>${langSelect('set')}</div><div class="row"><span class="note" style="width:120px">Theme</span>${seg('th', [['light', 'Light'], ['dark', 'Dark']], S.prefs.look || 'light')}</div><div class="row"><span class="note" style="width:120px">Density</span>${seg('dn', [['comfortable', 'Comfortable'], ['compact', 'Compact']], S.prefs.density || 'compact')}</div><div class="row"><span class="note" style="width:120px">Context panel</span>${seg('rpp', [['1', 'Shown'], ['0', 'Hidden']], S.prefs.ctxPanel ? '1' : '0')}</div><div class="note">Positive values use the green tone and negative values the red tone throughout; changes in yields are always in basis points.</div></div></section>
    <section class="panel c6"><header class="ph"><span class="pt">Storage & portability</span></header><div class="pb" style="display:flex;flex-direction:column;gap:8px"><div>${LS.ok ? '<span class="badge ok">Browser storage available</span> Saved items survive refreshes and future visits in this browser.' : '<span class="badge bad">Storage blocked</span> This browser is refusing local storage, so changes last only for this session. Export your workspace to keep it.'}</div><div class="note">Workspace size: ${nf(JSON.stringify(S).length / 1024, 1)} KB · ${S.watchlists.length} watchlists · ${S.graphs.length} graphs · ${S.notes.length} notes · ${S.alerts.length} alerts</div><div class="row"><button class="btn" id="ex">Export workspace</button><button class="btn" id="im">Import workspace</button><button class="btn dng" id="rs">Reset to examples</button></div></div></section>
    <section class="panel c6"><header class="ph"><span class="pt">Profiles on this device</span></header><div class="pb">${users.map(u => `<div class="row" style="justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--line)"><span><b>${esc(u.name)}</b> <span class="muted">${esc(u.email)}</span></span>${u.email === USER.email ? '<span class="badge acc">Signed in</span>' : ''}</div>`).join('')}<div class="note" style="margin-top:8px">Each profile’s workspace is isolated. Sign out to switch or create another profile.</div></div></section></div>`;
  $('#pf', pg).onsubmit = e => { e.preventDefault(); USER.name = $('#pn', pg).value.trim() || USER.name; USER.role = $('#pr', pg).value; const us = (LS.get('sf.users') || []).map(u => u.email === USER.email ? USER : u); LS.set('sf.users', us); $('#avatar').textContent = USER.name.split(/\s+/).map(s => s[0]).join('').slice(0, 2).toUpperCase(); toast('Profile saved'); };
