  const showPri = (cl === 'all' || cl === 'pri');
  const priCard = !showPri ? '' : !allowPri ? `<section class="panel"><div class="pb"><div class="note" style="padding-top:12px">Private markets are switched off for your account by your organization's admin.</div></div></section>` : (() => { const d = DEALS.filter(x => x.type !== 'Buyout').slice(0, 5); const f = PFUNDS.filter(x => x.q === 1).sort((a, b) => b.vintage - a.vintage).slice(0, 4); return `<section class="panel"><header class="ph"><a class="pt" data-go="deals">Latest private rounds</a>${fictB()}</header><div class="pb">${d.map(x => `<div class="dvr" data-go="pco" data-p="${x.co}" role="link" tabindex="0"><span><b style="font-weight:500">${esc(PCO[x.co].name)}</b><small>${esc(x.type)} · ${esc(PCO[x.co].industry)} · ${fds(x.t)}</small></span><span class="mono">${big(x.amt, '$')}</span>${x.step ? `<span class="chgp ${x.step >= 1 ? 'up' : 'dn'}">${nf(x.step, 2)}×</span>` : '<span></span>'}</div>`).join('')}</div></section><section class="panel"><header class="ph"><a class="pt" data-go="funds">Top-quartile funds</a>${fictB()}</header><div class="pb">${f.map(x => `<div class="dvr" data-go="funds" data-p="${x.id}" role="link" tabindex="0"><span><b style="font-weight:500">${esc(x.name)}</b><small>${esc(x.strat)} · ${x.vintage}</small></span><span class="mono">${pc(x.irr, 1)}</span><span class="chgp fl">${nf(x.tvpi, 2)}×</span></div>`).join('')}</div></section>`; })();
  // people & firms
  const act = {}; recent.forEach(x => act[x.author] = (act[x.author] || 0) + 1);
  const ppl = verifiedPeople().filter(id => id !== CLOUD.uid && NET.ver[id].oid !== CLOUD.oid).sort((a, b) => (act[b] || 0) - (act[a] || 0)).slice(0, 6);
  const firms = {}; verifiedPeople().forEach(id => { const o = NET.ver[id].oid; firms[o] = firms[o] || { name: NET.ver[id].name, n: 0, posts: 0 }; firms[o].n++; firms[o].posts += act[id] || 0; });
