  if (o.type === 'yield') { f.curve = Object.fromEntries(MATS.map(m => [m + 'Y_pct', BY[`YD.${o.country}${m}`] ? r2(quote(`YD.${o.country}${m}`).last, 3) : null])); if (BY[`YD.${o.country}2`] && BY[`YD.${o.country}10`]) f.curve.spread_2s10s_bp = r2((quote(`YD.${o.country}10`).last - quote(`YD.${o.country}2`).last) * 100, 0); }
