function screenText() { const pg = $('#main .page'); if (!pg) return ''; const cl = pg.cloneNode(true); $$('.aip, script, style, .tabs, .seg, select, button', cl).forEach(n => n.remove()); return cl.innerText.replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 12000); }

/* ---------- number verification ---------- */
const NUM_RE = /(?:^|[^A-Za-z0-9_.])([-−+]?)\$?((?:\d{1,3}(?:,\d{3})+|\d+)(?:\.\d+)?)\s*(tn|bn|mm|T|B|M|K|k)?(?![A-Za-z0-9])/g;
const SUF = { T: 1e12, tn: 1e12, B: 1e9, bn: 1e9, M: 1e6, mm: 1e6, K: 1e3, k: 1e3 };
function nums(text) { const out = []; let m; NUM_RE.lastIndex = 0; while ((m = NUM_RE.exec(text))) { const raw = m[2]; const d = (raw.split('.')[1] || '').length; const v = parseFloat(raw.replace(/,/g, '')); out.push({ raw: m[0].trim(), v, d, suf: m[3] ? SUF[m[3]] : 1 }); } return out; }
const EXEMPT = new Set([14, 20, 21, 50, 52, 63, 100, 200, 252]);
