const LOADED = /\b(buy|sell|hold(?:ing)? rating|overweight|underweight|undervalued|overvalued|cheap|expensive|bargain|price target|target price|upside|downside|will (?:rise|fall|climb|drop|rally|outperform|underperform)|expect(?:s|ed)? (?:to|a)|forecast\w*|soar\w*|plung\w*|skyrocket\w*|crash\w*|stellar|terrible|bullish|bearish|must)\b/gi;
