  { const vs = VOLSET.map(id => ({ id, v: valAt(id, t), ch: gChg(id, t), p: nxLvlPct(id, t), z: nxZ(id, t) })).filter(x => x.v != null); const el = vs.filter(x => (x.p ?? 0) >= 80); const big = vs.slice().sort((a, b) => Math.abs(b.z || 0) - Math.abs(a.z || 0)).slice(0, 2);
    if (vs.length) add({ id: 'vg' + t, kind: 'vlx', topic: 'Volatility', ids: VOLSET.concat(['IX.SKEW']), p: big[0].id, broad: true, z: big[0].z, u: el.length / VOLSET.length, uWhy: `${el.length} of ${VOLSET.length} volatility gauges at or above the 80th percentile`, sig: el.length >= 2 ? ['highvol'] : [], mkts: ['Equities', 'Rates', 'Commodities', 'FX'],
      title: `Volatility gauges: ${big.map(x => `${BY[x.id].tk} ${nf(x.v, 1)} (${sgn(x.ch, 2)})`).join(', ')}; ${el.length} of ${VOLSET.length} in the top fifth of their 1-year range`, sum: `MOVE ${nf(valAt('IX.MOVE', t), 1)}, OVX ${nf(valAt('IX.OVX', t), 1)}, GVZ ${nf(valAt('IX.GVZ', t), 1)}, EVZ ${nf(valAt('IX.EVZ', t), 2)}; SKEW ${nf(valAt('IX.SKEW', t), 1)}.`,
      facts: vs.map(x => `${BY[x.id].tk} ${nf(x.v, 2)} (${sgn(x.ch, 2)} pts), ${nf(x.p ?? 0, 0)}th percentile of 1 year`), hyp: ['Implied volatility rising across asset classes together points to a broad repricing of risk; rising in one class only points to an asset-specific concern.', 'Compare each gauge with the realized volatility of its underlying (shown in Risk & sentiment gauges).'], unk: ['Option prices behind these indices are simulated; no options data is connected.'], ev: [['Volatility index levels', 'IX.VIX']] }); }
