  if (X['IX.NDX'].v != null && Math.sign(spx) !== Math.sign(X['IX.NDX'].v)) contras.push({ what: `S&P 500 ${pc(spx)} and Nasdaq 100 ${pc(X['IX.NDX'].v)} moved in opposite directions`, alts: ['Sector mix (technology weight)', 'Size effects among the largest companies'], need: 'Sector contributions and breadth' });
  for (let k = 0; k < 5; k++) { const tt = nxPrevN(t, k); EQ.forEach(o => { if (nxEarnDates(o.id).slice(1).includes(tt)) { const e = nxEarn(o.id, tt); if (e.surp > 2 && e.rx != null && e.rx < -1) contras.push({ what: `${o.tk} beat simulated consensus by ${nf(e.surp, 1)}% but fell ${pc(e.rx)}`, alts: ['Guidance or margins (not in this data)', 'Expectations above the published consensus', 'A market-wide move that day'], need: 'Forward guidance and segment results from the release', id: o.id }); } }); }
  add('contra', 'Narrative contradictions', contras.length > 0, contras.length ? `${contras.length} case${contras.length > 1 ? 's' : ''} where market behaviour conflicts with an apparent narrative.` : 'No contradictions found.', contras.map(c => [c.what, 'Test: ' + c.need]), 'Checks oil vs energy stocks, index vs breadth, S&P 500 vs Nasdaq 100, and earnings beats followed by declines (last 5 sessions).', ['CM.CO1', 'ET.XLE', 'IX.SPX', ...contras.filter(c => c.id).map(c => c.id)], { contras });
