  { const ps = VOLSET.map(id => [id, nxLvlPct(id, t), nxZ(id, t)]); const hi = ps.filter(x => (x[1] ?? 0) >= 80), up = ps.filter(x => (x[2] ?? 0) >= 1);
    add('vstress', 'Cross-asset volatility stress', hi.length >= 3 || up.length >= 3, hi.length >= 3 ? `${hi.length} of ${VOLSET.length} volatility gauges are in the top fifth of their 1-year range.` : `${up.length} volatility gauges rose by at least one standard deviation on the day.`, ps.map(([id, p, z]) => [BY[id].tk, `${nf(valAt(id, t), 2)} · ${nf(p ?? 0, 0)}th pct · ${sgn(z, 1)}σ`]), 'Triggers when 3 or more of VIX, VXN, VXD, GVZ, OVX, MOVE and EVZ sit at or above their 80th 1-year percentile, or rise by 1σ or more on the day.', VOLSET); }
  add('unu', 'Cluster of unusual moves', d.unusual.length >= 6, `${d.unusual.length} instruments moved beyond 2σ or traded above 2× average volume.`, d.unusual.slice(0, 6).map(x => [BY[x.id].tk, `${unitCh(x.id, x.v)} · ${zf(x.z)}${x.vx >= 2 ? ' · vol ' + nf(x.vx, 1) + '×' : ''}`]), 'Triggers when 6 or more instruments breach |σ-score| ≥ 2 or volume ≥ 2× the 20-day average.', d.unusual.slice(0, 6).map(x => x.id));
  return ins;
