  if (st.type === 'Research') items = items.filter(x => rel.s.has(x.id)); else if (st.type === 'Charts') items = items.filter(x => x.ct === 'News' && x.p && BY[x.p]); else if (st.type !== 'All') items = items.filter(x => x.ct === st.type); else items = items.filter(x => x.ct !== 'AI Insights');
  if (st.topic !== 'All') items = items.filter(x => x.topic === st.topic);
