  if (st.rel.length) items = items.filter(x => (st.rel.includes('w') && x.ids.some(id => rel.w.has(id))) || (st.rel.includes('p') && x.ids.some(id => rel.p.has(id))) || (st.rel.includes('s') && rel.s.has(x.id)));
  if (st.ticker) items = items.filter(x => x.ids.includes(st.ticker));
  if (st.q) { const q = st.q.toLowerCase(); items = items.filter(x => (x.title + ' ' + x.sum + ' ' + x.ids.map(id => BY[id]?.tk).join(' ')).toLowerCase().includes(q)); }
  const relScore = x => (x.ids.some(id => rel.w.has(id)) ? 2 : 0) + (x.ids.some(id => rel.p.has(id)) ? 2 : 0) + (rel.s.has(x.id) ? 1 : 0);
