    <div class="nx-row"><div class="nx-tx"><h4>${esc(x.title)}</h4><p>${esc(x.sum)}</p></div>${x.p && x.kind !== 'ins' ? `<div class="nx-sp">${nxSpark(x.p, x.day)}<span class="${cls(pv)}">${esc(BY[x.p].tk)} ${unitCh(x.p, pv)}</span></div>` : ''}</div>
