  ['#nxFrom', '#nxTo'].forEach(s => $(s, pg).onchange = () => { st.from = Date.parse($('#nxFrom', pg).value); st.to = Date.parse($('#nxTo', pg).value); if (st.from > st.to) [st.from, st.to] = [st.to, st.from]; reset(); });
