  const act = Object.entries(sec).map(([s, xs]) => ({ s, abs: xs.reduce((a, x) => a + Math.abs(x.v), 0) / xs.length, rv: xs.filter(x => x.rv).reduce((a, x) => a + x.rv, 0) / (xs.filter(x => x.rv).length || 1), v: perf(sectorETF(s).id, MV.per), n: xs.length })).sort((a, b) => b.rv - a.rv);
