function mvFacts() {
  const rows = mvFilter(mvPool()); const r = v => r2(v); const b = mvBreadth(rows); const row = x => ({ ticker: x.o.tk, name: x.o.name, sector: x.o.sector || null, return_pct: r(x.v), vs_sector_pp: r(x.rel), vs_sp500_pp: r(x.relM), relative_volume: r(x.rv), rel_volume_percentile_1y: r(x.rvp), u_score_sigma: r(x.U), trend: x.trend, market_cap_usd_bn: x.mc ? r(x.mc / 1e9) : null, catalyst: x.ern ? `simulated earnings ${iso(x.ern.t)}, EPS surprise ${r(x.ern.surp)}%` : 'unverified (no news provider)' });
  const f = { period: MV.per, universe: { eq: 'U.S. large caps', etf: 'ETFs', all: 'All assets' }[MV.uni], instruments: rows.length, breadth: { advancing: b.adv, declining: b.dec, moving_more_than_2pct: b.big2, above_50d_ma: b.a50, above_200d_ma: b.a200, near_52w_high: b.hi, near_52w_low: b.lo, cap_weighted_return_pct: r(b.cwr), top5_contribution_pct_points: r(b.top5) }, most_active_sectors: b.act.slice(0, 4).map(x => ({ sector: x.s, avg_relative_volume: r(x.rv), sector_etf_return_pct: r(x.v) })), top_gainers: rows.slice().sort((a, c) => c.v - a.v).slice(0, 8).map(row), top_decliners: rows.slice().sort((a, c) => a.v - c.v).slice(0, 8).map(row), most_active: rows.filter(x => x.rv).sort((a, c) => c.rv - a.rv).slice(0, 8).map(row), most_unusual: rows.slice().sort((a, c) => c.U - a.U).slice(0, 8).map(row), insights: mvInsights(rows).filter(i => i.trig).map(i => ({ title: i.title, findings: i.items.map(x => x.t), rule: i.rule })) };
  if (MV.sel && BY[MV.sel]) { const x = mvRow(BY[MV.sel], MV.per); const A = mvAnalog(MV.sel); f.selected_mover = { ...row(x), gap_pct: r(x.gap), day_range_pct: r(x.rng), return_20d_pct: r(x.r20), realized_vol_20d_pct: r(x.rv20), realized_vol_1y_pct: r(x.rv1y), next_earnings: x.nextE ? iso(x.nextE) : null, historical_similar_sessions: A ? { count: A.n, forward: A.a.map(y => ({ days: y.h, n: y.n, median_pct: r(y.med), pct_positive: r(y.pos) })) } : null, related: mvRelated(x).map(y => ({ ticker: BY[y.id].tk, relation: y.k, basis: y.why, return_pct: r(y.v) })) }; }
  return f;
}
{ const _ff2 = factsFor; factsFor = function (r, p) { const f = _ff2(r, p); if (r === 'movers') { try { Object.assign(f, mvFacts()); } catch (e) { f.note = 'Some movers figures could not be computed.'; } } return f; }; }

