      <div><span>Technical</span>${ck('hi', 'Near 52-week high')}${ck('lo', 'Near 52-week low')}${sel('a50', [['', '50-day MA: any'], ['above', 'Above 50-day MA'], ['below', 'Below 50-day MA']])}${ck('trend', 'Strong 20-day trend (≥6%)')}${ck('vexp', 'Volatility expansion (20D ≥ 1.3× 1Y)')}${ck('gap', 'Gap ≥ 2%')}</div>
      <div><span>Events</span>${ck('earn', 'Earnings reaction in the period')}${ck('surp', 'Earnings surprise ≥ 5%')}${ck('upE', 'Earnings in next 10 days')}${ck('guid', 'Guidance changes', 'Needs a company-events feed')}${ck('anr', 'Analyst revisions', 'Needs an estimates provider')}${ck('fil', 'Filings & corporate actions', 'Needs a filings feed')}</div>
      <div><span>Research</span>${sel('status', [['', 'Any status'], ['cat', 'Dated catalyst found'], ['nocat', 'No catalyst identified'], ['saved', 'Saved'], ['wl', 'On a watchlist']])}</div>
