    $('#g4', pg).innerHTML = mvList(rows.slice().sort((a, c) => c.U - a.U).slice(0, 10), 'u');
    const ins = mvInsights(rows); $('#mvIns', pg).innerHTML = `<p class="note" style="margin-top:0">Shown only when the data meets the stated rule.</p>${ins.filter(i => i.trig).map(i => `<div class="nx-ic"><h4>${esc(i.title)}</h4><ul class="mv-il">${i.items.map(x => `<li><a href="#" data-mv="${x.id}">${esc(BY[x.id].tk)}</a> ${esc(x.t)}</li>`).join('')}</ul><p class="note">${esc(i.rule)} Metrics: ${esc(i.metrics)}.</p></div>`).join('') || '<div class="empty"><b>No insights triggered</b>None of the rules below was met.</div>'}<details class="nx-not"><summary>Checked, not triggered (${ins.filter(i => !i.trig).length})</summary><ul>${ins.filter(i => !i.trig).map(i => `<li><b>${esc(i.title)}</b><span class="note">${esc(i.rule)}</span></li>`).join('')}</ul></details>`;
