  on(pg, 'click', '#mvSaveS', () => modal('Save as screen', `<label class="f"><span>Name</span><input class="inp" id="msn" maxlength="60" placeholder="e.g. Large caps falling >2% on 2× volume"></label>`, { actions: [{ label: 'Cancel', fn: c => c() }, { label: 'Save', cls: 'pri', fn: (c, mb) => { S.mvScreens.unshift({ id: uid(), name: $('#msn', mb).value.trim() || 'My screen', f: { ...f }, per: MV.per, uni: MV.uni }); S.mvScreens = S.mvScreens.slice(0, 20); save(); c(); drawF(); toast('Screen saved'); } }] }));
  on(pg, 'click', '[data-mv]', (e, b) => { if (e.target.closest('a.tk[data-sec]')) return; e.preventDefault(); mvOpen(b.dataset.mv); });
  pg.addEventListener('keydown', e => { const r = e.target.closest('.mv-r'); if (r && (e.key === 'Enter' || e.key === ' ')) { e.preventDefault(); mvOpen(r.dataset.mv); } if (e.key === 'Escape' && $('#mvDrawer') && !$('#mvDrawer').hidden) $('#mvClose').click(); });
  const ask = q => { const el = $$('.aip', pg).find(x => x.id !== 'mvAi'); if (!el) return toast('AI insights are turned off for your account by your organization', true); el.scrollIntoView({ behavior: 'smooth', block: 'start' }); runInsight(el, q); };
  $('#mvAsk', pg).onsubmit = e => { e.preventDefault(); const q = $('#mvQ', pg).value.trim(); if (q) ask(q); };
