  USNFP: { imp: 3, time: [8, 30, 'America/New_York'], assets: ['Rates', 'FX', 'Equities'], rx: ['YD.US2', 'YD.US10', 'FX.DXY', 'IX.SPX', 'IX.RUT'], why: 'Payrolls signal the strength of the labour market and growth; strong hiring can lift yields and the dollar, weak hiring the reverse.' },
  USUR: { imp: 2, time: [8, 30, 'America/New_York'], assets: ['Rates', 'Equities'], rx: ['YD.US2', 'IX.SPX', 'FX.DXY'], why: 'The unemployment rate is one half of the Federal Reserve\'s mandate and a measure of labour-market slack.' },
