  EAHICP: { imp: 3, time: [11, 0, 'Europe/Berlin'], assets: ['Rates', 'FX'], rx: ['YD.DE2', 'YD.DE10', 'FX.EURUSD', 'IX.SX5E'], why: 'Euro-area HICP is the ECB\'s target measure; it moves Bund yields and the euro.' },
  JPCPI: { imp: 2, time: [8, 30, 'Asia/Tokyo'], assets: ['Rates', 'FX'], rx: ['YD.JP10', 'FX.USDJPY', 'IX.NKY'], why: 'Japanese inflation feeds Bank of Japan normalisation expectations, the yen and JGB yields.' },
  CNPMI: { imp: 2, time: [9, 30, 'Asia/Shanghai'], assets: ['Commodities', 'Equities', 'FX'], rx: ['CM.HG1', 'IX.HSI', 'IX.SHCOMP', 'CM.CO1'], why: 'China\'s manufacturing PMI is a read on global industrial demand, closely watched by metals and emerging-market investors.' },
