  $('#calV', pg).onchange = e => { const v = S.calViews.find(x => x.id === e.target.value); if (v) { Object.assign(st, JSON.parse(JSON.stringify(v.st))); render(); } };
  $('#calReset', pg).onclick = () => { Object.assign(st, { view: 'table', range: 14, types: ['earn', 'eco'], extra: ['adm'], country: '', sector: '', asset: '', imp: 0, wl: false, mc: 0, sort: 'time', q: '', when: 'up' }); render(); };
  on(pg, 'click', '[data-ev]', (e, b) => { if (e.target.closest('a.tk[data-sec]') || e.target.closest('a[target]')) return; e.preventDefault(); calOpen(b.dataset.ev); });
