const FIW = { tab: 'ov', sel: null, f: { types: [], ccy: [], sort: 'ytw' }, cty: ['US', 'NG', 'UK', 'DE'], cmp: '1M', ctry: 'NG', iss: null, scen: 'p100', ask: '' };
const FI_TABS = [['ov', 'Overview'], ['curves', 'Yield curves & rates'], ['screen', 'Bond screener'], ['gov', 'Government & EM'], ['credit', 'Corporate credit'], ['auct', 'Auctions & issuance'], ['mm', 'Money markets'], ['port', 'Portfolio & risk'], ['funds', 'Funds & Treasuries']];
const QT = { eod: 'Simulated EOD', model: 'Model estimate', ind: 'Indicative (simulated)' };
const SETTLE = (() => { let t = END + DAY; while ([0, 6].includes(new Date(t).getUTCDay())) t += DAY; return t; })();
const yrs = (t, from = SETTLE) => (t - from) / (365.25 * DAY);
const RT = ['AAA', 'AA', 'A', 'BBB', 'BB', 'B', 'CCC']; const rIdx = r => RT.indexOf((r || '').replace(/[+-].*$/, '').split(' ')[0]);
