function govPts(cc, t = END) { const pts = []; MMR.filter(o => o.country === cc && o.id.startsWith('YD.')).forEach(o => { const v = valAt(o.id, t); if (v != null) pts.push([o.mat, v]); }); MATS.forEach(m => { const id = `YD.${cc}${m}`; if (BY[id]) { const v = valAt(id, t); if (v != null) pts.push([m, v]); } }); return pts.sort((a, b) => a[0] - b[0]); }
const KEYS = [2, 5, 10, 30];
function keyW(m, x) { const i = KEYS.indexOf(m); const lo = KEYS[i - 1], hi = KEYS[i + 1]; if (x <= m) return lo == null ? 1 : x <= lo ? 0 : (x - lo) / (m - lo); return hi == null ? 1 : x >= hi ? 0 : (hi - x) / (hi - m); }
