  if (FIW.tab === 'port') { const R = fiPortCalc(FIW.scen); f.portfolio = { value_usd: r(R.tot), ytw_pct: r(R.ytw), duration: r(R.dur), dv01_usd: r(R.dv), scenario: SCEN[FIW.scen][0], scenario_pnl_usd: r(R.dP), carry_12m_usd: r(R.carry), roll_12m_usd: r(R.roll), holdings: R.rows.map(x => ({ ticker: x.b.tk, value_usd: r(x.mv), dv01_usd: r(x.dv), scenario_pnl_usd: r(x.dP) })) }; }
  if (FIW.tab === 'gov' || FIW.tab === 'auct') f.nigeria_auctions = fiNgAuctions().filter(x => x.past).slice(-9).map(x => ({ date: iso(x.t), auction: x.title, offer_ngn_bn: r(x.offer / 1e9), bid_to_cover: r(x.btc), stop_rate_pct: r(x.stop) }));
  if (FIW.tab === 'credit') { const im = implied(FIW.iss); f.issuer = { name: BY[FIW.iss].name, implied_rating: im.r, gross_leverage: r(im.lev), interest_coverage: r(im.cov), fcf_usd: r(im.fcf), signals: fiCreditWatch().find(w => w.id === FIW.iss)?.sig || [] }; }
  if (FIW.sel) f.selected_bond = f.bonds.find(b => FIBY[FIW.sel] && b.ticker === FIBY[FIW.sel].tk);
