const GY = { tab: 'ov', cty: ['US', 'DE', 'UK', 'JP', 'NG'], ov: ['now', '1M'], date: null, mode: 'nom', hm: 'lvl', reg: '', cls: '', pair: ['US', 'DE'], ev: 'USCPI', win: 1, ten: 10, cc: 'NG', corrW: 120, scen: 'us50', mvP: '1W', mvM: 'ten', sel: null };
let GY_TABS = [['ov', 'Overview', 1], ['curves', 'Curve atlas', 1], ['heat', 'Heatmap', 1], ['mov', 'Movers', 1], ['spreads', 'Cross-country spreads', 2], ['real', 'Real yields', 2], ['cb', 'Central banks', 2], ['sov', 'Sovereign risk', 2], ['iss', 'Event analytics', 2], ['reg', 'Regimes & relationships', 2], ['em', 'EM & frontier', 3], ['port', 'Portfolio exposure', 3], ['classic', 'Matrix & history', 1]];
const GY_LV = { 1: ['Observe', 'What is happening?'], 2: ['Explain', 'Why might it be happening?'], 3: ['Investigate', 'What should I analyse next?'] };
const GY_FN = {}, GY_X = {}, GY_SEG = {};
const GY_META = { US: ['North America', 'Developed'], CA: ['North America', 'Developed'], UK: ['Europe', 'Developed'], DE: ['Europe', 'Developed'], FR: ['Europe', 'Developed'], IT: ['Europe', 'Developed'], JP: ['Asia-Pacific', 'Developed'], AU: ['Asia-Pacific', 'Developed'], CN: ['Asia-Pacific', 'Emerging'], IN: ['Asia-Pacific', 'Emerging'], ID: ['Asia-Pacific', 'Emerging'], BR: ['Latin America', 'Emerging'], MX: ['Latin America', 'Emerging'], TR: ['Middle East', 'Emerging'], EG: ['Africa', 'Frontier'], ZA: ['Africa', 'Emerging'], NG: ['Africa', 'Frontier'], KE: ['Africa', 'Frontier'], GH: ['Africa', 'Frontier'] };
const GY_INF = { US: ['EC.USCPI'], UK: ['EC.UKCPI'], DE: ['EC.EAHICP'], FR: ['EC.EAHICP'], IT: ['EC.EAHICP'], JP: ['EC.JPCPI'], IN: ['EC.INCPI'], CN: [null, .5], CA: [null, 2.2], AU: [null, 2.8], BR: [null, 5.0], MX: [null, 3.8], ID: [null, 2.4], TR: [null, 33], ZA: [null, 3.4], NG: [null, 20], KE: [null, 4.5], EG: [null, 12], GH: [null, 9] };
const GY_TGT = { US: '2%', UK: '2%', DE: '2%', FR: '2%', IT: '2%', JP: '2%', CA: '2%', AU: '2–3%', IN: '4% ±2', BR: '3%', MX: '3%' };
const GY_CB = { US: ['Federal Reserve', 'FOMC'], UK: ['Bank of England', 'BoE'], DE: ['European Central Bank', 'ECB'], FR: ['European Central Bank', 'ECB'], IT: ['European Central Bank', 'ECB'], JP: ['Bank of Japan', 'BoJ'], CN: ["People's Bank of China"], CA: ['Bank of Canada'], AU: ['Reserve Bank of Australia'], IN: ['Reserve Bank of India'], BR: ['Banco Central do Brasil'], MX: ['Banco de México'], ID: ['Bank Indonesia'], TR: ['Central Bank of the Republic of Türkiye'], ZA: ['South African Reserve Bank'], NG: ['Central Bank of Nigeria', 'CBN'], KE: ['Central Bank of Kenya'], EG: ['Central Bank of Egypt'], GH: ['Bank of Ghana'] };
const GY_TEN = [['3M', .25], ['1Y', 1], ['2Y', 2], ['5Y', 5], ['10Y', 10], ['20Y', 20], ['30Y', 30]];
const gyCC = () => [...new Set(YLD.map(o => o.country))];
const gyN = cc => COUNTRY[cc]?.n || cc;
const gyD = k => { const D = NX_D(); return D[Math.max(0, D.length - 1 - k)]; };
const GY_K = { '1D': 1, '1W': 5, '1M': 21, '3M': 63, '1Y': 252 };
function gyY(cc, ten, t = END) { // returns { v, q } with quote type
  if (ten === 20) { const a = gyY(cc, 10, t).v, b = gyY(cc, 30, t).v; return a != null && b != null ? { v: a + (b - a) * .5, q: 'interp' } : { v: null, q: 'na' }; }
  const id = ten === .25 ? `YD.${cc}3M` : ten === 1 ? `YD.${cc}1Y` : `YD.${cc}${ten}`; if (!BY[id]) return { v: null, q: 'na' }; const v = valAt(id, t); return { v, q: GY_META[cc]?.[1] === 'Frontier' ? 'ind' : 'obs', id };
}
const gyInf = (cc, t = END) => { const m = GY_INF[cc]; if (!m) return { v: null }; if (m[0]) return { v: valAt(m[0], t), src: BY[m[0]].name, kind: 'Latest CPI (YoY), ex-post' }; if (typeof mcAt === 'function') { const c = { DE: 'EU', FR: 'EU', IT: 'EU' }[cc] || cc; if (typeof MCC !== 'undefined' && MCC[c]) { const v = mcAt(c, 'CPI', t); if (v != null) return { v, src: 'Economic indicators (simulated macro panel)', kind: 'Latest CPI (YoY), simulated' }; } } return { v: m[1], src: 'Illustrative assumption', kind: 'Assumed inflation (no CPI series connected)' }; };
const gyReal = (cc, ten = 10, t = END) => { const y = gyY(cc, ten, t).v, i = gyInf(cc, t).v; return y == null || i == null ? null : y - i; };
const gyCcy = cc => { const id = COUNTRY[cc]?.fx; if (!id) return 'USD'; const tk = id.slice(3); return tk.startsWith('USD') ? tk.slice(3) : tk.slice(0, 3); };
const gyFx = (cc, t0, t1 = END) => { const id = COUNTRY[cc]?.fx; if (!id) return 0; const r = (valAt(id, t1) / valAt(id, t0) - 1) * 100; return id.slice(3).startsWith('USD') ? -r : r; }; // local currency % vs USD (+ = stronger)
const GY_POL = { UK: 3.75, DE: 2.0, FR: 2.0, IT: 2.0, JP: .75, CN: 1.4, CA: 2.25, AU: 3.35, IN: 5.25, BR: 14.25, MX: 8.0, ID: 5.5, TR: 37.0, ZA: 7.0, KE: 10.5, EG: 23.0, GH: 21.0 };
function gyPol(cc, t = END) { if (cc === 'US') return valAt('EC.FEDF', t) - .125; if (cc === 'NG') return valAt('MM.NGMPR', t); return GY_POL[cc] ?? null; }
function gyPath(cc, t = END) { const p = gyPol(cc, t); if (p == null) return null; if (BY[`YD.${cc}3M`] && BY[`YD.${cc}1Y`]) { const y3 = govY(cc, .25, t); return [3, 6, 12, 24].map(m => ({ m, r: govY(cc, m / 12 + .25, t) - (y3 - p) })); }
  const g = gyY(cc, 2, t).v - .15 - p; const term = p + 2 * g; return [3, 6, 12, 24].map(m => ({ m, r: p + (term - p) * m / 24 })); } // no bill curve: linear path whose 2-year average matches the 2Y yield less an assumed 15 bp term premium
const QB = q => q === 'interp' ? '<span class="gy-q" title="Interpolated between 10Y and 30Y">interp.</span>' : q === 'ind' ? '<span class="gy-q ind" title="Indicative frontier-market quote (simulated)">ind.</span>' : '';
function gyDiv(v, mx) { if (v == null) return 'background:var(--well)'; const a = Math.min(1, Math.abs(v) / (mx || 1)); return `background:color-mix(in srgb,var(${v > 0 ? '--dn' : '--up'}) ${Math.round(8 + a * 52)}%,var(--panel))`; }
function gySeq(v, lo, hi, arr) { if (v == null) return 'background:var(--well)'; const a = arr && arr.length > 1 ? arr.filter(x => x < v).length / (arr.length - 1) : hi > lo ? (v - lo) / (hi - lo) : .5; return `background:color-mix(in srgb,var(--violet) ${Math.round(6 + a * 60)}%,var(--panel))`; }
const gyRows = () => gyCC().filter(cc => (!GY.reg || GY_META[cc]?.[0] === GY.reg) && (!GY.cls || GY_META[cc]?.[1] === GY.cls));
const gyFilt = () => `<div class="row" style="gap:6px;flex-wrap:wrap"><select class="inp sm" data-gy="reg"><option value="">All regions</option>${['North America', 'Europe', 'Asia-Pacific', 'Latin America', 'Middle East', 'Africa'].map(r => `<option ${GY.reg === r ? 'selected' : ''}>${r}</option>`).join('')}</select><select class="inp sm" data-gy="cls"><option value="">All markets</option>${['Developed', 'Emerging', 'Frontier'].map(r => `<option ${GY.cls === r ? 'selected' : ''}>${r}</option>`).join('')}</select></div>`;

/* ---------- OVERVIEW ---------- */
function gyOverview(el) {
  const ccs = gyRows(); const t1 = gyD(1), t5 = gyD(5), t21 = gyD(21);
  const all = ccs.flatMap(cc => [2, 5, 10, 30].map(m => ({ cc, m, id: `YD.${cc}${m}` })).filter(x => BY[x.id]).map(x => ({ ...x, d1: (valAt(x.id, END) - valAt(x.id, t1)) * 100, d5: (valAt(x.id, END) - valAt(x.id, t5)) * 100, d21: (valAt(x.id, END) - valAt(x.id, t21)) * 100 })));
  const slope = ccs.map(cc => { const s = t => (gyY(cc, 10, t).v - gyY(cc, 2, t).v) * 100; return { cc, s: s(END), ch: s(END) - s(t21) }; });
  const real = ccs.map(cc => ({ cc, r: gyReal(cc), k: gyInf(cc).kind })).filter(x => x.r != null).sort((a, b) => b.r - a.r);
  const pol = ccs.map(cc => { const p = gyPath(cc), p0 = gyPath(cc, t21); return p && p0 ? { cc, ch12: p[2].r - gyPol(cc), rep: (p[2].r - p0[2].r) * 100 } : null; }).filter(Boolean).sort((a, b) => a.ch12 - b.ch12);
  const sov = Object.keys(SOV).map(k => { const xs = fiAll().filter(a => a.b.iss === k && a.b.kind === 'Eurobond'); return { k, s: xs.reduce((q, a) => q + a.spr, 0) / (xs.length || 1), ch: xs.reduce((q, a) => q + (a.sd21 ?? 0), 0) / (xs.length || 1) }; });
  const cat = [...calAll().filter(e => !e.past && ['eco', 'cb', 'auc'].includes(e.type) && e.t <= END + 14 * DAY), ...fiNgAuctions().filter(a => !a.past).slice(0, 3).map(a => ({ t: a.t, title: a.title, type: 'auc', imp: 2 })), ...fiCbn().slice(0, 1).map(t => ({ t, title: 'Central Bank of Nigeria MPC (simulated date)', type: 'cb', imp: 3 }))].sort((a, b) => a.t - b.t).slice(0, 10);
  el.innerHTML = `<div class="fi-tb">${gyFilt()}<span class="note">${ccs.length} markets · ${simB('SIM EOD')} · frontier quotes are indicative</span></div>
    <section class="panel"><header class="ph"><span class="pt">Global benchmark yields</span><span class="pm">Click a value for its history</span></header><div class="pb flush"><div class="tw"><table class="t dense gy-bm"><thead><tr><th>Market</th><th class="r">2Y</th><th class="r">5Y</th><th class="r">10Y</th><th class="r">30Y</th><th class="r">10Y 1D</th><th class="r">10Y 1M</th><th>10Y · 3M</th><th class="r">2s10s</th><th class="r">Real 10Y</th></tr></thead><tbody>${ccs.map(cc => { const y10 = `YD.${cc}10`; const D = NX_D(); const sp = spark(D.slice(-63).map(t => valAt(y10, t)), 70, 20); return `<tr><td><b>${esc(gyN(cc))}</b><div class="sub">${GY_META[cc]?.join(' · ')}</div></td>${[2, 5, 10, 30].map(m => { const x = gyY(cc, m); return `<td class="r">${x.v == null ? '—' : `<a href="#" data-gyc="${cc}|${m}">${nf(x.v, 2)}%</a>${QB(x.q)}`}</td>`; }).join('')}<td class="r ${cls(-nxChg(y10, END))}">${bpf(nxChg(y10, END), 1)}</td><td class="r ${cls(-nxWin(y10, t21, END))}">${bpf(nxWin(y10, t21, END), 0)}</td><td>${sp}</td><td class="r">${sgn((gyY(cc, 10).v - gyY(cc, 2).v) * 100, 0)}</td><td class="r">${gyReal(cc) == null ? '—' : nf(gyReal(cc), 2) + '%'}${GY_INF[cc]?.[0] ? '' : '<sup title="Uses an illustrative inflation assumption">a</sup>'}</td></tr>`; }).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Local-currency government yields. Real 10Y = nominal 10Y minus latest CPI (ex-post) or, marked <sup>a</sup>, an illustrative inflation assumption where no CPI series is connected. Source: Superfinancials simulator, end of day ${fd(END)}.</p></div></section>
    <div class="fi-q">
      <div class="fi-qc"><h4>Yield movers · 1 week</h4><div class="fi-two"><div><h6>Rises</h6>${all.slice().sort((a, b) => b.d5 - a.d5).slice(0, 6).map(x => `<div class="fi-r"><a href="#" data-gyc="${x.cc}|${x.m}">${esc(x.cc)} ${x.m}Y</a><b class="dn">${bpf(x.d5, 0)}</b></div>`).join('')}</div><div><h6>Falls</h6>${all.slice().sort((a, b) => a.d5 - b.d5).slice(0, 6).map(x => `<div class="fi-r"><a href="#" data-gyc="${x.cc}|${x.m}">${esc(x.cc)} ${x.m}Y</a><b class="up">${bpf(x.d5, 0)}</b></div>`).join('')}</div></div></div>
      <div class="fi-qc"><h4>Curve watch</h4><h6>Steepest · flattest 2s10s</h6>${[...slope.slice().sort((a, b) => b.s - a.s).slice(0, 3), ...slope.slice().sort((a, b) => a.s - b.s).slice(0, 3)].map(x => `<div class="fi-r"><span>${esc(gyN(x.cc))}</span><b>${sgn(x.s, 0)} bp</b>${x.s < 0 ? '<span class="fi-shape inv">inverted</span>' : ''}</div>`).join('')}<h6>Fastest slope change · 1M</h6>${slope.slice().sort((a, b) => Math.abs(b.ch) - Math.abs(a.ch)).slice(0, 3).map(x => `<div class="fi-r"><span>${esc(gyN(x.cc))}</span><b>${bpf(x.ch, 0)}</b><span class="note">${x.ch > 0 ? 'steepening' : 'flattening'}</span></div>`).join('')}</div>
      <div class="fi-qc"><h4>Real-yield ranking · 10Y</h4>${real.slice(0, 8).map((x, i) => `<div class="fi-r"><span>${i + 1}. ${esc(gyN(x.cc))}${GY_INF[x.cc]?.[0] ? '' : ' <sup>a</sup>'}</span><b class="${cls(x.r)}">${nf(x.r, 2)}%</b></div>`).join('')}<p class="note">Method: nominal minus inflation as labelled. <sup>a</sup> = illustrative assumption.</p></div>
      <div class="fi-qc"><h4>Policy divergence · implied 12M change</h4>${[...pol.slice(0, 4), ...pol.slice(-3)].map(x => `<div class="fi-r"><span>${esc(gyN(x.cc))}</span><b class="${cls(-x.ch12)}">${bpf(x.ch12 * 100, 0)}</b><span class="note">${bpf(x.rep, 0)} repriced 1M</span></div>`).join('')}<p class="note">Approximate market pricing from simulated bill/2Y yields, not OIS. Not objective probabilities.</p></div>
      <div class="fi-qc"><h4>Sovereign risk monitor</h4>${sov.map(x => `<div class="fi-r"><span>${esc(SOV[x.k].n)} USD Eurobonds</span><b>${nf(x.s, 0)} bp</b><i class="${cls(-x.ch)}">${bpf(x.ch, 0)} 1M</i></div>`).join('')}<p class="note">Spreads over Treasuries from simulated Eurobond prices. CDS and agency ratings: not connected.</p></div>
      <div class="fi-qc"><h4>Upcoming catalysts · 14 days</h4><ul class="fi-ul">${cat.map(e => `<li><b>${fd(e.t, { day: '2-digit', month: 'short' })}</b> ${esc(e.title)}</li>`).join('')}</ul><p class="note">Simulated schedules; see Issuance &amp; events.</p></div></div>`;
}

/* ---------- CURVE EXPLORER ---------- */
function gyCurves(el) {
  const ccs = gyCC(); const OV = [['now', 'Today', 0], ['1D', 'Yesterday', 1], ['1W', '1 week ago', 5], ['1M', '1 month ago', 21], ['3M', '3 months ago', 63], ['1Y', '1 year ago', 252], ['5Y', '5 years ago', 1260], ['date', 'Chosen date', null]];
  const tOf = k => k === 'date' ? (GY.date || gyD(126)) : gyD(OV.find(o => o[0] === k)[2]);
  const ptsOf = (cc, t) => { const p = GY_TEN.map(([l, m]) => [m, m === 20 ? null : gyY(cc, m, t).v]).filter(x => x[1] != null); if (GY.mode === 'real') { const i = gyInf(cc, t).v; return i == null ? [] : p.map(([m, y]) => [m, y - i]); } if (GY.mode === 'fwd') { const out = []; for (let k = 1; k < p.length; k++) { const [a, ya] = p[k - 1], [b, yb] = p[k]; out.push([(a + b) / 2, ((Math.pow(1 + yb / 100, b) / Math.pow(1 + ya / 100, a)) ** (1 / (b - a)) - 1) * 100]); } return out; } return p; };
  const sets = []; GY.cty.forEach((cc, i) => GY.ov.forEach((k, j) => { const pts = ptsOf(cc, tOf(k)); if (pts.length) sets.push({ label: `${gyN(cc)} · ${OV.find(o => o[0] === k)[1]}`, color: PAL[i % 8], dash: j > 0, pts }); }));
  const fc = GY.cty.flatMap(cc => { const xs = fiAll().filter(a => a.b.iss === cc && a.b.kind === 'Eurobond').sort((a, b) => a.yrs - b.yrs); return xs.length ? [{ cc, xs }] : []; });
  const segM = GY.cty.map(cc => { const t0 = gyD(21); return { cc, cells: GY_TEN.filter(([, m]) => m !== 20).map(([l, m]) => { const id = gyY(cc, m).id; if (!id) return { l, v: null }; const s = series(id); const i = s.c.length - 1; const ch = (s.c[i] - s.c[Math.max(0, i - 21)]) * 100; const xs = []; for (let k = i - 252; k < i; k += 21) if (k > 21) xs.push((s.c[k] - s.c[k - 21]) * 100); const m0 = xs.reduce((a, b) => a + b, 0) / xs.length, sd = Math.sqrt(xs.reduce((a, b) => a + (b - m0) ** 2, 0) / Math.max(1, xs.length - 1)); return { l, v: ch, z: sd ? (ch - m0) / sd : 0 }; }) }; });
  const reg4 = (cc, k) => { const t0 = gyD(GY_K[k] || 21); const L = t => GY_TEN.filter(([, m]) => m !== 20).map(([, m]) => gyY(cc, m, t).v).filter(v => v != null); const lv = t => { const x = L(t); return x.reduce((a, b) => a + b, 0) / x.length; }; const sl = t => gyY(cc, 10, t).v - gyY(cc, 2, t).v; const dl = (lv(END) - lv(t0)) * 100, ds = (sl(END) - sl(t0)) * 100; return { dl, ds, lab: Math.abs(ds) < 3 ? (dl > 0 ? 'Parallel rise (bear)' : 'Parallel fall (bull)') : `${dl > 0 ? 'Bear' : 'Bull'} ${ds > 0 ? 'steepening' : 'flattening'}` }; };
  const pctl = (cc, f) => { const D = NX_D(); const xs = []; for (let k = D.length - 1; k >= Math.max(300, 0); k -= 5) { const v = f(D[k]); if (v != null && isFinite(v)) xs.push(v); } const now = f(END); return xs.filter(v => v <= now).length / xs.length * 100; };
  el.innerHTML = `<div class="fi-tb"><div class="row" style="gap:6px;flex-wrap:wrap">${ccs.map(cc => `<button class="chip ${GY.cty.includes(cc) ? 'on' : ''}" data-gycc="${cc}">${esc(gyN(cc))}</button>`).join('')}</div></div>
    <div class="fi-tb"><div class="row" style="gap:6px;flex-wrap:wrap"><span class="note">Overlay</span>${OV.map(([k, l]) => `<button class="chip ${GY.ov.includes(k) ? 'on' : ''}" data-gyov="${k}">${l}</button>`).join('')}<input class="inp sm" type="date" id="gyDate" value="${iso(GY.date || gyD(126))}" aria-label="Historical date"></div><div class="row">${seg('gymode', [['nom', 'Nominal'], ['real', 'Real (approx.)'], ['fwd', 'Forwards']], GY.mode)}</div></div>
    <div class="grid"><section class="panel c8"><header class="ph"><span class="pt">Local-currency government curves</span><span class="pm">${QL('eod')}</span></header><div class="pb"><div id="gyCv"></div><div class="nx-leg">${sets.map(s => `<span><i style="background:${s.color};${s.dash ? 'opacity:.55' : ''}"></i>${esc(s.label)}</span>`).join('')}</div><p class="note">${GY.mode === 'real' ? 'Real = nominal minus latest CPI or an illustrative assumption (method per country on the Real yields tab). ' : GY.mode === 'fwd' ? 'Forward rates between adjacent tenors, from yields treated as annual zero rates (approximation). ' : ''}Swap/OIS curves and on-the-run vs off-the-run splits are not connected. Tenors shown only where the market has data.</p></div></section>
      <section class="panel c4"><header class="ph"><span class="pt">Foreign-currency sovereign curves (USD)</span></header><div class="pb">${fc.length ? `<div id="gyFc"></div><p class="note">USD Eurobond yields, shown separately from local-currency curves: different currency, investor base and legal terms.</p>` : '<p class="note">Select Nigeria, South Africa, Kenya, Egypt or Ghana to see their USD Eurobond curves.</p>'}</div></section></div>
    <section class="panel"><header class="ph"><span class="pt">Curve analytics</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Market</th><th class="r">2s10s</th><th class="r">3m10y</th><th class="r">5s30s</th><th class="r">Fly 2·5·10</th><th class="r">2s10s pctl</th><th>1W regime</th><th>1M regime</th></tr></thead><tbody>${GY.cty.map(cc => { const g = m => gyY(cc, m).v; const r1 = reg4(cc, '1W'), r2 = reg4(cc, '1M'); return `<tr><td>${esc(gyN(cc))}</td><td class="r">${sgn((g(10) - g(2)) * 100, 0)}</td><td class="r">${g(.25) == null ? '—' : sgn((g(10) - g(.25)) * 100, 0)}</td><td class="r">${g(30) == null ? '—' : sgn((g(30) - g(5)) * 100, 0)}</td><td class="r">${sgn((2 * g(5) - g(2) - g(10)) * 100, 0)}</td><td class="r">${nf(pctl(cc, t => gyY(cc, 10, t).v - gyY(cc, 2, t).v), 0)}th</td><td><span class="gy-rg ${r1.lab.split(' ')[0].toLowerCase()}">${r1.lab}</span></td><td><span class="gy-rg ${r2.lab.split(' ')[0].toLowerCase()}">${r2.lab}</span></td></tr>`; }).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Bull = yields falling, bear = yields rising; steepening/flattening = change in 10Y − 2Y. Percentile over the full simulated history (10 years of weekly observations; a 20-year lookback needs a longer licensed series).</p></div></section>
      <section class="panel"><header class="ph"><span class="pt">Unusual segment moves · 1M</span></header><div class="pb"><div class="tw"><table class="fi-hm"><thead><tr><th></th>${GY_TEN.filter(([, m]) => m !== 20).map(([l]) => `<th>${l}</th>`).join('')}</tr></thead><tbody>${segM.map(r => `<tr><th>${esc(r.cc)}</th>${r.cells.map(c => `<td style="${gyDiv(c.v, 60)};${Math.abs(c.z || 0) >= 2 ? 'box-shadow:inset 0 0 0 2px var(--violet)' : ''}" title="${c.v == null ? 'No data' : `${bpf(c.v, 0)} · z ${nf(c.z, 1)} vs 1Y of monthly moves`}">${c.v == null ? '—' : sgn(c.v, 0)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note">bp change over 1 month; outlined = more than 2 standard deviations from the past year's monthly moves.</p></div></section>`;
  fiCurveChart($('#gyCv', el), sets, 320);
  if ($('#gyFc', el)) xyChart($('#gyFc', el), { h: 260, xlab: 'Years to maturity', ylab: 'Yield %', xf: v => nf(v, 0), yf: v => nf(v, 1) + '%', series: fc.map((f, i) => ({ label: gyN(f.cc) + ' USD', color: PAL[GY.cty.indexOf(f.cc) % 8], line: true, points: f.xs.map(a => ({ x: a.yrs, y: a.ytm, name: a.b.name, extra: `spread ${nf(a.spr, 0)} bp` })) })) });
}

/* ---------- HEATMAP ---------- */
function gyHeat(el) {
  const ccs = gyRows(); const M = GY.hm; let cols = GY_TEN, val, fmt = v => nf(v, 2), scale = 'seq', note = '';
  if (M === 'shape') { cols = [['2s10s', 0], ['3m10y', 1], ['5s30s', 2], ['Fly', 3]]; val = (cc, i) => { const g = m => gyY(cc, m).v; const r = [g(10) != null && g(2) != null ? (g(10) - g(2)) * 100 : null, g(.25) != null ? (g(10) - g(.25)) * 100 : null, g(30) != null ? (g(30) - g(5)) * 100 : null, (2 * g(5) - g(2) - g(10)) * 100][i]; return r; }; fmt = v => sgn(v, 0); scale = 'div'; note = 'bp. Negative 2s10s / 3m10y = inverted.'; }
  else { val = (cc, i) => { const m = GY_TEN[i][1]; const x = gyY(cc, m); if (x.v == null) return null; if (M === 'lvl') return x.v; if (['d1', 'd5', 'd21'].includes(M)) { const k = { d1: 1, d5: 5, d21: 21 }[M]; const p = gyY(cc, m, gyD(k)).v; return p == null ? null : (x.v - p) * 100; } if (M === 'real') { const i2 = gyInf(cc).v; return i2 == null ? null : x.v - i2; } if (M === 'spr') { const b = gyY(GY.pair[0] === cc ? 'DE' : 'US', m).v; return b == null ? null : (x.v - b) * 100; } if (M === 'vol') { if (!x.id) return null; const xs = []; for (let k = 1; k <= 60; k++) { const v = nxChg(x.id, gyD(k)); if (v != null) xs.push(v); } const mm = xs.reduce((a, b) => a + b, 0) / xs.length; return Math.sqrt(xs.reduce((a, b) => a + (b - mm) ** 2, 0) / (xs.length - 1)); } }; if (M.startsWith('d')) { fmt = v => sgn(v, 1); scale = 'div'; note = 'bp change; red = yields up. Scale relative to this period.'; } if (M === 'spr') { fmt = v => sgn(v, 0); scale = 'seq'; note = 'bp over the U.S. Treasury of the same tenor (U.S. row vs Germany).'; } if (M === 'vol') { fmt = v => nf(v, 1); note = 'Standard deviation of daily changes over 60 sessions, bp. Implied rate volatility (MOVE-type) only for the U.S.'; } if (M === 'real') note = 'Nominal minus latest CPI or illustrative inflation assumption.'; }
  const vals = ccs.map(cc => cols.map((c, i) => val(cc, i))); const flat = vals.flat().filter(v => v != null); const lo = Math.min(...flat), hi = Math.max(...flat), mx = Math.max(...flat.map(Math.abs));
  el.innerHTML = `<div class="fi-tb"><div class="row" style="gap:8px;flex-wrap:wrap">${seg('gyhm', [['lvl', 'Yield'], ['d1', '1D Δ'], ['d5', '1W Δ'], ['d21', '1M Δ'], ['real', 'Real'], ['spr', 'vs UST'], ['shape', 'Curve shape'], ['vol', 'Volatility']], M)}</div>${gyFilt()}</div>
    <section class="panel"><header class="ph"><span class="pt">Global yield heatmap</span><span class="pm">${QL('eod')}</span></header><div class="pb"><div class="tw"><table class="gy-hm"><thead><tr><th>Market</th><th>Class</th>${cols.map(c => `<th>${c[0]}</th>`).join('')}</tr></thead><tbody>${ccs.map((cc, r) => `<tr><th>${esc(gyN(cc))}</th><td class="sub">${GY_META[cc]?.[1]}</td>${cols.map((c, i) => { const v = vals[r][i]; const q = M !== 'shape' ? gyY(cc, c[1]).q : ''; return `<td ${v == null ? '' : `data-gyc="${cc}|${c[1]}"`} style="${scale === 'div' ? gyDiv(v, mx) : gySeq(v, lo, hi, flat)}" class="${q === 'interp' ? 'interp' : ''}">${v == null ? '—' : fmt(v)}</td>`; }).join('')}</tr>`).join('')}</tbody></table></div><p class="note">${note} Colour shows each cell's rank among the values shown for this metric (percentile scale, so outliers such as Türkiye don't wash out the rest); diverging metrics are scaled to the largest absolute move. Dotted cells are interpolated (20Y). Click a cell for its history, curve and related releases.</p></div></section>`;
}

/* ---------- cell drawer ---------- */
function gyOpen(cc, m) {
  m = +m; const pg = $('#main .page'); let dr = $('#gyDrawer'); if (!dr) { dr = document.createElement('aside'); dr.id = 'gyDrawer'; dr.className = 'mv-drawer'; pg.append(dr); }
  const x = gyY(cc, m); const id = x.id; const lab = GY_TEN.find(t => t[1] === m)?.[0] || m + 'Y';
  const rel = calAll().filter(e => e.type === 'eco' && (e.country === cc || (['DE', 'FR', 'IT'].includes(cc) && e.country === 'EU'))).sort((a, b) => Math.abs(a.t - END) - Math.abs(b.t - END)).slice(0, 5);
  dr.innerHTML = `<header class="mv-dh"><div><span class="nx-lab">${esc(GY_META[cc]?.join(' · '))}</span><h2>${esc(gyN(cc))} ${lab}</h2><div class="note">${x.v == null ? 'No data' : nf(x.v, 3) + '%'} · ${x.q === 'interp' ? 'interpolated from 10Y and 30Y' : x.q === 'ind' ? 'indicative frontier quote' : 'observed'} · simulated end of day ${fd(END)} · local currency</div></div><button class="btn sm ghost" id="gyClose">✕</button></header><div class="mv-db">
    <section><h4>History · 1 year</h4><div id="gyH"></div></section><section><h4>Curve</h4><div id="gyC"></div></section>
    <section><h4>Related macro releases</h4>${rel.length ? `<ul class="mv-its">${rel.map(e => `<li>${fd(e.t)} · ${esc(e.title)} ${e.past ? `· actual ${eUnit(e.eco, e.d.act)} vs ${eUnit(e.eco, e.d.cons)}` : '· upcoming'}</li>`).join('')}</ul>` : '<p class="note">No connected releases for this market.</p>'}</section>
    <section><h4>Source &amp; conventions</h4><dl class="kl"><div><dt>Quote type</dt><dd>${x.q === 'interp' ? 'Calculated (interpolated)' : x.q === 'ind' ? 'Indicative (simulated)' : 'Observed (simulated EOD)'}</dd></div><div><dt>Currency · tenor</dt><dd>Local currency · ${lab}</dd></div><div><dt>Production sources</dt><dd>National debt office, central bank, exchange or licensed provider</dd></div></dl></section>
    ${id ? `<div class="mv-act"><a class="btn sm" data-sec="${id}" href="#sec.${id}">Security page</a></div>` : ''}</div>`;
  dr.hidden = false;
  if (id) new TChart($('#gyH', dr), buildCompare([id], { range: '1Y', h: 200 }).cfg); else $('#gyH', dr).innerHTML = `<p class="note">Interpolated point: see the 10Y and 30Y series.</p>`;
  fiCurveChart($('#gyC', dr), [{ label: 'Today', color: 'var(--s1)', pts: govPts(cc) }, { label: '1M ago', color: 'var(--s2)', dash: true, pts: govPts(cc, gyD(21)) }], 200);
  $('#gyClose', dr).onclick = () => dr.hidden = true;
}

/* ---------- SPREADS ---------- */
function gySpreads(el) {
  const ccs = gyCC(); const [a, b] = GY.pair; const ten = GY.ten; const D = NX_D();
  const sp = t => { const x = gyY(a, ten, t).v, y = gyY(b, ten, t).v; return x == null || y == null ? null : (x - y) * 100; };
  const hist = []; for (let k = D.length - 1; k >= 260; k -= 5) { const v = sp(D[k]); if (v != null) hist.push(v); } const now = sp(END); const avg = hist.reduce((q, v) => q + v, 0) / hist.length; const pct = hist.filter(v => v <= now).length / hist.length * 100;
  const ch = []; for (let k = 1; k <= 60; k++) { const v1 = sp(gyD(k - 1)), v0 = sp(gyD(k)); if (v1 != null && v0 != null) ch.push(v1 - v0); } const vol = Math.sqrt(ch.reduce((q, v) => q + v * v, 0) / ch.length); const tr = now - sp(gyD(63));
  const fxr = cc => ({ r1y: gyFx(cc, gyD(252)), v: COUNTRY[cc]?.fx ? annVol(COUNTRY[cc].fx) : 0 });
  const sr = cc => gyY(cc, .25).v ?? gyY(cc, 2).v; const hedged = gyY(a, ten).v - (sr(a) - sr(b));
  const infd = (gyInf(a).v ?? 0) - (gyInf(b).v ?? 0); const pold = (gyPol(a) ?? 0) - (gyPol(b) ?? 0); const fa = fxr(a), fb = fxr(b);
  const ebA = fiAll().filter(x => x.b.iss === a && x.b.kind === 'Eurobond'); const loc = gyY(a, 5).v; const eb5 = ebA.sort((x, y) => Math.abs(x.yrs - 5) - Math.abs(y.yrs - 5))[0];
  const pairs = [['US', 'DE'], ['US', 'UK'], ['JP', 'US'], ['IT', 'DE'], ['FR', 'DE'], ['BR', 'US'], ['ZA', 'US'], ['IN', 'US'], ['MX', 'US'], ['NG', 'US'], ['KE', 'US'], ['EG', 'US']];
  el.innerHTML = `<div class="fi-tb"><div class="row" style="gap:6px;align-items:center"><select class="inp sm" data-gyp="0">${ccs.map(c => `<option value="${c}" ${c === a ? 'selected' : ''}>${esc(gyN(c))}</option>`).join('')}</select><span>minus</span><select class="inp sm" data-gyp="1">${ccs.map(c => `<option value="${c}" ${c === b ? 'selected' : ''}>${esc(gyN(c))}</option>`).join('')}</select>${seg('gyten', [['2', '2Y'], ['5', '5Y'], ['10', '10Y']], String(ten))}</div></div>
    <div class="grid"><section class="panel c7"><header class="ph"><span class="pt">${esc(gyN(a))} − ${esc(gyN(b))} ${ten}Y</span><span class="pm">${QL('eod')}</span></header><div class="pb"><div class="fi-kpis"><div><span>Differential</span><b>${sgn(now, 0)} bp</b></div><div><span>History avg · pctl</span><b>${sgn(avg, 0)}</b><small>${nf(pct, 0)}th percentile</small></div><div><span>Volatility · 3M trend</span><b>${nf(vol, 1)}</b><small>bp/day · ${bpf(tr, 0)} 3M</small></div><div><span>Policy-rate diff.</span><b>${sgn(pold * 100, 0)}</b><small>bp (simulated policy)</small></div><div><span>Inflation diff.</span><b>${sgn(infd, 1)}</b><small>pts</small></div><div><span>FX 1Y · ${gyCcy(a)} vs ${gyCcy(b)}</span><b>${a === b || gyCcy(a) === gyCcy(b) ? '—' : pc(((1 + fa.r1y / 100) / (1 + fb.r1y / 100) - 1) * 100, 1)}</b><small>${gyCcy(a) === gyCcy(b) ? 'same currency' : `+ = ${gyCcy(a)} stronger`}</small></div></div><div id="gySp"></div>
      <h6>Four ways to compare</h6><div class="tw"><table class="t dense"><thead><tr><th>Measure</th><th class="r">${esc(a)}</th><th class="r">${esc(b)}</th><th>Method</th></tr></thead><tbody><tr><td>1. Nominal yield (local currency)</td><td class="r">${nf(gyY(a, ten).v, 2)}%</td><td class="r">${nf(gyY(b, ten).v, 2)}%</td><td class="sub">Observed (simulated)</td></tr><tr><td>2. Estimated real yield</td><td class="r">${nf(gyReal(a, ten), 2)}%</td><td class="r">${nf(gyReal(b, ten), 2)}%</td><td class="sub">Nominal − ${GY_INF[a]?.[0] ? 'CPI' : 'assumed inflation'}</td></tr><tr><td>3. Hedged into ${gyCcy(b)}</td><td class="r">${nf(hedged, 2)}%</td><td class="r">${nf(gyY(b, ten).v, 2)}%</td><td class="sub">CIP approx.: − (short-rate differential)</td></tr><tr><td>4. 1Y return in ${gyCcy(b)}, your FX scenario</td><td class="r" id="gyTR">—</td><td class="r">${nf(gyY(b, ten).v, 2)}%</td><td class="sub"><label>${gyCcy(a)} move vs ${gyCcy(b)} % <input class="inp sm" id="gyFx" type="number" step="any" value="-5" style="width:64px">%</label></td></tr></tbody></table></div><p class="note">A large differential is not an arbitrage: FX moves, hedge costs, sovereign risk, transaction costs, taxes and liquidity can remove it. Ratings and CDS: not connected.</p></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">Common pairs · ${ten}Y</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Pair</th><th class="r">Spread</th><th class="r">1M Δ</th><th class="r">Pctl</th></tr></thead><tbody>${pairs.filter(([x, y]) => gyY(x, ten).v != null && gyY(y, ten).v != null).map(([x, y]) => { const s = t => (gyY(x, ten, t).v - gyY(y, ten, t).v) * 100; const hs = []; for (let k = D.length - 1; k >= 260; k -= 10) hs.push(s(D[k])); const n0 = s(END); return `<tr data-gypair="${x}|${y}"><td><a href="#">${x} − ${y}</a></td><td class="r">${sgn(n0, 0)}</td><td class="r ${cls(-(n0 - s(gyD(21))))}">${bpf(n0 - s(gyD(21)), 0)}</td><td class="r">${nf(hs.filter(v => v <= n0).length / hs.length * 100, 0)}th</td></tr>`; }).join('')}</tbody></table></div></div></section></div>
    ${ebA.length ? `<section class="panel"><header class="ph"><span class="pt">${esc(gyN(a))}: local-currency vs USD Eurobond (~5Y)</span></header><div class="pb"><div class="fi-kpis"><div><span>Local ${esc(a)} 5Y</span><b>${nf(loc, 2)}%</b></div><div><span>USD Eurobond ~${nf(eb5.yrs, 1)}Y</span><b>${nf(eb5.ytm, 2)}%</b></div><div><span>Gap</span><b>${sgn((loc - eb5.ytm) * 100, 0)} bp</b></div><div><span>Implied breakeven depreciation</span><b>${nf(((1 + loc / 100) / (1 + eb5.ytm / 100) - 1) * 100, 1)}%/yr</b></div></div><p class="note">The local yield is in local currency, the Eurobond in USD. The gap mainly reflects expected depreciation, FX risk premia, liquidity and convertibility; not directly comparable without an FX scenario.</p></div></section>` : ''}`;
  xyChart($('#gySp', el), { h: 200, xlab: '', ylab: 'bp', xf: v => fd(v, { month: 'short', year: '2-digit' }), yf: v => nf(v, 0), series: [{ label: 'Spread', color: 'var(--s1)', line: true, r: 0, points: D.slice(-504).filter((_, i) => i % 3 === 0).map(t => ({ x: t, y: sp(t) })).filter(p => p.y != null) }] });
  const tr1 = () => { const f = +$('#gyFx', el).value; $('#gyTR', el).textContent = pc(((1 + gyY(a, ten).v / 100) * (1 + f / 100) - 1) * 100, 2); }; $('#gyFx', el).oninput = tr1; tr1();
}

/* ---------- REAL YIELDS ---------- */
function gyReal_(el) {
  const ccs = gyRows(); const tip = fiAll().find(a => a.b.tk === 'TIPS35'); const nom = govY('US', tip.yrs); const be10 = nom - tip.y;
  const rel = ecoRels(BY['EC.USCPI']).past; const D = NX_D(); const around = rel.map(r => { const i = bsLE(D, r.t); return i > 1 && i + 1 < D.length ? { t: r.t, surp: r.surp, nomCh: (govY('US', 10, D[i + 1]) - govY('US', 10, D[i - 1])) * 100, realCh: (bY(tip.b, D[i + 1]) - bY(tip.b, D[i - 1])) * 100 } : null; }).filter(Boolean);
  const avg = (xs, k) => xs.reduce((s, x) => s + x[k], 0) / (xs.length || 1);
  const rows = ccs.map(cc => { const inf = gyInf(cc), pol = gyPol(cc); return { cc, n: gyY(cc, 10).v, inf, r: gyReal(cc), r1m: gyReal(cc, 10, gyD(21)), pol, gap: pol != null && inf.v != null ? pol - inf.v : null }; }).sort((a, b) => b.r - a.r);
  el.innerHTML = `<div class="fi-tb">${gyFilt()}</div><div class="grid"><section class="panel c8"><header class="ph"><span class="pt">Real-yield ranking · 10Y</span><span class="pm">method per row</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Market</th><th class="r">Nominal</th><th class="r">Inflation</th><th>Inflation source</th><th class="r">Real</th><th class="r">Real 1M Δ</th><th class="r">Target</th><th class="r">Policy − inflation</th></tr></thead><tbody>${rows.map(x => `<tr><td>${esc(gyN(x.cc))}</td><td class="r">${nf(x.n, 2)}%</td><td class="r">${nf(x.inf.v, 1)}%</td><td><span class="sub" style="max-width:220px">${esc(x.inf.kind)}</span></td><td class="r"><b class="${cls(x.r)}">${nf(x.r, 2)}%</b></td><td class="r ${cls(-(x.r - x.r1m))}">${bpf((x.r - x.r1m) * 100, 0)}</td><td class="r">${GY_TGT[x.cc] || '—'}</td><td class="r ${cls(x.gap)}">${x.gap == null ? '—' : sgn(x.gap, 1) + ' pts'}</td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Real yield = nominal 10Y minus inflation as labelled (ex-post CPI, or an illustrative assumption where no CPI series is connected). Survey and model inflation forecasts are not connected. Policy rates for most markets are simulated approximations.</p></div></section>
      <section class="panel c4"><header class="ph"><span class="pt">United States · inflation-linked pricing</span></header><div class="pb"><div class="fi-kpis"><div><span>Nominal ~10Y</span><b>${nf(nom, 2)}%</b></div><div><span>TIPS real yield</span><b>${nf(tip.y, 2)}%</b></div><div><span>10Y breakeven</span><b>${nf(be10, 2)}%</b></div><div><span>5Y breakeven (approx.)</span><b>${nf(be10 - .08, 2)}%</b></div></div><p class="note">Breakevens are not pure inflation forecasts: they include inflation-risk and liquidity premia. Inflation swaps are not connected.</p>
        <h6>Around U.S. CPI releases (${around.length})</h6><dl class="kl"><div><dt>Avg nominal 10Y change, day before → day after</dt><dd>${bpf(avg(around, 'nomCh'), 1)}</dd></div><div><dt>Avg real (TIPS) change</dt><dd>${bpf(avg(around, 'realCh'), 1)}</dd></div><div><dt>When CPI beat consensus</dt><dd>${bpf(avg(around.filter(x => x.surp > 0), 'nomCh'), 1)} nominal</dd></div><div><dt>When CPI missed</dt><dd>${bpf(avg(around.filter(x => x.surp < 0), 'nomCh'), 1)} nominal</dd></div></dl><p class="note">Was the real-yield move driven by nominal rates or breakevens? Compare the two averages: the difference is the breakeven change. Association, not causation; simulated history.</p></div></section></div>
    <section class="panel"><header class="ph"><span class="pt">Real-yield curves (approx.)</span></header><div class="pb"><div id="gyRc"></div><p class="note">Nominal curve minus one inflation figure per market: a flat inflation assumption across maturities, which is a simplification.</p></div></section>`;
  fiCurveChart($('#gyRc', el), GY.cty.map((cc, i) => ({ label: gyN(cc), color: PAL[i], pts: govPts(cc).map(([m, y]) => [m, y - (gyInf(cc).v ?? 0)]) })), 260);
}

/* ---------- CENTRAL BANKS ---------- */
function gyCB(el) {
  const ccs = [...new Set(gyCC().filter(cc => !['FR', 'IT'].includes(cc)))]; const nextOf = cc => { const k = GY_CB[cc]?.[1]; if (k === 'CBN') return fiCbn()[0]; if (k) return calAll().find(e => e.type === 'cb' && e.d.k === k && !e.past)?.t; return null; };
  const rows = ccs.map(cc => { const p = gyPath(cc), p0 = gyPath(cc, gyD(21)), pol = gyPol(cc); return { cc, pol, p, rep: p && p0 ? (p[2].r - p0[2].r) * 100 : null, next: nextOf(cc), inf: gyInf(cc).v }; }).filter(r => r.p);
  const div = rows.slice().sort((a, b) => (a.p[2].r - a.pol) - (b.p[2].r - b.pol));
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Central-bank dashboard</span><span class="pm">${QL('model')} policy paths</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Central bank</th><th class="r">Policy rate</th><th>Next meeting</th><th class="r">3M</th><th class="r">6M</th><th class="r">12M</th><th class="r">24M</th><th class="r">Repriced 1M (12M pt)</th><th class="r">Inflation</th><th>Projections</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${esc(GY_CB[r.cc]?.[0] || r.cc)}</b><div class="sub">${esc(gyN(r.cc))}${['US', 'NG'].includes(r.cc) ? '' : ' · simulated rate'}</div></td><td class="r">${nf(r.pol, 2)}%</td><td>${r.next ? fd(r.next) : '<span class="muted">not connected</span>'}</td>${r.p.map(x => `<td class="r ${cls(-(x.r - r.pol))}">${bpf((x.r - r.pol) * 100, 0)}</td>`).join('')}<td class="r ${cls(-r.rep)}">${bpf(r.rep, 0)}</td><td class="r">${nf(r.inf, 1)}%</td><td><span class="muted sub">not connected</span></td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Implied changes vs today's policy rate, U.S. and Nigeria: from the simulated bill curve with the 3-month point anchored to the policy rate. Other markets (no bill series): a straight-line path whose two-year average matches the 2Y yield less an assumed 15 bp term premium. Policy rates outside the U.S. and Nigeria are illustrative, not official. OIS, futures and official projections (dot plots, inflation reports) are not connected, so this is market pricing under simple assumptions, not objective probabilities.</p></div></section>
    <div class="grid"><section class="panel c6"><header class="ph"><span class="pt">Policy divergence monitor · next 12 months</span></header><div class="pb">${div.map(r => { const v = (r.p[2].r - r.pol) * 100; const mx = Math.max(...div.map(x => Math.abs((x.p[2].r - x.pol) * 100)), 25); return `<div class="mv-sbr" style="cursor:default"><span class="mv-sbn">${esc(gyN(r.cc))}</span><span class="mv-sbt"><i class="${v >= 0 ? 'n' : 'p'}" style="width:${Math.abs(v) / mx * 50}%;${v >= 0 ? 'left:50%;right:auto' : 'right:50%;left:auto'}"></i></span><b class="${cls(-v)}">${bpf(v, 0)}</b><em>${r.rep == null ? '' : bpf(r.rep, 0)}</em></div>`; }).join('')}<p class="note">Bars: implied change (left = cuts, right = hikes). Last column: change in that pricing over 1 month. Cuts priced: ${div.filter(r => r.p[2].r < r.pol - .1).length}, hikes priced: ${div.filter(r => r.p[2].r > r.pol + .1).length}.</p></div></section>
      <section class="panel c6"><header class="ph"><span class="pt">Largest repricing · 1 month</span></header><div class="pb">${rows.slice().sort((a, b) => Math.abs(b.rep) - Math.abs(a.rep)).slice(0, 6).map(r => `<div class="fi-r"><span>${esc(GY_CB[r.cc]?.[0])}</span><b class="${cls(-r.rep)}">${bpf(r.rep, 0)}</b><span class="note">12M point</span></div>`).join('')}<p class="note">Gap between market pricing and official guidance: cannot be computed until central-bank projections are connected.</p></div></section></div>`;
}

/* ---------- SOVEREIGN RISK ---------- */
const SOV2 = { US: [122, 14, 6.0, 0, 'n/a'], UK: [101, 9, 4.5, 0, 'n/a'], DE: [63, 3, 2.3, 0, 'n/a'], FR: [113, 5, 5.4, 0, 'n/a'], IT: [137, 9, 3.4, 0, 'n/a'], JP: [235, 8, 3.0, 0, 'n/a'], CN: [90, 7, 7.0, 3, 'n/a'], CA: [107, 6, 1.5, 0, 'n/a'], AU: [50, 4, 1.0, 0, 'n/a'], IN: [82, 25, 7.5, 5, 'n/a'], BR: [87, 30, 7.0, 6, 'n/a'], MX: [53, 14, 4.0, 18, 'n/a'], ID: [40, 15, 2.5, 30, 'n/a'], TR: [26, 12, 3.0, 40, 'n/a'] };
function gySov(el) {
  const ccs = gyRows(); const t21 = gyD(21);
  const rows = ccs.map(cc => { const f = SOV[cc] ? [SOV[cc].debtGdp, SOV[cc].intRev, SOV[cc].def, SOV[cc].fxShare] : SOV2[cc] || []; const d10 = (gyY(cc, 10).v - gyY(cc, 10, t21).v) * 100, d2 = (gyY(cc, 2).v - gyY(cc, 2, t21).v) * 100; const fxm = gyFx(cc, t21); const eb = fiAll().filter(a => a.b.iss === cc && a.b.kind === 'Eurobond'); const ebc = eb.length ? eb.reduce((s, a) => s + (a.sd21 ?? 0), 0) / eb.length : null; const ev = [['Policy expectations', d2], ['Term premium / inflation (slope)', d10 - d2], ['Sovereign credit (USD spread)', ebc], ['Currency pressure', fxm < -2 ? -fxm * 3 : 0]].filter(x => x[1] != null); const lead = ev.slice().sort((a, b) => Math.abs(b[1]) - Math.abs(a[1]))[0]; return { cc, f, d10, d2, fxm, ebc, ev, lead }; });
  el.innerHTML = `<div class="fi-tb">${gyFilt()}</div><section class="panel"><header class="ph"><span class="pt">Sovereign risk dashboard · 1 month</span><span class="pm">illustrative fiscal figures</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Sovereign</th><th class="r">Debt/GDP</th><th class="r">Interest/revenue</th><th class="r">Deficit/GDP</th><th class="r">FX debt</th><th class="r">10Y 1M</th><th class="r">2Y 1M</th><th class="r">USD spread 1M</th><th class="r">FX vs USD 1M</th><th>Largest component (evidence, not conclusion)</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${esc(gyN(r.cc))}</b></td>${[0, 1, 2, 3].map(i => `<td class="r">${r.f[i] == null ? '—' : r.f[i] + '%'}</td>`).join('')}<td class="r ${cls(-r.d10)}">${bpf(r.d10, 0)}</td><td class="r ${cls(-r.d2)}">${bpf(r.d2, 0)}</td><td class="r ${r.ebc == null ? '' : cls(-r.ebc)}">${r.ebc == null ? '—' : bpf(r.ebc, 0)}</td><td class="r ${cls(r.fxm)}">${pc(r.fxm, 1)}</td><td><span class="sub" style="max-width:260px">${Math.abs(r.d10) < 3 ? 'Little change' : `${esc(r.lead[0])} (${bpf(r.lead[1], 0)}); also: ${r.ev.filter(x => x !== r.lead && Math.abs(x[1]) > 3).map(x => x[0].split(' (')[0].toLowerCase()).join(', ') || 'none material'}`}</span></td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Possible drivers of a yield change shown side by side: front-end (policy expectations), slope (term premium or inflation compensation), USD sovereign spread (credit), currency weakness (external pressure). Liquidity and supply effects are not measurable here. These are analytical possibilities, not automatic conclusions. <b>Fiscal figures are illustrative, not official statistics</b>; ratings, CDS, reserves and IMF data are not connected.</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Debt service vs revenue</span></header><div class="pb">${fiBars(rows.filter(r => r.f[1] != null).sort((a, b) => b.f[1] - a.f[1]).map(r => ({ label: r.cc, v: r.f[1] })), { h: 200, f: v => nf(v, 0) + '%' })}<p class="note">Interest expense as a share of government revenue (illustrative). Higher shares leave less room to absorb higher yields.</p></div></section>
    <p class="note">Detailed debt maturity walls, auctions and Nigeria's fiscal &amp; FX sensitivity live in <a href="#" data-gogo="fixed|gov">Fixed income › Government &amp; EM</a>.</p>`;
}

/* ---------- ISSUANCE & EVENTS ---------- */
function gyAucOther() { const out = []; [['UK', 'UK Gilt auction', 'YD.UK10', 4.5e9 * 1.27, 2], ['DE', 'German Bund auction', 'YD.DE10', 5e9 * 1.08, 3], ['JP', 'JGB 10-year auction', 'YD.JP10', 2.6e12 / 150, 4], ['IT', 'BTP auction', 'YD.IT10', 8e9 * 1.08, 4]].forEach(([cc, nm, id, sz, dow], j) => { let t = END - 42 * DAY; for (; t <= END + 42 * DAY; t += 14 * DAY) { let d = t + j * DAY; while (new Date(d).getUTCDay() !== dow) d += DAY; const g = rng(hash(nm + d)); out.push({ cc, t: d, title: nm, past: d <= END, size: sz, btc: 1.6 + g() * 1.6, stop: d <= END ? valAt(id, d) + (g() - .5) * .02 : null, post: null }); } }); return out; }
function gyIssue(el) {
  const us = fiUsAuc().map(a => ({ cc: 'US', t: a.t, title: a.title, past: a.past, size: a.off, btc: a.btc, stop: a.hi, tail: a.tail })); const ng = fiNgAuctions().map(a => ({ cc: 'NG', t: a.t, title: a.title, past: a.past, size: a.offer / valAt('FX.USDNGN', END), btc: a.btc, stop: a.stop })); const ot = gyAucOther(); const all = [...us, ...ng, ...ot];
  const wk = {}; all.filter(a => !a.past && a.t <= END + 42 * DAY).forEach(a => { let m = a.t; while (new Date(m).getUTCDay() !== 1) m -= DAY; (wk[m] = wk[m] || []).push(a); });
  const weeks = Object.entries(wk).sort((a, b) => a[0] - b[0]).map(([m, xs]) => ({ m: +m, xs, tot: xs.reduce((s, a) => s + a.size, 0), n: new Set(xs.map(a => a.cc)).size }));
  const EVS = [['USCPI', 'U.S. CPI', () => ecoRels(BY['EC.USCPI']).past.map(r => r.t)], ['USNFP', 'U.S. payrolls', () => ecoRels(BY['EC.USNFP']).past.map(r => r.t)], ['UKCPI', 'UK CPI', () => ecoRels(BY['EC.UKCPI']).past.map(r => r.t)], ['EAHICP', 'Euro-area HICP', () => ecoRels(BY['EC.EAHICP']).past.map(r => r.t)], ['FOMC', 'FOMC decisions', () => calAll().filter(e => e.type === 'cb' && e.d.k === 'FOMC' && e.past).map(e => e.t)], ['ECB', 'ECB decisions', () => calAll().filter(e => e.type === 'cb' && e.d.k === 'ECB' && e.past).map(e => e.t)], ['UST', 'U.S. 10Y/30Y auctions', () => fiUsAuc().filter(a => a.past && a.tn >= 10).map(a => a.t)]];
  const ev = EVS.find(e => e[0] === GY.ev) || EVS[0]; const dates = ev[2]().filter(t => t < END - 3 * DAY); const D = NX_D(); const w = GY.win;
  const react = gyCC().map(cc => { const id = `YD.${cc}${GY.ten === 2 ? 2 : 10}`; if (!BY[id]) return null; const xs = dates.map(t => { const i = bsLE(D, t); if (i - w - 1 < 0 || i + w >= D.length) return null; return (valAt(id, D[i + w]) - valAt(id, D[i - w - 1])) * 100; }).filter(v => v != null); const base = []; for (let k = 30; k < 280; k += 7) base.push(Math.abs((valAt(id, D[D.length - k]) - valAt(id, D[D.length - k - 2 * w - 1])) * 100)); const mabs = xs.reduce((s, v) => s + Math.abs(v), 0) / (xs.length || 1), b0 = base.reduce((s, v) => s + v, 0) / base.length; return { cc, avg: xs.reduce((s, v) => s + v, 0) / (xs.length || 1), mabs, ratio: mabs / b0, n: xs.length }; }).filter(Boolean).sort((a, b) => b.ratio - a.ratio);
  el.innerHTML = `<div class="grid"><section class="panel c7"><header class="ph"><span class="pt">Global auction calendar &amp; results</span><span class="pm">${QL('ind')}</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Date</th><th>Auction</th><th class="r">Size (USD eq.)</th><th class="r">Bid-to-cover</th><th class="r">Stop / high yield</th></tr></thead><tbody>${[...all.filter(a => !a.past).sort((a, b) => a.t - b.t).slice(0, 8), ...all.filter(a => a.past).sort((a, b) => b.t - a.t).slice(0, 12)].map(a => `<tr><td>${fd(a.t, { day: '2-digit', month: 'short' })}${a.past ? '' : ' <span class="cal-st estimated">Next</span>'}</td><td><b>${esc(a.cc)}</b> ${esc(a.title)}</td><td class="r">${fmtSize(a.size, 'USD')}</td><td class="r">${a.past ? nf(a.btc, 2) + '×' : '—'}</td><td class="r">${a.stop == null ? '—' : nf(a.stop, 3) + '%'}</td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Auction formats differ (U.S. single-price, UK/German/Italian uniform or multiple-price, Nigerian NTB stop rates), so bid-to-cover is not comparable across markets. Weighted-average yields, allotment detail and syndications: see Fixed income › Auctions. All simulated.</p></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">Supply pressure · next 6 weeks</span></header><div class="pb">${fiBars(weeks.map(w2 => ({ label: fd(w2.m, { day: '2-digit', month: 'short' }), v: w2.tot / 1e9 })), { h: 180, f: v => '$' + nf(v, 0) + 'bn' })}<ul class="fi-ul">${weeks.filter(w2 => w2.n >= 3).map(w2 => `<li>Week of ${fd(w2.m)}: ${w2.n} sovereign issuers in market (${[...new Set(w2.xs.map(a => a.cc))].join(', ')}), ${fmtSize(w2.tot, 'USD')}</li>`).join('') || '<li>No week with three or more issuers.</li>'}</ul><p class="note">Gross auction size in the simulated calendar. Maturities, coupons and central-bank operations offset part of it.</p></div></section></div>
    <section class="panel"><header class="ph"><span class="pt">Event reactions</span></header><div class="pb"><div class="row" style="gap:8px;flex-wrap:wrap"><select class="inp sm" id="gyEv">${EVS.map(e => `<option value="${e[0]}" ${e[0] === GY.ev ? 'selected' : ''}>${e[1]}</option>`).join('')}</select>${seg('gywin', [['1', '−1 to +1 day'], ['5', '−5 to +5 days']], String(w))}${seg('gyten2', [['2', '2Y'], ['10', '10Y']], String(GY.ten === 2 ? 2 : 10))}<span class="note">${dates.length} past events</span></div>
      <div class="tw"><table class="t dense"><thead><tr><th>Market</th><th class="r">Avg change</th><th class="r">Avg absolute change</th><th class="r">vs normal window</th><th class="r">n</th></tr></thead><tbody>${react.map(r => `<tr><td>${esc(gyN(r.cc))}</td><td class="r ${cls(-r.avg)}">${bpf(r.avg, 1)}</td><td class="r">${nf(r.mabs, 1)} bp</td><td class="r"><b>${nf(r.ratio, 2)}×</b></td><td class="r">${r.n}</td></tr>`).join('')}</tbody></table></div><div id="gyEs"></div><p class="note">Change from the close before the window to the close at its end. "vs normal" compares with same-length windows on random past days. Daily closes only, other news in the same window is not removed: temporal association, not proven causation. Simulated history.</p></div></section>`;
  const sel = react.slice(0, 4).map(r => `YD.${r.cc}${GY.ten === 2 ? 2 : 10}`); calStudy($('#gyEs', el), dates.filter(t => t < END - 6 * DAY), sel);
}

/* ---------- EM & FRONTIER ---------- */
function gyEM(el) {
  const ccs = gyCC().filter(cc => GY_META[cc]?.[1] !== 'Developed'); const t21 = gyD(21);
  const rows = ccs.map(cc => { const fx = COUNTRY[cc]?.fx; const fxm = fx ? gyFx(cc, t21) : null; const d10 = (gyY(cc, 10).v - gyY(cc, 10, t21).v) * 100; const eb = fiAll().filter(a => a.b.iss === cc && a.b.kind === 'Eurobond'); const frontier = GY_META[cc][1] === 'Frontier'; return { cc, y2: gyY(cc, 2).v, y10: gyY(cc, 10).v, r: gyReal(cc), d10, fxm, fx1y: fx ? gyFx(cc, gyD(252)) : null, eb: eb.length ? eb.reduce((s, a) => s + a.spr, 0) / eb.length : null, flag: d10 > 10 && fxm != null && fxm < -1, frontier, stale: frontier && hash(cc + iso(END)) % 3 === 0 }; });
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Emerging &amp; frontier sovereign yields</span><span class="pm">frontier = indicative</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Market</th><th>Class</th><th class="r">2Y</th><th class="r">10Y</th><th class="r">Real 10Y</th><th class="r">10Y 1M</th><th class="r">FX 1M</th><th class="r">FX 1Y</th><th class="r">USD Eurobond spread</th><th>Signals &amp; data quality</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${esc(gyN(r.cc))}</b></td><td><span class="sub">${GY_META[r.cc][1]}</span></td><td class="r">${nf(r.y2, 2)}%</td><td class="r">${nf(r.y10, 2)}%</td><td class="r">${nf(r.r, 2)}%<sup>${GY_INF[r.cc]?.[0] ? '' : 'a'}</sup></td><td class="r ${cls(-r.d10)}">${bpf(r.d10, 0)}</td><td class="r ${cls(r.fxm)}">${r.fxm == null ? '—' : pc(r.fxm, 1)}</td><td class="r ${cls(r.fx1y)}">${r.fx1y == null ? '—' : pc(r.fx1y, 1)}</td><td class="r">${r.eb == null ? '—' : nf(r.eb, 0) + ' bp'}</td><td>${r.flag ? '<span class="fi-shape inv">Yields up, currency weaker</span> ' : ''}${r.frontier ? `<span class="gy-q ind">${r.stale ? 'stale: last quote 2 days old' : 'indicative quote'}</span>` : '<span class="gy-q">observed</span>'}</td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">FX = local currency vs USD (positive = local currency stronger). Frontier yields are indicative secondary quotes with possible gaps; production would distinguish official auction yields from secondary indications and show each quote's date and source. <sup>a</sup> Illustrative inflation assumption.</p></div></section>
    <div class="grid"><section class="panel c6"><header class="ph"><span class="pt">Nigeria · real yield &amp; policy context</span></header><div class="pb"><div class="fi-kpis"><div><span>FGN 10Y</span><b>${nf(gyY('NG', 10).v, 2)}%</b></div><div><span>Inflation assumption</span><b>${nf(gyInf('NG').v, 1)}%</b><small>illustrative, editable below</small></div><div><span>Real 10Y</span><b id="ngR">${nf(gyReal('NG'), 2)}%</b></div><div><span>MPR</span><b>${nf(valAt('MM.NGMPR', END), 2)}%</b></div></div><label class="row note" style="gap:8px">Inflation assumption % <input class="inp sm" id="ngInf" type="number" step="any" value="${gyInf('NG').v}" style="width:80px"></label><p class="note">No CPI series for Nigeria is connected; set your own assumption and the real yield updates. Disclose the assumption when sharing.</p><button class="btn sm" data-gogo="fixed|gov">Open the Nigeria Debt Intelligence workspace</button></div></section>
      <section class="panel c6"><header class="ph"><span class="pt">Local currency vs USD Eurobonds · separate panels</span></header><div class="pb"><div class="fi-two"><div><h6>Local (NGN)</h6>${[.25, 1, 2, 5, 10, 30].map(m => { const x = gyY('NG', m); return x.v == null ? '' : `<div class="fi-r"><span>${GY_TEN.find(t => t[1] === m)[0]}</span><b>${nf(x.v, 2)}%</b></div>`; }).join('')}</div><div><h6>USD Eurobonds</h6>${fiAll().filter(a => a.b.iss === 'NG' && a.b.kind === 'Eurobond').sort((a, b) => a.yrs - b.yrs).map(a => `<div class="fi-r"><span>${new Date(a.b.mat).getUTCFullYear()}</span><b>${nf(a.ytm, 2)}%</b><i>${nf(a.spr, 0)} bp</i></div>`).join('')}</div></div><p class="note">Not directly comparable: compare with FX scenarios, depreciation assumptions, USD spreads, liquidity and hedge costs (calculator in Fixed income › Government &amp; EM).</p></div></section></div>`;
  const inp = $('#ngInf', el); inp.oninput = () => { const v = +inp.value; GY_INF.NG = [null, v]; $('#ngR', el).textContent = nf(gyY('NG', 10).v - v, 2) + '%'; };
}

/* ---------- MOVERS ---------- */
function gyMovers(el) {
  const k = GY_K[GY.mvP]; const t0 = gyD(k); const ccs = gyRows(); let rows = [];
  if (GY.mvM === 'ten') rows = ccs.flatMap(cc => GY_TEN.filter(([, m]) => m !== 20).map(([l, m]) => { const a = gyY(cc, m).v, b = gyY(cc, m, t0).v; return a == null || b == null ? null : { l: `${gyN(cc)} ${l}`, v: (a - b) * 100, lvl: a, cc, m }; }).filter(Boolean));
  if (GY.mvM === 'slope') rows = ccs.map(cc => { const s = t => (gyY(cc, 10, t).v - gyY(cc, 2, t).v) * 100; return { l: `${gyN(cc)} 2s10s`, v: s(END) - s(t0), lvl: s(END), cc }; });
  if (GY.mvM === 'real') rows = ccs.map(cc => { const a = gyReal(cc), b = gyReal(cc, 10, t0); return a == null || b == null ? null : { l: `${gyN(cc)} real 10Y`, v: (a - b) * 100, lvl: a, cc }; }).filter(Boolean);
  if (GY.mvM === 'spr') rows = ccs.filter(cc => cc !== 'US').map(cc => { const s = t => (gyY(cc, 10, t).v - gyY('US', 10, t).v) * 100; return { l: `${gyN(cc)} − U.S. 10Y`, v: s(END) - s(t0), lvl: s(END), cc }; });
  if (GY.mvM === 'pol') rows = ccs.map(cc => { const p = gyPath(cc), p0 = gyPath(cc, t0); return p && p0 ? { l: `${GY_CB[cc]?.[0] || cc} · 12M implied`, v: (p[2].r - p0[2].r) * 100, lvl: p[2].r, cc } : null; }).filter(Boolean);
  rows.sort((a, b) => Math.abs(b.v) - Math.abs(a.v)); const mx = Math.max(...rows.map(r => Math.abs(r.v)), 1);
  el.innerHTML = `<div class="fi-tb"><div class="row" style="gap:8px;flex-wrap:wrap">${seg('gymvm', [['ten', 'Yields by tenor'], ['slope', 'Curve slope'], ['real', 'Real yields'], ['spr', 'Spread vs U.S.'], ['pol', 'Policy pricing']], GY.mvM)}${seg('gymvp', ['1D', '1W', '1M', '3M'], GY.mvP)}</div>${gyFilt()}</div>
    <section class="panel"><header class="ph"><span class="pt">Largest moves · ${GY.mvP}</span><span class="pm">${rows.length} series</span></header><div class="pb"><div class="mv-sb">${rows.slice(0, 25).map(r => `<a class="mv-sbr" href="#" ${r.m ? `data-gyc="${r.cc}|${r.m}"` : ''}><span class="mv-sbn">${esc(r.l)}</span><span class="mv-sbt"><i class="${r.v >= 0 ? 'n' : 'p'}" style="width:${Math.abs(r.v) / mx * 50}%;${r.v >= 0 ? 'left:50%;right:auto' : 'right:50%;left:auto'}"></i></span><b class="${cls(-r.v)}">${bpf(r.v, 0)}</b><em>${GY.mvM === 'ten' || GY.mvM === 'real' || GY.mvM === 'pol' ? nf(r.lvl, 2) + '%' : sgn(r.lvl, 0)}</em></a>`).join('')}</div><p class="note">Ranked by absolute change in bp; red = yields (or spreads, or priced policy) up. Click a yield for its history and related releases.</p></div></section>`;
}

/* ---------- REGIMES & RELATIONSHIPS ---------- */
function gyRegimes(el) {
  const D = NX_D(); const at = k => D[k]; const n = D.length;
  const state = i => { const t = at(i), t6 = at(Math.max(0, i - 126)), t3 = at(Math.max(0, i - 63)); const cpi = valAt('EC.USCPI', t) - valAt('EC.USCPI', t6); const ff = valAt('EC.FEDF', t) - valAt('EC.FEDF', t6); const inv = govY('US', 10, t) - govY('US', 2, t) < 0; const usd = (valAt('FX.DXY', t) / valAt('FX.DXY', t3) - 1) * 100; return { inf: cpi > .2 ? 'Inflation accelerating' : cpi < -.2 ? 'Disinflation' : 'Inflation stable', pol: ff > .2 ? 'Tightening' : ff < -.2 ? 'Easing' : 'Policy on hold', inv: inv ? 'Curve inverted' : 'Curve positive', usd: usd > 2 ? 'Dollar strengthening' : usd < -2 ? 'Dollar weakening' : 'Dollar stable', stress: valAt('SP.EMSOV', t) > 4.5 ? 'EM sovereign stress' : null, ftq: valAt('IX.VIX', t) > 30 ? 'Flight to quality (VIX > 30)' : null }; };
  const cur = state(n - 1); const EMS = ['BR', 'ZA', 'IN', 'MX', 'ID'];
  const fwd = (i, f) => { const j = Math.min(n - 1, i + 63); return f(at(j)) - f(at(i)); };
  const tab = {}; for (let i = 300; i < n - 63; i += 21) { const s = state(i); Object.values(s).filter(Boolean).forEach(lab => { (tab[lab] = tab[lab] || []).push({ us: fwd(i, t => govY('US', 10, t)) * 100, de: fwd(i, t => govY('DE', 10, t)) * 100, em: fwd(i, t => EMS.reduce((q, c) => q + govY(c, 10, t), 0) / EMS.length) * 100, sp: fwd(i, t => valAt('SP.EMSOV', t)) * 100 }); }); }
  const cycles = []; const ff = series('EC.FEDF'); for (let i = 12; i < ff.c.length; i++) if (ff.c[i] > ff.c[i - 1] + .1 && ff.c.slice(Math.max(0, i - 12), i - 1).every((v, k, a) => k === 0 || v <= a[k - 1] + .01)) cycles.push(ff.d[i]);
  const path = t0 => { const i0 = bsLE(D, t0); const out = []; for (let k = 0; k <= 504 && i0 + k < n; k += 5) out.push({ x: k / 21, y: (govY('US', 10, D[i0 + k]) - govY('US', 10, D[i0])) * 100 }); return out; };
  const usdUp = []; const usdDn = []; for (let i = 300; i < n - 21; i += 21) { const ch = (valAt('FX.DXY', at(i + 21)) / valAt('FX.DXY', at(i)) - 1) * 100; const em = (EMS.reduce((q, c) => q + govY(c, 10, at(i + 21)) - govY(c, 10, at(i)), 0) / EMS.length) * 100; (ch > 2 ? usdUp : ch < -2 ? usdDn : []).push(em); }
  const avg = a => a.reduce((s, v) => s + v, 0) / (a.length || 1);
  const cc = GY.cc; const W = GY.corrW; const tgt = `YD.${cc}10`; const drivers = [['YD.US10', 'U.S. 10Y (bp)'], ['FX.DXY', 'Dollar index (%)'], ['CM.CO1', 'Brent (%)'], ['IX.VIX', 'VIX (%)'], ['IX.SPX', 'S&P 500 (%)'], ['CM.GC1', 'Gold (%)'], ...(COUNTRY[cc]?.fx ? [[COUNTRY[cc].fx, 'Local FX vs USD (%)']] : [])].filter(([id]) => id !== tgt);
  const reg = (x, w, end) => { const ys = [], xs = []; for (let k = end - w + 1; k <= end; k++) { const t = D[k], p = D[k - 1]; const y = (valAt(tgt, t) - valAt(tgt, p)) * 100; const xv = isY(x) ? (valAt(x, t) - valAt(x, p)) * 100 : (valAt(x, t) / valAt(x, p) - 1) * 100; if (isFinite(y) && isFinite(xv)) { ys.push(y); xs.push(xv); } } const mx = avg(xs), my = avg(ys); let sxy = 0, sxx = 0, syy = 0; xs.forEach((v, i) => { sxy += (v - mx) * (ys[i] - my); sxx += (v - mx) ** 2; syy += (ys[i] - my) ** 2; }); return { b: sxx ? sxy / sxx : 0, r: sxx && syy ? sxy / Math.sqrt(sxx * syy) : 0 }; };
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Current regime · United States</span></header><div class="pb"><div class="gy-regs">${Object.values(cur).filter(Boolean).map(s => `<span class="chip static">${esc(s)}</span>`).join('')}</div><p class="note">Rules: CPI 6-month change ±0.2 pts; fed funds 6-month change ±0.2; 2s10s below zero; dollar index 3-month change ±2%; EM spread above 450 bp; VIX above 30. Recession dating is not connected.</p></div></section>
    <div class="grid"><section class="panel c7"><header class="ph"><span class="pt">What followed each regime · next 3 months</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Regime</th><th class="r">n</th><th class="r">U.S. 10Y</th><th class="r">Bund 10Y</th><th class="r">EM 10Y avg</th><th class="r">EM spread</th></tr></thead><tbody>${Object.entries(tab).sort((a, b) => b[1].length - a[1].length).map(([lab, xs]) => `<tr class="${Object.values(cur).includes(lab) ? 'gy-cur' : ''}"><td>${esc(lab)}</td><td class="r">${xs.length}</td>${['us', 'de', 'em', 'sp'].map(k => `<td class="r ${cls(-avg(xs.map(x => x[k])))}">${bpf(avg(xs.map(x => x[k])), 0)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Average change over the following 63 sessions, sampled monthly across the simulated 10-year history; highlighted rows match today. Small samples; relationships change over time and do not guarantee future outcomes.</p></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">EM yields when the dollar moves</span></header><div class="pb"><dl class="kl"><div><dt>Months with dollar index +2% or more</dt><dd>${bpf(avg(usdUp), 0)} avg EM 10Y change (n=${usdUp.length})</dd></div><div><dt>Months with dollar index −2% or more</dt><dd>${bpf(avg(usdDn), 0)} (n=${usdDn.length})</dd></div></dl><p class="note">EM basket: Brazil, South Africa, India, Mexico, Indonesia.</p></div></section></div>
    <section class="panel"><header class="ph"><span class="pt">U.S. 10Y through tightening cycles</span></header><div class="pb"><div id="gyCyc"></div><p class="note">10Y change (bp) from the first hike of each cycle detected in the simulated fed funds series, over 24 months. Comparing curve inversions with past recessions needs recession dating, which is not connected.</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Correlation &amp; sensitivity</span></header><div class="pb"><div class="row" style="gap:8px;flex-wrap:wrap"><select class="inp sm" id="gyCc">${gyCC().map(c => `<option value="${c}" ${c === cc ? 'selected' : ''}>${esc(gyN(c))} 10Y</option>`).join('')}</select>${seg('gycw', [['60', '60 days'], ['120', '120 days'], ['250', '250 days']], String(W))}</div><div class="tw"><table class="t dense"><thead><tr><th>Driver (daily change)</th><th class="r">Correlation</th><th class="r">Sensitivity (bp per unit)</th><th class="r">Correlation 1 year earlier</th></tr></thead><tbody>${drivers.map(([id, l]) => { const a = reg(id, W, n - 1), b = reg(id, W, n - 253); return `<tr><td>${lnk(id, l)}</td><td class="r">${nf(a.r, 2)}</td><td class="r">${nf(a.b, 2)}</td><td class="r ${Math.abs(a.r - b.r) > .3 ? 'dn' : ''}">${nf(b.r, 2)}</td></tr>`; }).join('')}</tbody></table></div><p class="note">Single-factor regression of daily ${esc(gyN(cc))} 10Y changes on each driver over the window. Red = correlation changed by more than 0.3 vs a year earlier. Historical relationships change and do not guarantee future behaviour. Inflation surprises and fiscal announcements: see Issuance &amp; events › Event reactions.</p></div></section>`;
  xyChart($('#gyCyc', el), { h: 240, xlab: 'Months after first hike', ylab: 'bp', xf: v => nf(v, 0), yf: v => nf(v, 0), series: cycles.map((t, i) => ({ label: 'Cycle from ' + fd(t, { month: 'short', year: 'numeric' }), color: PAL[i % 8], line: true, r: 0, points: path(t) })) });
  $('#gyCyc', el).insertAdjacentHTML('afterend', `<div class="nx-leg">${cycles.map((t, i) => `<span><i style="background:${PAL[i % 8]}"></i>Cycle from ${fd(t, { month: 'short', year: 'numeric' })}</span>`).join('')}</div>`);
}

/* ---------- PORTFOLIO EXPOSURE ---------- */
const GY_SC = { us50: 'U.S. yields +50 bp', usSteep: 'U.S. curve steepens (2Y −25, 30Y +50), Europe unchanged', em100: 'EM sovereign USD spreads +100 bp', fx10: 'Local currency (NGN) −10% vs USD', realUp: 'Real yields +50 bp, breakevens −25 bp', cuts: 'Staggered cuts: U.S. front −25, Nigeria front −100' };
function gyShock(sc, a) { const b = a.b, x = a.yrs; if (sc === 'us50') return b.curve === 'US' ? 50 : 0; if (sc === 'usSteep') return b.curve === 'US' ? -25 + (clamp(x, 2, 30) - 2) / 28 * 75 : 0; if (sc === 'em100') return b.kind === 'Eurobond' ? 100 : 0; if (sc === 'realUp') return b.kind === 'Inflation-linked' ? 50 : b.curve === 'US' ? 25 : 0; if (sc === 'cuts') return b.curve === 'US' ? (x <= 2 ? -25 : x <= 5 ? -25 * (5 - x) / 3 : 0) : b.curve === 'NG' ? (x <= 2 ? -100 : x <= 5 ? -100 * (5 - x) / 3 : 0) : 0; return 0; }
function gyPort(el) {
  const R = fiPortCalc(null); const sc = GY.scen; const rows = R.rows.map(r => { const dy = gyShock(sc, r.a); let pl = (bPrice(r.b, r.a.y + dy / 100).dirty - r.a.dirty) / 100 * r.h.face * ccyUSD(r.b.ccy); if (sc === 'fx10' && r.b.ccy === 'NGN') pl = r.mv * (1 / 1.1 - 1); return { ...r, dy, pl, cty: r.b.iss.length === 2 ? r.b.iss : 'US', hedged: r.b.ccy === 'USD' }; });
  const tot = rows.reduce((s, r) => s + r.pl, 0); const byC = {}; rows.forEach(r => { const k = r.b.curve === 'US' && r.b.kind !== 'Government bond' && r.b.kind !== 'Inflation-linked' ? (r.b.kind === 'Eurobond' ? r.b.iss + ' (USD)' : 'US credit') : r.b.curve; byC[k] = byC[k] || { mv: 0, dv: 0, krd: [0, 0, 0, 0] }; byC[k].mv += r.mv; byC[k].dv += r.dv; if (r.a.krd) r.a.krd.forEach((q, i) => byC[k].krd[i] += q.d * r.mv * 1e-4); });
  el.innerHTML = `<div class="grid"><section class="panel c7"><header class="ph"><span class="pt">Exposure by curve &amp; tenor</span><span class="pm">USD · ${QL('model')}</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Exposure</th><th class="r">Market value</th><th class="r">DV01</th>${KEYS.map(k => `<th class="r">${k}Y KRD $</th>`).join('')}</tr></thead><tbody>${Object.entries(byC).map(([k, v]) => `<tr><td>${esc(k)}</td><td class="r">${big(v.mv, '$')}</td><td class="r">$${nf(v.dv, 0)}</td>${v.krd.map(q => `<td class="r">$${nf(q, 0)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">KRD $ = value change for a 1 bp move at that key tenor. Holdings come from the Fixed income portfolio (editable there). FX-hedged share: ${nf(rows.filter(r => r.hedged).reduce((s, r) => s + r.mv, 0) / R.tot * 100, 0)}% is USD-denominated; NGN holdings are unhedged in this example. Liquidity buckets need trading data (not connected).</p></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">Scenario engine</span></header><div class="pb"><select class="inp" id="gySc" style="width:100%">${Object.entries(GY_SC).map(([k, l]) => `<option value="${k}" ${k === sc ? 'selected' : ''}>${l}</option>`).join('')}</select><div class="fi-big"><span>Estimated P&amp;L</span><b class="${cls(tot)}">${big(tot, '$')}</b><small>${pc(tot / R.tot * 100)} of ${big(R.tot, '$')}</small></div><h6>Drivers</h6>${rows.filter(r => Math.abs(r.pl) > 1).sort((a, b) => Math.abs(b.pl) - Math.abs(a.pl)).slice(0, 6).map(r => `<div class="fi-r"><span>${esc(r.b.tk)}</span><span>${r.dy ? bpf(r.dy, 0) : 'FX'}</span><b class="${cls(r.pl)}">${big(r.pl, '$')}</b></div>`).join('') || '<p class="note">No holding is affected by this scenario.</p>'}<p class="note">Full repricing at shocked yields; explicit assumptions in the scenario name; all other factors unchanged. Correlated shocks are not modelled.</p></div></section></div>`;
}

