  ccs.filter(c => c !== 'US').forEach(cc => { const b = ['FR', 'IT'].includes(cc) ? 'DE' : 'US'; const sp = t => (gyY(cc, 10, t).v - gyY(b, 10, t).v) * 100; const hs = []; for (let k = D.length - 1; k > 260; k -= 5) hs.push(sp(D[k])); const now = sp(END); const p = gyPct(hs, now); if (p > 4 && p < 96) return; out.push({ cat: 'rv', cc, score: 14, conf: GY_META[cc][1] === 'Frontier' ? 'Low' : 'Medium', confWhy: 'Percentile over a 10-year simulated history', head: `${gyN(cc)} − ${gyN(b)} 10Y spread at the ${ordn(p)} percentile of its history`, ev: `${sgn(now, 0)} bp now · range ${sgn(Math.min(...hs), 0)} to ${sgn(Math.max(...hs), 0)} bp · 1M ${bpf(now - sp(t21), 0)}`, why: 'Extreme spreads can mean-revert or signal a regime change; the difference may be justified by inflation, FX or credit risk.', link: ['spreads', 'Open spread analysis', () => { GY.pair = [cc, b]; GY.ten = 10; }], trail: { obs: `The ${gyN(cc)} − ${gyN(b)} 10-year spread is ${sgn(now, 0)} bp, at the ${ordn(p)} percentile.`, ev: [['Spread', sgn(now, 0) + ' bp'], ['1M change', bpf(now - sp(t21), 0)], ['History min / median / max', `${sgn(Math.min(...hs), 0)} / ${sgn(gyQ(hs, 50), 0)} / ${sgn(Math.max(...hs), 0)}`], ['Inflation difference', sgn((gyInf(cc).v ?? 0) - (gyInf(b).v ?? 0), 1) + ' pts'], ['Policy-rate difference', sgn(((gyPol(cc) ?? 0) - (gyPol(b) ?? 0)) * 100, 0) + ' bp']], interp: ['Inflation and policy differentials', 'Sovereign credit risk', 'Currency risk premium', 'Liquidity and investor base differences'], hist: `Weekly observations over the simulated 10-year history (n=${hs.length}).`, impl: 'Cross-market duration and relative-value positions.', unc: ['A historical extreme is not an arbitrage', 'Regime changes can keep spreads at extremes', 'Simulated data'] }, rule: { m: 'spr', a: cc, b, ten: 10, op: p > 50 ? 'xbelow' : 'xabove', thr: { kind: 'pctl', p: p > 50 ? 90 : 10, yrs: 5 } }, q: `Is the ${gyN(cc)}-${gyN(b)} 10-year spread at an extreme justified? List supporting and opposing evidence.` }); });
  // 5 moves inconsistent with policy pricing
