function gyNgPrem() { const xs = fiNgAuctions().filter(a => a.past && a.stop != null).slice(-6).map(a => { const d = +(a.title.match(/(\d+)-day/) || [])[1]; const id = d <= 91 ? 'YD.NG3M' : d <= 182 ? 'YD.NG6M' : 'YD.NG1Y'; return BY[id] ? (a.stop - valAt(id, a.t)) * 100 : null; }).filter(v => v != null); return xs.length ? gyM(xs) : 0; }
