const GY_THS = { us_ease: ['U.S. easing cycle', 'The Fed keeps cutting as inflation cools.', [['fed12', -1], ['us2', -1], ['uscpi', -1], ['us2s10s', 1]]], steep: ['Global curve steepening', 'Long-end yields rise relative to short ends across major markets.', [['us2s10s', 1], ['de2s10s', 1], ['uk2s10s', 1], ['usbe', 1]]], emrally: ['EM local-currency rally', 'EM currencies strengthen and local yields fall.', [['emfx', 1], ['em10', -1], ['emspr', -1], ['dxy', -1]]], ngdis: ['Nigeria disinflation & rate cuts', 'Nigerian yields and the policy rate fall while the naira holds.', [['ng1y', -1], ['ng10', -1], ['ngmpr', -1], ['ngn', 1]]], conv: ['Euro-area periphery convergence', 'Italian spreads narrow as risk appetite holds.', [['itde', -1], ['vix', -1], ['emspr', -1]]] };
function gyThDefs() { S.gyTheses = S.gyTheses || []; const o = Object.fromEntries(Object.entries(GY_THS).map(([k, v]) => [k, { key: k, name: v[0], desc: v[1], ind: v[2], tpl: true }])); S.gyTheses.filter(t => t.custom).forEach(t => o[t.key] = t); return o; }
function gyIndCh(k, back = 0) { const [, u, f] = GY_IND[k]; const t1 = gyD(back), t0 = gyD(back + 21); const a = f(t1), b = f(t0); return u === '%' ? (a / b - 1) * 100 : u === 'bp' ? (a - b) * 100 : a - b; }
function gyThEval(def, back = 0) { const rows = def.ind.map(([k, dir]) => { const v = gyIndCh(k, back); const u = GY_IND[k][1]; const tiny = u === 'bp' ? 2 : u === '%' ? .3 : .05; const vd = Math.abs(v) < tiny ? 0 : Math.sign(v) === dir ? 1 : -1; return { k, dir, v, u, vd }; }); const sc = rows.reduce((s, r) => s + r.vd, 0); return { rows, sc, sup: rows.filter(r => r.vd > 0).length, con: rows.filter(r => r.vd < 0).length }; }
const gyIndF = (v, u) => u === 'bp' ? bpf(v, 0) : u === '%' ? pc(v, 1) : sgn(v, 2) + ' pts';
function gyRuleVal(r, t = END) { if (r.m === 'thesis') { const d = gyThDefs()[r.key]; return d ? gyThEval(d, t === END ? 0 : 1).sc : null; } const g = (c, m) => gyY(c, m, t).v; switch (r.m) { case 'lvl': return g(r.a, r.ten); case 'real': return gyReal(r.a, r.ten, t); case 'spr': return (g(r.a, r.ten) - g(r.b, r.ten)) * 100; case 'slope': return (g(r.a, 10) - g(r.a, 2)) * 100; case 'ch1': return gyCh(r.a, r.ten, 1, t); case 'ch5': return gyCh(r.a, r.ten, 5, t); } return null; }
const gyRuleU = r => ['lvl', 'real'].includes(r.m) ? '%' : r.m === 'thesis' ? '' : ' bp';
function gyRuleThr(r) { if (r.m === 'thesis') return 0; if (r.thr.kind === 'val') return r.thr.v; const D = NX_D(); const xs = []; for (let k = D.length - 1; k > Math.max(0, D.length - 1 - r.thr.yrs * 252); k -= 5) { const v = gyRuleVal(r, D[k]); if (v != null) xs.push(v); } return gyQ(xs, r.thr.p); }
function gyRuleEval(r) { const v = gyRuleVal(r), pv = gyRuleVal(r, gyD(1)), th = gyRuleThr(r); let hit = false; if (r.m === 'thesis') hit = v < 0; else if (r.op === 'above') hit = v >= th; else if (r.op === 'below') hit = v <= th; else if (r.op === 'xabove') hit = pv < th && v >= th; else if (r.op === 'xbelow') hit = pv > th && v <= th; else if (r.op === 'absabove') hit = Math.abs(v) >= th; return { v, th, hit }; }
function gyRuleText(r) { if (r.m === 'thesis') return `Evidence turns against thesis "${gyThDefs()[r.key]?.name || r.key}"`; const what = { lvl: `${gyN(r.a)} ${r.ten}Y yield`, real: `${gyN(r.a)} real ${r.ten}Y yield`, spr: `${r.a}–${r.b} ${r.ten}Y spread`, slope: `${gyN(r.a)} 2s10s slope`, ch1: `${gyN(r.a)} ${r.ten}Y 1-day change`, ch5: `${gyN(r.a)} ${r.ten}Y 1-week change` }[r.m]; const op = { above: 'at or above', below: 'at or below', xabove: 'crosses above', xbelow: 'crosses below', absabove: 'moves by at least' }[r.op]; const th = r.thr.kind === 'pctl' ? `its ${r.thr.yrs}-year ${r.thr.p}th percentile (≈${nf(gyRuleThr(r), r.m === 'lvl' || r.m === 'real' ? 2 : 0)}${gyRuleU(r)})` : `${r.thr.v}${gyRuleU(r)}`; return `${what} ${op} ${th}`; }
const gyRuleFmt = (r, x) => x == null ? '—' : r.m === 'thesis' ? `score ${sgn(x, 0)}` : nf(x, ['lvl', 'real'].includes(r.m) ? 2 : 0) + gyRuleU(r);
function gyParseRule(q) { const s = q.toLowerCase(); const cc = gyFindCC(q); const ten = gyTenOf(s) || 10; const r = { m: 'lvl', a: cc[0] || 'US', b: cc[1] || null, ten, op: 'above', thr: { kind: 'val', v: 0 } };
  if (/2s10s|curve/.test(s)) { r.m = 'slope'; } else if (cc.length >= 2 || /spread|differential/.test(s)) { r.m = 'spr'; r.b = r.b || (r.a === 'US' ? 'DE' : 'US'); } else if (/real/.test(s)) r.m = 'real'; else if (/in a day|daily|one day|1-day/.test(s) && /move|change|jump/.test(s)) { r.m = 'ch1'; r.op = 'absabove'; } else if (/in a week|weekly|1-week/.test(s) && /move|change/.test(s)) { r.m = 'ch5'; r.op = 'absabove'; }
  if (/cross(es)? (above|over)|crosses its|rises? (above|over)|exceeds|breaks above/.test(s)) r.op = r.op === 'absabove' ? r.op : 'xabove'; if (/cross(es)? below|falls? below|drops? below|turns negative|inverts|goes negative/.test(s)) r.op = 'xbelow'; if (/stays? above|is above|above/.test(s) && r.op === 'above') r.op = 'above'; if (/below/.test(s) && r.op === 'above') r.op = 'below';
  const pm = s.match(/(?:(\d+|one|two|three|five|ten)[- ]year\s+)?(\d+)(?:st|nd|rd|th)\s*percentile/); if (pm) { const y = pm[1] ? (GY_NUMW[pm[1]] ?? +pm[1]) : 5; r.thr = { kind: 'pctl', p: +pm[2], yrs: Math.min(10, Math.max(1, y || 5)) }; }
  else { const nm = s.match(/(-?\d+(?:\.\d+)?)\s*(%|bp|basis|bps)/); if (nm) r.thr.v = +nm[1]; else if (/negative|inverts/.test(s)) r.thr.v = 0; else r.thr.v = Math.round((gyRuleVal(r) ?? 0) * (['lvl', 'real'].includes(r.m) ? 10 : 1)) / (['lvl', 'real'].includes(r.m) ? 10 : 1); }
  return r; }
function gyMakeAlert(rule) { if (S.alerts.length >= plan().alerts) { toast('Alert limit reached for your plan', true); return; } const sid = `YD.${rule.a || 'US'}${rule.ten && BY[`YD.${rule.a || 'US'}${rule.ten}`] ? rule.ten : 10}`; S.alerts.unshift({ id: uid(), sid: BY[sid] ? sid : 'YD.US10', kind: 'gyrule', rule: JSON.parse(JSON.stringify(rule)), value: 0, status: 'active', created: Date.now(), checked: null, history: [] }); save(); evalAlerts(false); toast('Alert created: ' + gyRuleText(rule)); if (GY.tab === 'watch') GY.draw(); }
