Object.assign(GX_SEG, { gxper: v => GX.per = v, gxmx: v => GX.mx = v, gxmxm: v => GX.mxM = v });
GX_X.wadd = () => { const b = $('[data-gxc="wb"]').value, q = $('[data-gxc="wq"]').value; if (b === q) return toast('Choose two different currencies', true); const p = gxStd(b, q).join('/'); if (!GX.watch.includes(p)) { GX.watch.push(p); S.fxWatch = GX.watch; save(); } GX.draw(); };
