/* ---------- MACRO & POLICY ---------- */
const GX_PAIRS = ['EUR/USD', 'USD/JPY', 'GBP/USD', 'AUD/USD', 'USD/CAD', 'USD/MXN', 'USD/ZAR', 'USD/BRL', 'USD/INR', 'USD/NGN'];
