  const sens = div.slice(0, 8).map(x => { const [b, q] = gxStd(x.a, x.b); const pr = gxPR(b, q, 250); const dd = D.slice(-250).map((t, i, A) => i ? ((gx2y(b, t) - gx2y(q, t)) - (gx2y(b, A[i - 1]) - gx2y(q, A[i - 1]))) * 100 : 0); const o = gyOLS(dd, pr); return { ...x, b, q, beta: o?.b, r: o?.r, m1: (gxPx(b, q) / gxPx(b, q, t21) - 1) * 100 }; });
