  const bars = [['Dollar index', (t, p) => (valAt('FX.DXY', t) / valAt('FX.DXY', p) - 1) * 100], ['EUR/USD', (t, p) => (gxPx('EUR', 'USD', t) / gxPx('EUR', 'USD', p) - 1) * 100], ['JPY vs USD', (t, p) => (usdPer('JPY', t) / usdPer('JPY', p) - 1) * 100], ['EM currencies', (t, p) => gyM(GX_EM.map(c => (usdPer(c, t) / usdPer(c, p) - 1) * 100))]];
  const EV = [...calAll().filter(e => e.past && e.type === 'cb' && ['FOMC', 'ECB', 'BoE', 'BoJ'].includes(e.d?.k)).map(e => ({ t: e.t, title: e.title, ccy: GX_CBC[e.d.k], kind: e.d.k })), ...['EC.USCPI', 'EC.USNFP', 'EC.UKCPI', 'EC.EAHICP'].flatMap(id => ecoRels(BY[id]).past.slice(-8).map(r => ({ t: r.t, title: BY[id].name, ccy: GX_EVC[BY[id].country], kind: id, r })))].filter(e => e.t < END - 6 * DAY).sort((a, b) => b.t - a.t).slice(0, 24);
