  gyScatter($('#gxSv', el), { h: 300, xlab: `Surprise (${BY[GX.evR].unit})`, ylab: `${pb}/${pq} change, %`, xf: v => sgn(v, 1), yf: v => sgn(v, 2), zeroX: true, zeroY: true, fits: o ? [{ o, color: 'var(--s1)', ci: true }] : [], pts: pts.map(p => ({ x: p.x, y: p.y, r: 5, c: 'var(--s1)', name: fd(p.r.t), extra: [`actual ${eUnit(BY[GX.evR], p.r.act)} vs ${eUnit(BY[GX.evR], p.r.cons)}`] })) });
