function gxEvRx(E, EV) { const D = NX_D(); const i = bsLE(D, E.t); const mv = (f, k) => i - 1 >= 0 && i + k < D.length ? f(D[i + k], D[i - 1]) : null; const c = E.ccy; const cf = (t, p) => c === 'USD' ? (valAt('FX.DXY', t) / valAt('FX.DXY', p) - 1) * 100 : (usdPer(c, t) / usdPer(c, p) - 1) * 100;
  const sim = EV.filter(x => x.kind === E.kind && x !== E); const hs = sim.map(x => { const j = bsLE(D, x.t); return j > 0 && j + 1 < D.length ? Math.abs(cf(D[j + 1], D[j - 1])) : null; }).filter(v => v != null); const m1 = mv(cf, 1); const p = gyPct(hs, Math.abs(m1));
  const slope = E.r ? (() => { const rr = ecoRels(BY[E.kind]).past; const o = gyOLS(rr.map(r => r.surp), rr.map(r => { const j = bsLE(D, r.t); return j > 0 && j + 1 < D.length ? cf(D[j + 1], D[j - 1]) : 0; })); return o?.b; })() : null; const cons = E.r && slope != null ? (Math.sign(E.r.surp * slope) === Math.sign(m1) ? 'Consistent with the historical response to surprises' : 'Opposite to the historical response: other news may have dominated') : 'No consensus for policy decisions (OIS not connected)';
  const rel = [['U.S. 2Y', (t, p) => (govY('US', 2, t) - govY('US', 2, p)) * 100, 'bp'], ['U.S. 10Y', (t, p) => (govY('US', 10, t) - govY('US', 10, p)) * 100, 'bp'], ['Brent', (t, p) => (valAt('CM.CO1', t) / valAt('CM.CO1', p) - 1) * 100, '%'], ['Gold', (t, p) => (valAt('CM.GC1', t) / valAt('CM.GC1', p) - 1) * 100, '%'], ...['EUR', 'JPY', 'GBP'].filter(x => x !== c).map(x => [`${x} vs USD`, (t, p) => (usdPer(x, t) / usdPer(x, p) - 1) * 100, '%']), ['EM basket', (t, p) => gyM(GX_EM.map(x => (usdPer(x, t) / usdPer(x, p) - 1) * 100)), '%']];
  return `<div class="gx-kpis s">${E.r ? `<div><span>Actual vs consensus</span><b>${eUnit(BY[E.kind], E.r.act)} vs ${eUnit(BY[E.kind], E.r.cons)}</b><small>surprise ${sgn(E.r.surp, 2)}</small></div>` : `<div><span>Decision</span><b style="font-size:15px">${esc(E.title)}</b></div>`}${[1, 3, 5].map(k => `<div><span>${c === 'USD' ? 'Dollar index' : c + ' vs USD'} +${k}d</span><b class="${cls(mv(cf, k))}">${pc(mv(cf, k), 2)}</b></div>`).join('')}</div><p class="gy-interp">Next-day move was at the <b>${ordn(p)} percentile</b> of ${hs.length} similar past events. ${cons}.</p><div class="tw"><table class="t dense"><thead><tr><th>Related market</th><th class="r">Next day</th></tr></thead><tbody>${rel.map(([l, f, u]) => `<tr><td>${l}</td><td class="r">${u === 'bp' ? bpf(mv(f, 1), 1) : pc(mv(f, 1), 2)}</td></tr>`).join('')}</tbody></table></div><p class="note">Windows run from the close before the event day. Daily closes cannot isolate the release minute. Simulated.</p><button class="btn sm" data-gxx="evask">Write an event-reaction report with Superfinancials</button>`; }
Object.assign(GX_SEG, { gxevw: v => GX.evW = +v }); GX_X.evR = b => { GX.evR = b.value; GX.draw(); }; GX_X.evP = b => { GX.evP = b.value; GX.draw(); }; GX_X.ev1 = b => { GX.ev1 = +b.value; GX.draw(); }; GX_X.rel = b => { GX.rel = b.value; GX.draw(); };
