  if (/policy change|fx polic|reform/.test(s) && cs.includes('NGN')) { const D = NX_D(); out.crit = ['USD/NGN around documented Nigerian FX policy milestones', '±5 and ±20 sessions']; out.cols = [['l', 'Event'], ['a', '−5d → +5d', v => pc(v, 1)], ['b', '−20d → +20d', v => pc(v, 1)]]; out.rows = GX_NGEV.map(([t, l]) => { const i = bsLE(D, t); const f = k => i - k >= 0 && i + k < D.length ? (gxPx('USD', 'NGN', D[i + k]) / gxPx('USD', 'NGN', D[i - k]) - 1) * 100 : null; return { l: `${fd(t, { month: 'short', year: 'numeric' })} · ${l}`, a: f(5), b: f(20) }; }); out.note = 'Prices on this platform are simulated, so these reactions do NOT show what actually happened around the real events. The workflow is what would run on licensed data.'; out.interp = `${out.rows.length} documented milestones; USD/NGN change (positive = naira weaker) in the windows around each.`; return out; }
  if (/oil/.test(s) && /diverg|relationship/.test(s)) { out.crit = ['3M actual move vs move implied by the prior-year oil beta', 'ranked by gap']; out.cols = [['c', 'Currency'], ['b', 'Oil beta', v => nf(v, 3)], ['e', 'Implied 3M', v => pc(v, 1)], ['a', 'Actual 3M', v => pc(v, 1)], ['g', 'Gap', v => pc(v, 1)]]; const om = (valAt('CM.CO1', END) / valAt('CM.CO1', gyD(63)) - 1) * 100; out.rows = grp.filter(c => c !== 'USD').map(c => { const b = gxBeta(c, 'CM.CO1', 250, 63).b; const a = gxRet(c, '3M'); return { c, b, e: b * om, a, g: a - b * om }; }).sort((x, y) => Math.abs(y.g) - Math.abs(x.g)).slice(0, 10); out.interp = `Brent moved ${pc(om, 1)} over 3 months. Largest divergence: ${out.rows[0].c} (${pc(out.rows[0].g, 1)}).`; out.note = 'Single-factor relationship estimated on the year before the window; other drivers are ignored.'; return out; }
  if (/reer|real effective/.test(s)) { out.crit = ['Model real effective index, percentile of 10 years']; out.cols = [['c', 'Currency'], ['v', 'Model REER', v => nf(v, 1)], ['p', 'Percentile', v => ordn(v)]]; out.rows = grp.filter(c => c !== 'USD').map(c => { const R = gxREER(c); return { c, v: R.v.at(-1), p: gyPct(R.v, R.v.at(-1)) }; }).sort((a, b) => b.p - a.p); out.note = 'Limitations: illustrative basket weights (not trade weights), assumed inflation for several currencies, a 10-year window, and no adjustment for productivity or terms of trade. The IMF and BIS publish official effective rates; index levels alone do not establish over- or undervaluation.'; out.interp = `Highest percentiles: ${out.rows.slice(0, 3).map(r => r.c).join(', ')}; lowest: ${out.rows.slice(-3).map(r => r.c).join(', ')}.`; return out; }
