GX_X.rq = b => { GX.xq = b.dataset.v; gxRun(); }; GX_X.rqask = () => { const R = GX.xr; GX.ask(`Question: "${R.q}". Calculation: ${R.crit.join('; ')}. Result: ${R.rows.slice(0, 10).map(r => R.cols.map(([k, l, f]) => `${l} ${r[k] == null ? '—' : f ? f(r[k]) : r[k]}`).join(', ')).join(' | ')}. Interpret, give caveats and next steps.`); };
GX_X.cat = b => { GX.cat = b.dataset.v; GX.draw(); };
GX_X.write = b => { const c = GX.vc; const P = { daily: "Write today's FX briefing: which currencies moved, the most plausible drivers, whether moves were unusual, and upcoming events. Separate evidence from interpretation and include counterarguments.", weekly: 'Write a weekly FX strategy note: major moves, policy divergence, carry and valuation, EM pressure, catalysts, with assumptions and counterarguments.', outlook: `Write a currency outlook for ${gxN(c)}: drivers, valuation (REER model, PPP, macro fair value), carry, risks and scenarios. Distinguish observations, model estimates and assumptions.`, country: `Write a country FX risk brief for ${gxN(c)}: depreciation, reserves, external financing, liquidity and policy, with the limits of the data. No probability of devaluation.`, event: 'Write an event-reaction report for the most recent major macro release and central-bank decision: actual vs consensus, FX reaction, comparison with past events and limitations.' }[b.dataset.v]; GX.ask(P); };

/* ---------- DATA & SOURCES ---------- */
function gxData(el) {
  const ids = FXL.filter(o => o.type === 'fx' && o.cls === 'FX spot'); const D = NX_D();
  const rows = ids.map(o => { const s = series(o.id); const c = o.base === 'USD' ? o.quote : o.base; const fr = GXC[c]?.cls === 'Frontier'; const xs = gyDx(o.id, 80); const sd = gySd(xs.slice(0, 60)); const out = xs.slice(-20).filter(v => sd && Math.abs(v) > 4 * sd).length; const st = GXC[c]?.cc && gyStale(GXC[c].cc); return { o, c, fr, first: s.d[0], out, st }; });
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Series inventory & data quality</span><span class="pm">${rows.length} directly quoted pairs · crosses calculated</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Pair</th><th>Convention</th><th>Rate type</th><th>Timestamp</th><th>Observed / calculated</th><th>Frequency</th><th>History from</th><th>Stale / outliers (20d)</th><th>Licence status</th></tr></thead><tbody>${rows.map(r => `<tr><td><b>${r.o.base}/${r.o.quote}</b></td><td class="sub">${esc(r.o.conv)}</td><td><span class="gy-q ${r.fr ? 'ind' : ''}">${r.fr ? 'Indicative mid' : 'Closing mid'}</span></td><td class="sub">${fd(r.st ? gyD(2) : END)} 17:00 New York</td><td>Simulated observation</td><td>Daily EOD</td><td>${fd(r.first, { month: 'short', year: 'numeric' })}</td><td class="${r.st || r.out ? 'dn' : ''}">${r.st ? 'stale' : '—'}${r.out ? ` · ${r.out} outlier day(s)` : ''}</td><td class="sub">Simulated; no redistribution restrictions</td></tr>`).join('')}<tr><td><b>Any other cross</b></td><td class="sub">Quote per 1 base</td><td>Calculated mid</td><td class="sub">Same as legs</td><td>Calculated via USD</td><td>Daily EOD</td><td>Shorter leg</td><td>Inherits legs</td><td class="sub">—</td></tr><tr><td><b>USD/NGN (three series)</b></td><td class="sub">NGN per 1 USD</td><td>Official · dealer · alternative</td><td class="sub">EOD</td><td>Observed · derived · illustrative</td><td>Daily</td><td>${fd(D[0], { month: 'short', year: 'numeric' })}</td><td>see EM tab</td><td class="sub">Never combined into one series</td></tr></tbody></table></div></div></section>
    <div class="grid"><section class="panel c6"><header class="ph"><span class="pt">Rules applied on every screen</span></header><div class="pb"><ul class="mv-its"><li>Every pair states its base and quote: B/Q = units of Q per 1 B. Currency "returns" are the change in the currency's value (positive = stronger).</li><li>Official rates, dealer quotes, indicative prices and alternative-market observations are labelled as distinct series and never merged into one continuous line.</li><li>Crosses are calculated from USD legs and labelled "calculated"; day high/low is shown only for directly quoted pairs.</li><li>Model estimates (REER model, PPP, macro fair value, forwards, scenarios) are labelled and never presented as market prices.</li><li>Illustrative inputs (reserves, import cover, several policy rates and inflation rates, basket weights) are marked as such.</li><li>Not connected: implied volatility and options, NDF and forward quotes, cross-currency basis, OIS, balance-of-payments flows, positioning, elections and policy announcements.</li></ul></div></section>
      <section class="panel c6"><header class="ph"><span class="pt">Production data sources (when licensed)</span></header><div class="pb"><div class="tw"><table class="t dense"><thead><tr><th>Category</th><th>Potential sources</th></tr></thead><tbody>${[['Reference & historical rates', 'IMF data, BIS statistics, central banks'], ['Effective exchange rates', 'IMF EER dataset, BIS EER statistics'], ['Market & indicative prices', 'Licensed vendors (e.g. LSEG, ICE)'], ['Forwards & NDFs', 'Licensed vendors; documented local sources'], ['Options & implied volatility', 'CME Group; licensed OTC providers'], ['Macro indicators', 'IMF, World Bank, national statistics agencies, central banks'], ['Interest rates', 'Central banks, BIS, licensed providers'], ['Capital flows & external balances', 'IMF balance-of-payments data, national authorities'], ['Market structure', 'BIS Triennial Survey; licensed trade data']].map(([a, b]) => `<tr><td>${a}</td><td class="sub" style="white-space:normal">${b}</td></tr>`).join('')}</tbody></table></div><p class="note">Availability, history, latency and redistribution rights depend on each vendor agreement. Publication frequency and observation timestamps must be preserved.</p></div></section></div>`;
}

/* ---------- AI facts ---------- */
function gxFacts() { const r = v => r2(v); return { fx_tab: GX_TABS.find(t => t[0] === GX.tab)?.[1], conventions: 'Pair B/Q = Q per 1 B; currency return positive = stronger vs USD. All prices simulated EOD; several rates, inflation, reserves illustrative.', currencies: GX_ALL.filter(c => c !== 'USD').map(c => ({ ccy: c, name: gxN(c), class: GXC[c].cls, region: GXC[c].reg, ret_1d: r(gxRet(c, '1D')), ret_1w: r(gxRet(c, '1W')), ret_1m: r(gxRet(c, '1M')), ret_ytd: r(gxRet(c, 'YTD')), ret_1y: r(gxRet(c, '1Y')), vol_3m: r(gxVol(c, 'USD', 63)), short_rate: r(gxRate(c)), rate_source: gxRateSrc(c), carry_vs_usd: r(gxCarry(c, 'USD')), real_rate: r(gxReal(c)), inflation_basis: gxInf(c).kind, regime: gxRegime(c).lab, reer_model_pctl: r(gyPct(gxREER(c).v, gxREER(c).v.at(-1))), stress_warnings: GXC[c].cls !== 'G10' ? gxStressInd(c).filter(x => x.bad).map(x => x.l) : undefined })), dollar_index: r(valAt('FX.DXY', END)), dollar_index_1w_pct: r((valAt('FX.DXY', END) / valAt('FX.DXY', gyD(5)) - 1) * 100), naira: { official: r(gxNg().off.at(-1)), dealer: r(gxNg().dealer.at(-1)), alternative_illustrative: r(gxNg().alt.at(-1)) }, insights: gxInsights().slice(0, 10).map(c => ({ category: GX_CAT[c.cat], headline: c.head, evidence: c.ev, confidence: c.conf })), watchlist: GX.watch }; }
{ const _ffx = factsFor; factsFor = function (r, p) { const f = _ffx(r, p); if (r === 'fx') { try { Object.assign(f, gxFacts()); } catch (e) { f.note = 'Some FX figures could not be computed.'; } } return f; }; }

/* ---------- page ---------- */
Object.assign(GX_FN, { ov: gxOv, pair: gxPair, val: gxVal, macro: gxMacro, em: gxEM, carry: gxCarryTab, flows: gxFlows, risk: gxRisk, ai: gxAI, data: gxData });
const GX_OLD = PAGES.fx;
PAGES.fx = pg => {
  if (S.fxWatch) GX.watch = S.fxWatch; if (state.p && GX_TABS.some(t => t[0] === state.p)) GX.tab = state.p;
  pg.innerHTML = hdr('fx', `Currencies intelligence: why currencies move, where pressure is building, how policy and flows affect exchange rates, and which exposures deserve attention, across ${GX_ALL.length} currencies. ${simB('SIM EOD')} Prices simulated; rate types and model estimates labelled.`, '') + `
    <nav class="fi-nav gx-nav" role="tablist">${GX_TABS.map(([k, l]) => `<button role="tab" class="${GX.tab === k ? 'on' : ''}" data-gxt="${k}">${l}</button>`).join('')}</nav>
    <section class="panel fi-askp"><div class="pb"><form class="nx-ask" id="gxAsk"><span class="nx-lab">AI FX strategist</span><input class="inp" id="gxAq" maxlength="300" placeholder="What is driving the dollar this week?" aria-label="Ask about currencies"><button class="btn pri" type="submit">Ask Superfinancials</button><button class="btn" type="button" data-gxx="write" data-v="daily">Daily FX briefing</button></form></div></section><div id="gxBody" class="gy-body gx-body"></div>`;
  const body = $('#gxBody', pg);
  const draw = () => { $$('[data-gxt]', pg).forEach(b => b.classList.toggle('on', b.dataset.gxt === GX.tab)); destroyCharts(); try { if (GX.tab === 'old') { GX_OLD(body); $('.phd', body)?.remove(); } else (GX_FN[GX.tab] || gxOv)(body); } catch (e) { console.error(e); body.innerHTML = `<div class="callout">This view failed to load: ${esc(e.message)}</div>`; } };
  const ask = q => { const el = $$('.aip', pg)[0]; if (!el) return toast('AI insights are turned off for your account by your organization', true); el.scrollIntoView({ behavior: 'smooth', block: 'start' }); runInsight(el, q); };
  GX.draw = draw; GX.ask = ask; GX.go = k => { GX.tab = k; state.p = k; try { history.replaceState(null, '', '#fx.' + k); } catch (x) { } draw(); $('.gx-nav', pg)?.scrollIntoView({ block: 'start', behavior: 'smooth' }); };
  draw();
  on(pg, 'click', '[data-gxt]', (e, b) => GX.go(b.dataset.gxt));
  on(pg, 'click', '[data-seg] button', (e, b) => { const k = b.closest('[data-seg]').dataset.seg; if (GX_SEG[k]) { GX_SEG[k](b.dataset.v); draw(); } });
  on(pg, 'click', '[data-gxx]', (e, b) => { if (GX_X[b.dataset.gxx]) { e.preventDefault(); e.stopPropagation(); GX_X[b.dataset.gxx](b, e); } });
  on(pg, 'change', '[data-gxc]', (e, b) => { if (GX_X[b.dataset.gxc]) GX_X[b.dataset.gxc](b, e); });
  $('#gxAsk', pg).onsubmit = e => { e.preventDefault(); const q = $('#gxAq', pg).value.trim(); if (q) ask(q); };
  pg.addEventListener('keydown', e => { if (e.key === 'Escape' && $('#gyDrawer') && !$('#gyDrawer').hidden) $('#gyClose').click(); });
};

