const CMX = Object.fromEntries(CM_META.filter(m => BY[m[0]]).map(([id, s, g, loc, cmo, cy, sa, inv, roll, prod]) => [id, { id, s, g, loc, cmo, cy, sa, inv, roll, prod }]));
const CM_IDS = Object.keys(CMX); const CM_FUT = CM_IDS.filter(id => CMX[id].cmo > 0);
const cmN = id => BY[id]?.name || id; const cmTk = id => BY[id]?.tk || id;
const cmU = id => BY[id]?.unit || ''; const cmP = (id, t = END) => valAt(id, t);
const cmF = (id, v) => v == null ? '—' : nf(v, v >= 1000 ? 0 : v >= 100 ? 1 : v >= 10 ? 2 : 3);
const cmRet = (id, k, t = END) => { const D = NX_D(); const i = bsLE(D, t); return (cmP(id, D[i]) / cmP(id, D[Math.max(0, i - k)]) - 1) * 100; };
const CM_PER = [['1D', 1], ['1W', 5], ['1M', 21], ['3M', 63], ['YTD', 'ytd'], ['1Y', 252], ['5Y', 1260]];
const cmK = p => p === 'YTD' ? gxK('YTD') : (CM_PER.find(x => x[0] === p) || [0, 21])[1];
const cmVol = (id, n = 63, back = 0) => gySd(gyDx(id, n, back)) * Math.sqrt(252);
const cmKind = id => { const c = BY[id].cls; return /assessment/i.test(c) || /illustrative/i.test(BY[id].exch) ? ['ind', 'Assessment / illustrative'] : /Spot/.test(c) ? ['obs', 'Spot (simulated)'] : /index/i.test(c) ? ['obs', 'Index (simulated)'] : ['obs', 'Futures settlement (simulated)']; };
const CM_MO = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

/* ---------- inventories (model) ---------- */
const CMI = {};
function cmInv(id) { if (CMI[id]) return CMI[id]; const m = CMX[id]; if (!m?.inv) return null; const [name, unit, base, amp, pk, use, src] = m.inv; const W = GXW(); const r = rng(hash('inv' + id)); const vol = cmVol(id, 252) / 100 || .25; let d = 0; const v = [], dev = [];
  W.forEach((t, i) => { const p = Math.log(cmP(id, t)), p0 = Math.log(cmP(id, W[Math.max(0, i - 26)])); const z = (p - p0) / (vol * Math.sqrt(.5)); d = .9 * d + .1 * (-.35 * z) + (r() - .5) * .025; const woy = Math.floor((new Date(t) - Date.UTC(new Date(t).getUTCFullYear(), 0, 1)) / (7 * DAY)); const sea = 1 + amp * Math.cos(2 * Math.PI * (woy - pk) / 52); dev.push(d); v.push(base * sea * (1 + d)); });
  return CMI[id] = { W, v, dev, name, unit, base, use, src }; }
function cmInvSeason(id, yrs = 5) { const I = cmInv(id); if (!I) return null; const byY = {}; I.W.forEach((t, i) => { const d = new Date(t); const y = d.getUTCFullYear(); const w = Math.min(51, Math.floor((t - Date.UTC(y, 0, 1)) / (7 * DAY))); (byY[y] = byY[y] || [])[w] = I.v[i]; }); const ys = Object.keys(byY).map(Number).sort(); const cur = ys.at(-1); const hist = ys.filter(y => y < cur).slice(-yrs); const lo = [], hi = [], avg = []; for (let w = 0; w < 52; w++) { const xs = hist.map(y => byY[y][w]).filter(v => v != null); lo.push(xs.length ? Math.min(...xs) : null); hi.push(xs.length ? Math.max(...xs) : null); avg.push(xs.length ? gyM(xs) : null); } return { byY, ys, cur, hist, lo, hi, avg }; }
function cmInvStat(id) { const I = cmInv(id); if (!I) return null; const S = cmInvSeason(id); const n = I.v.length; const last = I.v[n - 1]; const w = Math.min(51, Math.floor((END - Date.UTC(new Date(END).getUTCFullYear(), 0, 1)) / (7 * DAY))); const hs = S.hist.map(y => S.byY[y][w]).filter(v => v != null); const pct = gyPct(hs.concat([last]), last); const vsAvg = S.avg[w] ? (last / S.avg[w] - 1) * 100 : null; const ch4 = last - I.v[n - 5], ch1 = last - I.v[n - 2]; const ws = []; for (let i = n - 1; i > n - 260 && i > 1; i--) ws.push(I.v[i] - I.v[i - 1]); const z = gySd(ws) ? ch1 / gySd(ws) : 0; return { last, pct, vsAvg, ch1, ch4, z, cover: I.use ? last / I.use : null, unit: I.unit, name: I.name, src: I.src, avg: S.avg[w], lo: S.lo[w], hi: S.hi[w] }; }

/* ---------- futures curves (model) ---------- */
function cmCurve(id, t = END) { const m = CMX[id]; if (!m || !m.cmo) return null; const W = GXW(); const I = cmInv(id); let dev = 0; if (I) dev = I.dev[Math.max(0, bsLE(W, t))]; else { const r = rng(hash('cdev' + id + Math.floor(t / (7 * DAY)))); const p = Math.log(cmP(id, t)), p0 = Math.log(cmP(id, t - 182 * DAY)); dev = -.25 * (p - p0) / ((cmVol(id, 252) / 100 || .25) * .7) + (r() - .5) * .02; dev = Math.max(-.3, Math.min(.3, dev)); }
  const s = m.cy + .05 * dev; const P = cmP(id, t); const d0 = new Date(t); const fm = d0.getUTCMonth() + 1; const [amp, pk] = m.sa; const sea = mo => amp * Math.cos(2 * Math.PI * ((mo % 12) - (pk - 1)) / 12); const out = []; for (let k = 0; k <= m.cmo; k++) { const mo = (d0.getUTCMonth() + 1 + k) % 12; out.push({ k, lab: `${CM_MO[mo]} ${String(d0.getUTCFullYear() + Math.floor((d0.getUTCMonth() + 1 + k) / 12)).slice(2)}`, p: P * Math.exp(s * k + sea(mo) - sea(fm % 12)) }); } return out; }
const cmSpr = (id, a, b, t = END) => { const c = cmCurve(id, t); return c ? c[a].p - c[Math.min(b, c.length - 1)].p : null; };
const cmSlope = (id, t = END) => { const c = cmCurve(id, t); if (!c) return null; const n = Math.min(12, c.length - 1); return (c[n].p / c[0].p - 1) * 100; };
const cmPctW = p => p >= 100 ? 'above the 5-year seasonal range' : p <= 0 ? 'below the 5-year seasonal range' : ordn(p) + ' seasonal percentile';
const cmShape = v => v == null ? '—' : v < -2 ? 'Backwardation' : v > 2 ? 'Contango' : 'Flat';
function cmSprHist(id, a, b, n = 1260) { const D = NX_D(); const out = []; for (let i = D.length - 1; i >= Math.max(0, D.length - n); i -= 5) out.push(cmSpr(id, a, b, D[i])); return out.reverse(); }

/* ---------- positioning (model of a COT-style report) ---------- */
const CMPOS = {};
function cmPos(id) { if (CMPOS[id]) return CMPOS[id]; if (!CMX[id]?.cmo) return null; const W = GXW(); const r = rng(hash('cot' + id)); const vol = cmVol(id, 252) / 100 || .25; let e = 0; const mm = [], oi = []; let o = 100; W.forEach((t, i) => { const r13 = Math.log(cmP(id, t) / cmP(id, W[Math.max(0, i - 13)])); e = .8 * e + (r() - .5) * 6; mm.push(Math.max(-45, Math.min(65, 32 * Math.tanh(r13 / (vol * .5)) + 8 + e))); o = o * (1 + (r() - .5) * .04) + (100 - o) * .02; oi.push(o); }); return CMPOS[id] = { W, mm, oi }; }
function cmPosStat(id) { const P = cmPos(id); if (!P) return null; const n = P.mm.length; const last = P.mm[n - 1]; const pct = gyPct(P.mm.slice(-260), last); return { last, pct, ch4: last - P.mm[n - 5], oiCh: (P.oi[n - 1] / P.oi[n - 5] - 1) * 100, asof: P.W[n - 1] - 3 * DAY }; }

/* ---------- supply-demand balances (illustrative, quarterly) ---------- */
const CM_BAL = { 'CM.CO1': ['World petroleum', 'mb/d', 102, 1.1, .6, 'Production', 'Consumption'], 'CM.HG1': ['World refined copper', 'kt/quarter', 6800, 2.8, .12, 'Refined production', 'Refined consumption'], 'CM.ZC1': ['World corn', 'Mt/quarter', 300, 1.6, .05, 'Production (crop-year spread)', 'Use'], 'CM.NG1': ['U.S. natural gas', 'Bcf/d', 104, 2, .5, 'Dry production + imports', 'Consumption + exports'], 'CM.CC1': ['World cocoa', 'kt/quarter', 1200, 1, .3, 'Grindings-adjusted production', 'Grindings'], 'CM.ALI': ['World primary aluminium', 'kt/quarter', 18000, 2.5, .1, 'Production', 'Consumption'] };
const CMB = {};
function cmBal(id) { if (CMB[id]) return CMB[id]; const b = CM_BAL[id]; if (!b) return null; const [name, unit, base, gr, sd] = b; const r = rng(hash('bal' + id)); const q0 = new Date(END); const curQ = q0.getUTCFullYear() * 4 + Math.floor(q0.getUTCMonth() / 3); const rows = []; let bal = 0; for (let q = curQ - 18; q <= curQ + 5; q++) { const y = Math.floor(q / 4), qq = q % 4; const cons = base * Math.pow(1 + gr / 100, (q - curQ) / 4) * (1 + .012 * Math.cos(2 * Math.PI * (qq - 2) / 4)); const t = Date.UTC(y, qq * 3 + 1, 15); const ret = t <= END ? Math.log(cmP(id, Math.min(t, END)) / cmP(id, Math.max(t - 91 * DAY, NX_D()[0]))) : 0; bal = .6 * bal + (r() - .5) * sd * base / 100 * 2.2 - ret * base * .004; const prod = cons + bal; const st = t < END - 120 * DAY ? 'Actual' : t < END ? 'Estimate' : 'Forecast'; const rev = st === 'Actual' ? 0 : (r() - .5) * sd * base / 100 * 1.2; rows.push({ q: `${y} Q${qq + 1}`, t, prod, cons, chg: prod - cons, st, prior: { prod: prod - rev * .6, cons: cons + rev * .4 }, price: t <= END ? gyM(NX_D().filter(d => d > t - 91 * DAY && d <= Math.min(t + 45 * DAY, END)).map(d => cmP(id, d))) : null }); } return CMB[id] = { name, unit, rows, lp: b[5], lc: b[6] }; }

