function cmWx(i) { const [name, lat, lon, ids, note, [s0, s1]] = CM_REG[i]; const mo = new Date(END).getUTCMonth() + 1; const inS = s0 <= s1 ? mo >= s0 && mo <= s1 : mo >= s0 || mo <= s1; const r = rng(hash('wx' + name + iso(END).slice(0, 7))); const ta = (r() - .45) * 3.2, pa = Math.round((r() - .5) * 70); const fta = ta + (r() - .5) * 1.5, unc = .8 + r() * 1.2; const sc = Math.abs(ta) * .5 + Math.max(0, -pa) / 25 + r() * .6; const cond = !inS ? 5 : sc < .6 ? 0 : sc < 1.3 ? 1 : sc < 1.9 ? 2 : sc < 2.6 ? 3 : 4; return { name, lat, lon, ids, note, inS, ta, pa, fta, unc, cond, risk: inS ? sc : 0 }; }
