  const lngEU = hh * 1.15 + 2.75 + .8, lngAS = hh * 1.15 + 2.75 + 1.9; const wti = cmP('CM.CL1'), br = cmP('CM.CO1'); const td = cmP('CM.TD3C') / 7.33;
