/* ---------- SCENARIOS & RISK ---------- */
const CM_ST = { oil30: ['Oil −30%', { 'CM.CO1': -30, 'CM.CL1': -30 }], gold15: ['Gold +15%', { 'CM.GC1': 15 }], cu20: ['Copper −20%', { 'CM.HG1': -20 }], gr25: ['Grains +25%', { 'CM.ZC1': 25, 'CM.ZS1': 25, 'CM.ZW1': 25 }], gas50: ['Natural gas +50%', { 'CM.NG1': 50, 'CM.TTF': 50 }], frt: ['Freight +25% and a major export route disrupted', { 'CM.CO1': 8, 'CM.UREA': 12, 'CM.BDIX': 25, 'CM.TD3C': 60 }] };
const CM_PF0 = [['EQ.XOM', 120000], ['EQ.FCX', 80000], ['EQ.NEM', 60000], ['EQ.ADM', 50000], ['EQ.CF', 40000], ['ET.GLD', 70000], ['ET.USO', 30000], ['EQ.VLO', 40000]];
function cmScen(el) {
  const id = CM.sc; const b = cmBal(id); const I = cmInv(id); const A = CM.scA;
  const el2 = (() => { if (!I) return { b: -1.5, r: 0 }; const xs = [], ys = []; for (let i = 13; i < I.v.length; i += 4) { xs.push((I.dev[i] - I.dev[i - 13]) * 100); ys.push(Math.log(cmP(id, I.W[i]) / cmP(id, I.W[i - 13])) * 100); } return gyOLS(xs, ys) || { b: -1.5, r: 0 }; })();
  const base = b.rows.find(r => r.st !== 'Actual') || b.rows.at(-1); const cons = base.cons; const dBal = (A.sup / 100) * cons - (A.dem / 100) * cons; const qs = A.q; const cumPct = dBal * qs / (cons * .25 * 4) * 100; const pChg = el2.b * cumPct;
  const fan = CM.fan; const D = NX_D().slice(-252); const sp = cmP(fan); const vol = cmVol(fan, 252) / 100; const fut = []; for (let k = 1; k <= 60; k++) fut.push(END + k * 7 * DAY); const X = [...D, ...fut]; const nh = D.length; const LAST = nh + 51; const yr = i => i < nh ? null : (i - nh + 1) * 7 / 365.25; const crv = cmCurve(fan);
  const fs = CM.fanS || { base: crv ? crv[Math.min(12, crv.length - 1)].p : sp, up: sp * Math.exp(vol), dn: sp * Math.exp(-vol) }; CM.fanS = fs; const path = e => X.map((_, i) => i < nh - 1 || i > LAST ? null : i === nh - 1 ? sp : sp * Math.pow(e / sp, yr(i))); const cone = k => X.map((_, i) => i < nh - 1 || i > LAST ? null : i === nh - 1 ? sp : sp * Math.exp(k * vol * Math.sqrt(yr(i))));
  S.cmPort = S.cmPort || CM_PF0.map(([i, v]) => ({ id: i, v })); const pf = S.cmPort.filter(h => BY[h.id]); const sh = CM_ST[CM.st][1];
  const rows = pf.map(h => { let pl = 0; const parts = []; Object.entries(sh).forEach(([cid, pct]) => { const be = h.id === cid ? 1 : (gyOLS(gyDx(cid, 250), gyDx(h.id, 250))?.b || 0); const r2 = gyOLS(gyDx(cid, 250), gyDx(h.id, 250))?.r2 || 0; if (Math.abs(be) < .02 && h.id !== cid) return; const c = h.v * be * pct / 100 * (h.id === cid ? 1 : Math.min(1, r2 * 2 + .2)); pl += c; parts.push(`${cmTk(cid)} β${nf(be, 2)}`); }); return { ...h, pl, parts }; }); const tot = rows.reduce((s, r) => s + r.pl, 0), tv = pf.reduce((s, h) => s + h.v, 0);
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Supply-demand scenario lab</span><span class="pm">${esc(b.name)}</span></header><div class="pb"><div class="row" style="gap:8px">${cmSel(id, 'sc', Object.keys(CM_BAL))}</div><div class="gy-sliders">${[['sup', 'Supply change, %', -10, 10, .5], ['dem', 'Demand change, %', -10, 10, .5], ['q', 'Duration, quarters', 1, 8, 1]].map(([k, l, a, bb, st]) => `<label><span>${l} <b id="csa_${k}">${A[k]}</b></span><input type="range" min="${a}" max="${bb}" step="${st}" value="${A[k]}" data-csa="${k}"></label>`).join('')}</div>
      <div class="gx-kpis"><div><span>Balance change</span><b class="${cls(dBal)}">${sgn(dBal, 2)} ${esc(b.unit)}</b><small>${gyProv('A')} your supply & demand inputs</small></div><div><span>Cumulative stock change</span><b>${sgn(cumPct, 1)}%</b><small>of a quarter's consumption-equivalent stocks ${gyProv('M')}</small></div><div><span>Price sensitivity to stocks</span><b>${nf(el2.b, 2)}</b><small>% price per pt of stock deviation ${gyProv('H')} r ${nf(el2.r, 2)}</small></div><div><span>Implied price change</span><b class="${cls(pChg)}">${pc(pChg, 1)}</b><small>${gyProv('M')} ${Math.abs(el2.r) < .2 ? 'weak relationship: high uncertainty' : ''}</small></div></div><p class="note">Structure: balance change × duration → stock change → price via the historical stock–price relationship (13-week changes, simulated history). Assumes no demand response, policy action or substitution. Where the relationship is weak, the model cannot reliably estimate the outcome.</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Price scenario fan chart</span></header><div class="pb"><div class="row" style="gap:8px;flex-wrap:wrap;align-items:center">${cmSel(fan, 'fan')}<label class="note">Baseline <input class="inp sm" type="number" step="any" value="${+fs.base.toFixed(2)}" data-cmfan="base" style="width:100px"></label><label class="note">Upside <input class="inp sm" type="number" step="any" value="${+fs.up.toFixed(2)}" data-cmfan="up" style="width:100px"></label><label class="note">Downside <input class="inp sm" type="number" step="any" value="${+fs.dn.toFixed(2)}" data-cmfan="dn" style="width:100px"></label><button class="btn sm ghost" data-cmx="fanreset">Reset</button></div><div id="cmFan"></div>${gxLeg([['var(--fg)', cmN(fan)], ['var(--s4)', '±1 / ±2 sd cone (realized vol)', 1], ...(crv ? [['var(--s4)', 'Futures curve (model)']] : []), ['var(--up)', 'Baseline'], ['var(--s1)', 'Upside'], ['var(--dn)', 'Downside']])}<p class="note">Cone from 1-year realized volatility (${nf(vol * 100, 0)}%), statistical, not a forecast. Scenario end-points are your assumptions (defaults: 12-month futures point and ±1 sd); link them to explicit production, demand, inventory, currency and freight assumptions above.</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Portfolio stress tests</span><span class="pm">commodity-linked holdings</span></header><div class="pb"><div class="gx-scs">${Object.entries(CM_ST).map(([k, [l]]) => `<button class="gx-sc ${k === CM.st ? 'on' : ''}" data-cmx="st" data-v="${k}"><span>${esc(l)}</span></button>`).join('')}</div><div class="gx-kpis s"><div><span>Estimated P&amp;L</span><b class="${cls(tot)}">${big(tot, '$')}</b><small>${pc(tot / tv * 100, 2)} of ${big(tv, '$')}</small></div><div><span>Shocks ${gyProv('A')}</span><b style="font-size:14px">${Object.entries(sh).map(([c, v]) => `${cmTk(c)} ${sgn(v, 0)}%`).join(', ')}</b></div></div>
      <div class="tw"><table class="t dense"><thead><tr><th>Holding</th><th class="r">Value</th><th>Linked via ${gyProv('H')}</th><th class="r">Scenario P&amp;L</th><th></th></tr></thead><tbody>${rows.map((r, i) => `<tr><td><a href="#sec.${r.id}" data-sec="${r.id}">${esc(BY[r.id].tk)}</a> <span class="sub">${esc(BY[r.id].name)}</span></td><td class="r"><input class="inp sm" type="number" step="1000" value="${r.v}" data-cmpf="${i}" style="width:100px"></td><td class="sub">${r.parts.join(', ') || 'no material link'}</td><td class="r ${cls(r.pl)}">${big(r.pl, '$')}</td><td><button class="btn sm ghost" data-cmx="pfrm" data-v="${i}" aria-label="Remove">✕</button></td></tr>`).join('')}</tbody></table></div><div class="row" style="gap:6px;margin-top:8px"><select class="inp sm" data-cms="pfadd">${[...EQ.filter(o => CM_CO.some(c => c[0] === o.id)), ...CMD.filter(o => o.type === 'etf')].map(o => `<option value="${o.id}">${esc(o.tk)} · ${esc(o.name)}</option>`).join('')}</select><button class="btn sm" data-cmx="pfadd">Add holding</button></div>
      ${CM.st === 'frt' ? `<h6>Oil and fertilizer markets under this scenario</h6><dl class="kl"><div><dt>Crude</dt><dd>Delivered prices rise more than benchmarks: freight adds ≈${nf(cmP('CM.TD3C') / 7.33 * .6, 2)} $/bbl on Middle East → Asia; disrupted route forces longer voyages and ties up tankers ${gyProv('A')}</dd></div><div><dt>Fertilizers</dt><dd>Urea assumed +12%: importers in Africa and South Asia face higher landed costs; affordability vs corn deteriorates ${gyProv('A')}</dd></div><div><dt>Second-round</dt><dd>Higher fuel and fertilizer costs feed food prices with a lag (not modelled)</dd></div></dl>` : ''}<p class="note">P&amp;L = value × beta to each shocked commodity × shock, damped where the historical fit is weak; direct holdings take the shock in full. Betas from simulated daily returns; correlations between shocks are not modelled.</p></div></section>`;
  gxChart($('#cmFan', el), { h: 320, x: X, split: nh - 1, splitLab: 'today', series: [{ v: X.map((t, i) => i < nh ? cmP(fan, t) : null), c: 'var(--fg)', label: cmN(fan) }, ...(crv ? [{ v: X.map((_, i) => { if (i < nh - 1 || i > LAST) return null; const m = Math.min(crv.length - 1, Math.round((i - nh + 1) * 7 / 30.4)); return crv[m].p; }), c: 'var(--s4)', label: 'Futures curve', dash: '3 3' }] : []), { v: path(fs.base), c: 'var(--up)', label: 'Baseline', pts: [LAST], lab: v => cmF(fan, v) }, { v: path(fs.up), c: 'var(--s1)', label: 'Upside', pts: [LAST], lab: v => cmF(fan, v) }, { v: path(fs.dn), c: 'var(--dn)', label: 'Downside', pts: [LAST], lab: v => cmF(fan, v) }], bands: [{ lo: cone(-2), hi: cone(2), c: 'var(--s4)', op: .12, label: '±2 sd' }, { lo: cone(-1), hi: cone(1), c: 'var(--s4)', op: .16, label: '±1 sd' }], fl: v => cmF(fan, v) });
  $$('[data-csa]', el).forEach(i => { i.oninput = () => { $('#csa_' + i.dataset.csa).textContent = i.value; }; i.onchange = () => { CM.scA[i.dataset.csa] = +i.value; CM.draw(); }; });
  $$('[data-cmfan]', el).forEach(i => i.onchange = () => { CM.fanS[i.dataset.cmfan] = +i.value; CM.draw(); }); $$('[data-cmpf]', el).forEach(i => i.onchange = () => { S.cmPort[+i.dataset.cmpf].v = +i.value; save(); CM.draw(); });
}
CM_X.sc = b => { CM.sc = b.value; CM.draw(); }; CM_X.fan = b => { CM.fan = b.value; CM.fanS = null; CM.draw(); }; CM_X.fanreset = () => { CM.fanS = null; CM.draw(); }; CM_X.st = b => { CM.st = b.dataset.v; CM.draw(); };
CM_X.pfrm = b => { S.cmPort.splice(+b.dataset.v, 1); save(); CM.draw(); }; CM_X.pfadd = () => { const v = $('[data-cms="pfadd"]').value; S.cmPort.push({ id: v, v: 50000 }); save(); CM.draw(); };

/* ---------- AI COMMODITIES ANALYST ---------- */
function cmResearch(q) { const s = q.toLowerCase(); const out = { q, crit: [], cols: [], rows: [], note: '', interp: '', ask: false, go: null };
  if (/memo|critical-mineral|critical mineral/.test(s) && /memo|generate|write/.test(s)) { out.ask = true; return out; }
  if (/bottom|lowest|near the low/.test(s) && /range|five-year|5-year/.test(s)) { out.crit = ['Price percentile within its 5-year weekly range', 'lowest first']; out.cols = [['n', 'Commodity'], ['p', '5Y percentile', v => ordn(v)], ['r', '1Y', v => pc(v, 1)]]; out.rows = CM_IDS.filter(id => CMX[id].s !== 'ix').map(id => ({ n: cmN(id), p: cmPct5(id), r: cmRet(id, 252) })).sort((a, b) => a.p - b.p).slice(0, 10); out.interp = `Closest to their 5-year lows: ${out.rows.slice(0, 3).map(r => r.n).join(', ')}.`; return out; }
  if (/inventor/.test(s) && /curve|tighten|front/.test(s)) { out.crit = ['Energy', 'Inventories down over 4 weeks', 'M1→M12 slope fell over 1 month (front tightening)']; out.cols = [['n', 'Market'], ['i', '4-week stock change'], ['c', 'Curve 1M ago → now'], ['m', 'Both conditions']]; out.rows = CM_IDS.filter(id => CMX[id].s === 'en' && CMX[id].inv).map(id => { const st = cmInvStat(id); const c0 = cmSlope(id, gyD(21)), c1 = cmSlope(id); return { n: cmN(id), i: `${sgn(st.ch4, 1)} ${st.unit}`, c: `${sgn(c0, 1)}% → ${sgn(c1, 1)}%`, m: st.ch4 < 0 && c1 < c0 ? 'Yes' : 'No', ok: st.ch4 < 0 && c1 < c0 }; }).sort((a, b) => b.ok - a.ok); out.interp = `${out.rows.filter(r => r.ok).length} energy market(s) meet both conditions.`; out.note = 'Inventories and curves are modelled from simulated prices.'; return out; }
  if (/copper/.test(s) && /alumin/.test(s) && /lithium/.test(s)) { out.crit = ['Inventory percentile', 'New capacity (illustrative)', 'Electrification demand share (approx.)']; out.cols = [['n', 'Metal'], ['inv', 'Inventory'], ['cap', 'New capacity pipeline'], ['el', 'Electrification share of demand'], ['r', 'Price 1Y', v => pc(v, 1)]]; out.rows = [['CM.HG1', 'Mine projects slow (10–15 yrs lead time)', 'Grids, EVs, data centres; rising'], ['CM.ALI', 'Smelting capped in China; new capacity elsewhere', 'Grids, EV lightweighting'], ['CM.LIC', 'Large additions in recent years; some paused', 'Batteries: the majority of demand']].map(([id, c, e]) => ({ n: cmN(id), inv: CMX[id].inv ? `${ordn(cmInvStat(id).pct)} seasonal pctl` : 'no exchange stocks', cap: c, el: e, r: cmRet(id, 252) })); out.note = 'Capacity and demand descriptions are qualitative summaries of public outlooks (IEA, ICSG); verify.'; out.interp = 'Copper combines slow supply response with electrification demand; lithium has seen faster supply additions.'; return out; }
  if (/weather/.test(s)) { out.crit = ['Agricultural regions in season', 'Condition Watch or worse', 'ranked by risk score']; out.cols = [['n', 'Region'], ['m', 'Markets'], ['c', 'Condition'], ['f', '2-week outlook'], ['b', 'Production base']]; out.rows = CM_REG.map((_, i) => cmWx(i)).filter(w => w.ids.some(id => CMX[id].s === 'ag') && w.inS).sort((a, b) => b.risk - a.risk).slice(0, 8).map(w => ({ n: w.name, m: w.ids.map(cmTk).join(', '), c: CM_COND[w.cond][0], f: `${sgn(w.fta, 1)}°C ± ${nf(w.unc, 1)}`, b: w.note })); out.note = 'Simulated conditions; a 3-month outlook needs seasonal forecasts (not connected).'; out.interp = `Highest weather risk: ${out.rows[0]?.n || '—'}.`; return out; }
  if (/brent/.test(s) && /move|explain/.test(s)) { const E = cmExplain('CM.CO1', 5); out.crit = ['Brent, 1 week', 'measured drivers vs hypotheses']; out.cols = [['k', 'Type'], ['f', 'Factor'], ['t', 'Evidence']]; out.rows = E.out.map(o => ({ k: o.m ? 'Measured' : 'Hypothesis', f: o.f, t: o.txt })); out.interp = `Brent ${pc(E.ch, 1)} this week. Measured factors are estimated from simulated data; hypotheses need confirmation.`; return out; }
  if (/refining capacity|concentrat/.test(s)) { out.crit = ['Top-country share of refining/processing']; out.cols = [['n', 'Material'], ['r', 'Refining'], ['p', 'Share', v => v + '%']]; out.rows = CM_CONC.map(c => ({ n: c[0], r: c[2], p: c[3] })).sort((a, b) => b.p - a.p); out.note = 'Approximate public figures; verify.'; out.interp = `Most concentrated: ${out.rows.slice(0, 3).map(r => r.n).join(', ')}.`; return out; }
  if (/gold/.test(s) && /compan|margin/.test(s)) { const gold = cmP('CM.GC1'); out.crit = ['Gold-linked companies', 'margin = price − cost (illustrative AISC)', 'currency exposure noted']; out.cols = [['n', 'Company'], ['b', 'Beta to gold', v => nf(v, 2)], ['a', 'Illustrative AISC $/oz'], ['m', 'Margin at spot', v => '$' + nf(v, 0)], ['s', 'Margin change for +10% gold', v => pc(v, 0)], ['fx', 'Currency']]; out.rows = [['EQ.NEM', 1500, 'USD reporting; costs in AUD, CAD, GHS and others'], ['EQ.FCX', null, 'Gold is a by-product of copper']].map(([id, aisc, fx]) => { const b = gyOLS(gyDx('CM.GC1'), gyDx(id))?.b; const m = aisc ? gold - aisc : null; return { n: BY[id].tk, b, a: aisc ? nf(aisc, 0) : 'n/a', m: m ?? 0, s: aisc ? gold * .1 / m * 100 : 0, fx }; }); out.note = 'AISC is an illustrative assumption, not a company figure; local-currency costs mean a weaker local currency raises margins. Verify with filings.'; out.interp = 'Higher-cost producers have more operating leverage to the gold price.'; return out; }
  if (/freight/.test(s) && /route|disrupt/.test(s)) { CM.st = 'frt'; out.go = 'scen'; return out; }
  if (/scarcity|implied/.test(s) && /balance/.test(s)) { out.crit = ['Curve M1→M12 (market-implied scarcity)', 'Latest modelled balance (stock change)']; out.cols = [['n', 'Market'], ['c', 'Curve signal'], ['b', 'Balance signal'], ['x', 'Consistent?']]; out.rows = Object.keys(CM_BAL).map(id => { const sl = cmSlope(id); const bb = cmBal(id); const r = bb.rows.filter(x => x.st !== 'Forecast').at(-1); return { n: cmN(id), c: `${cmShape(sl)} ${sgn(sl, 1)}%`, b: `${r.q} ${sgn(r.chg, 2)} ${bb.unit}`, x: (sl < 0) === (r.chg < 0) ? 'Yes' : 'No — investigate' }; }); out.note = 'Curves and balances are modelled; inconsistency may reflect timing, coverage or expectations.'; out.interp = `${out.rows.filter(r => r.x === 'Yes').length} of ${out.rows.length} markets show consistent signals.`; return out; }
  out.crit = ['Performance ranking', '1 month']; out.cols = [['n', 'Commodity'], ['r', '1M', v => pc(v, 1)]]; out.rows = CM_IDS.map(id => ({ n: cmN(id), r: cmRet(id, 21) })).sort((a, b) => b.r - a.r).slice(0, 12); out.interp = 'Showing 1-month performance; try one of the example questions.'; return out; }
function cmAI(el) {
  const ins = cmInsights(); const shown = ins.filter(c => !CM.cat || c.cat === CM.cat); CM.cards = shown; const R = CM.xr;
  const secs = ['en', 'pm', 'bm', 'ag'].map(s => { const ids = CM_IDS.filter(id => CMX[id].s === s); const top = ids.slice().sort((a, b) => Math.abs(cmRet(b, 5)) - Math.abs(cmRet(a, 5)))[0]; const E = cmExplain(top, 5); return { s, top, E }; });
  const EX = ['Which commodities are trading near the bottom of their five-year historical ranges?', 'Find energy markets where inventories are falling and the front of the futures curve is tightening.', 'Compare copper, aluminum and lithium using inventory, new capacity and demand from electrification.', 'Which agricultural commodities face the largest weather-related supply risks over the next three months?', "Explain this week's move in Brent crude and separate measured drivers from hypotheses.", 'Which metals have the most concentrated refining capacity by country?', 'Show me companies whose margins may benefit from higher gold prices, accounting for production costs and currency exposure.', 'What happens to the oil and fertilizer markets if freight costs rise 25% and a major export route is disrupted?', "Compare the market's implied scarcity signal with the latest reported supply-demand balance.", 'Generate a research memo on critical-mineral supply-chain bottlenecks relevant to data centers and power infrastructure.'];
  const an = CM_IDS.filter(id => CMX[id].s !== 'ix').map(id => { const r = cmRet(id, 5), sd = gySd(gyDx(id, 250, 5)) * Math.sqrt(5); const z = sd ? r / sd : 0; const iv = CMX[id].inv ? cmInvStat(id) : null; const ps = cmPosStat(id); const sp = CMX[id].cmo ? gyPct(cmSprHist(id, 0, 1, 1260).filter(v => v != null), cmSpr(id, 0, 1)) : null; const wx = CM_REG.map((_, i) => cmWx(i)).some(w => w.ids.includes(id) && w.cond >= 3 && w.cond < 5); const sig = [Math.abs(z) > 2, iv && (iv.pct <= 10 || iv.pct >= 90), sp != null && (sp <= 5 || sp >= 95), ps && (ps.pct <= 5 || ps.pct >= 95), wx]; return { id, z, iv, sp, ps, wx, n: sig.filter(Boolean).length }; }).sort((a, b) => b.n - a.n || Math.abs(b.z) - Math.abs(a.z));
  el.innerHTML = `<section class="panel gy-strat"><header class="ph"><span class="pt">AI Global Commodities Strategist</span><span class="pm">${simB('SIM EOD')} · week to ${fd(END)}</span></header><div class="pb"><div class="gy-st2"><div><h6>What changed, by sector</h6><ol class="gy-obs">${secs.map(x => `<li><p>${CMS[x.s]}: ${esc(cmN(x.top))} ${pc(x.E.ch, 1)} this week.</p><div class="gy-alt"><span>Measured</span>${x.E.out.filter(o => o.m).slice(0, 3).map(o => `<em>${esc(o.f)} · ${esc(o.txt)}</em>`).join('')}${x.E.out.some(o => !o.m) ? `<span style="margin-top:4px">Hypotheses</span>${x.E.out.filter(o => !o.m).slice(0, 2).map(o => `<em class="alt">${esc(o.txt)}</em>`).join('')}` : ''}</div></li>`).join('')}</ol></div>
      <div><h6>AI commodity research writer</h6><div class="gx-wr">${[['daily', 'Daily commodities briefing'], ['sector', 'Sector outlook'], ['sd', 'Supply-demand note'], ['co', 'Company exposure report'], ['cm', 'Critical-minerals memo']].map(([k, l]) => `<button class="btn ${k === 'daily' ? 'pri' : ''}" data-cmx="write" data-v="${k}">${l}</button>`).join('')}</div><h6>Upcoming catalysts</h6>${cmEvents(END + DAY, END + 7 * DAY).filter(e => e.imp >= 2).slice(0, 5).map(e => `<div class="fi-r"><span>${fd(e.t, { day: '2-digit', month: 'short' })}</span><span>${esc(e.title)}</span></div>`).join('')}<p class="note">Superfinancials AI receives the data on this page (simulated) and is asked for evidence, alternatives, counterarguments and explicit data limitations.</p></div></div></div></section>
    <section class="panel"><header class="ph"><span class="pt">Natural-language commodity research</span></header><div class="pb"><form class="nx-ask" id="cmRq"><input class="inp" id="cmRqi" maxlength="240" value="${esc(CM.xq)}" placeholder="Which commodities are trading near the bottom of their five-year historical ranges?" aria-label="Ask a commodity research question"><button class="btn pri" type="submit">Run</button></form><div class="nx-ex" style="margin-top:10px">${EX.map(q => `<button class="chip" data-cmx="rq" data-v="${esc(q)}">${esc(q)}</button>`).join('')}</div>
      ${R ? `<div class="gy-crit" style="margin-top:12px"><span class="nx-lab">Calculation</span>${R.crit.map(c => `<span class="gy-chip" style="padding-right:10px">${esc(c)}</span>`).join('')}<span class="note">data: simulated, ${fd(END)}</span></div><p class="gy-interp">${esc(R.interp)}</p>${R.note ? `<p class="gy-warn1">${esc(R.note)}</p>` : ''}<div class="tw"><table class="t dense"><thead><tr>${R.cols.map(c => `<th class="${c[2] ? 'r' : ''}">${c[1]}</th>`).join('')}</tr></thead><tbody>${R.rows.map(r => `<tr>${R.cols.map(([k, , f]) => `<td class="${f ? 'r' : ''}" style="white-space:normal">${r[k] == null ? '—' : f ? f(r[k]) : esc(String(r[k]))}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="gy-btns"><button class="btn sm" data-cmx="rqask">Ask Superfinancials to interpret</button></div>` : ''}</div></section>
    <div class="fi-tb"><div class="row" style="gap:6px;flex-wrap:wrap"><button class="chip ${!CM.cat ? 'on' : ''}" data-cmx="cat" data-v="">All insights · ${ins.length}</button>${Object.entries(CM_CAT).map(([k, l]) => { const n = ins.filter(c => c.cat === k).length; return n ? `<button class="chip ${CM.cat === k ? 'on' : ''}" data-cmx="cat" data-v="${k}">${l} · ${n}</button>` : ''; }).join('')}</div></div>
    <div class="gy-cards">${shown.map(cmCard).join('') || '<p class="note">No insights in this category.</p>'}</div>
    <section class="panel"><header class="ph"><span class="pt">Supply-demand anomaly agent</span><span class="pm">prioritises corroborated signals</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Market</th><th class="r">Signals</th><th class="r">Weekly move (σ)</th><th class="r">Inventory pctl</th><th class="r">M1–M2 pctl</th><th class="r">Positioning pctl</th><th>Weather</th></tr></thead><tbody>${an.slice(0, 14).map(a => `<tr><td><a href="#" data-cmx="open" data-v="${a.id}">${esc(cmN(a.id))}</a></td><td class="r"><b class="${a.n >= 2 ? 'dn' : ''}">${a.n}</b></td><td class="r ${Math.abs(a.z) > 2 ? 'dn' : ''}">${sgn(a.z, 1)}</td><td class="r">${a.iv ? ordn(a.iv.pct) : '—'}</td><td class="r">${a.sp == null ? '—' : ordn(a.sp)}</td><td class="r">${a.ps ? ordn(a.ps.pct) : '—'}</td><td>${a.wx ? '<b class="dn">poor</b>' : '—'}</td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Two or more agreeing signals rank first; a single unusual data point ranks lower. Freshness: prices daily, inventories and positioning weekly (positioning 3-day lag), weather monthly. All modelled or simulated.</p></div></section>`;
  $('#cmRq', el).onsubmit = e => { e.preventDefault(); CM.xq = $('#cmRqi', el).value.trim(); if (CM.xq) cmRun(); };
}
function cmRun() { const R = cmResearch(CM.xq); if (R.ask) { CM.xr = null; CM.draw(); CM.ask(CM.xq + ' Use the commodity data on this page (simulated), trace minerals from extraction to processing to users, separate evidence from interpretation, include counterarguments and data limitations.'); return; } if (R.go) { toast('Opening the freight and route-disruption stress test'); CM.go(R.go); return; } CM.xr = R; CM.draw(); }
CM_X.rq = b => { CM.xq = b.dataset.v; cmRun(); }; CM_X.cat = b => { CM.cat = b.dataset.v; CM.draw(); };
CM_X.rqask = () => { const R = CM.xr; CM.ask(`Question: "${R.q}". Calculation: ${R.crit.join('; ')}. Result: ${R.rows.slice(0, 10).map(r => R.cols.map(([k, l, f]) => `${l} ${r[k] == null ? '—' : f ? f(r[k]) : r[k]}`).join(', ')).join(' | ')}. Interpret with caveats.`); };
CM_X.write = b => CM.ask({ daily: "Write today's commodities briefing: the largest moves across energy, metals, agriculture and other sectors, measured drivers vs hypotheses, inventories, curves, positioning, weather and physical signals, alternative interpretations and upcoming catalysts.", sector: `Write a sector outlook for ${CMS[CMX[CM.id].s]}: prices, curves, inventories, balances, risks and scenarios with counterarguments.`, sd: `Write a supply-demand note on ${cmN(CM.sid)}: inventories vs seasonal norms, balance estimates and revisions, curve signals, and what would change the view.`, co: `Write a company exposure report for ${cmN(CM.co)}: which listed companies are exposed, how (revenue, costs, margins), measured betas, and the limits of the evidence.`, cm: 'Write a research memo on critical-mineral supply-chain bottlenecks relevant to data centres and power infrastructure: concentration, lead times, substitution, exposed companies and private projects, and what distinguishes a structural bottleneck from a temporary price spike.' }[b.dataset.v]);

/* ---------- DATA & SOURCES ---------- */
function cmData(el) {
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Series inventory</span><span class="pm">${CM_IDS.length} price series</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Series</th><th>Grade</th><th>Unit · currency</th><th>Delivery / location</th><th>Contract / methodology</th><th>Source</th><th>Status</th><th>Frequency</th><th>History from</th><th>Licence</th></tr></thead><tbody>${CM_IDS.map(id => { const m = CMX[id], o = BY[id]; return `<tr><td><b>${esc(cmN(id))}</b></td><td class="sub" style="white-space:normal">${esc(m.g)}</td><td class="sub">${esc(o.unit)} · ${o.ccy}</td><td class="sub" style="white-space:normal">${esc(m.loc)}</td><td class="sub" style="white-space:normal">${m.cmo ? 'Continuous front month, unadjusted rolls. ' : ''}${esc(m.roll)}</td><td class="sub">${esc(o.exch)}</td><td>${cmTag(id)}</td><td>Daily EOD</td><td>${fd(series(id).d[0], { month: 'short', year: 'numeric' })}</td><td class="sub">Simulated</td></tr>`; }).join('')}</tbody></table></div></div></section>
    <section class="panel"><header class="ph"><span class="pt">Derived and model series</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Series</th><th>Status</th><th>Method</th><th>Production source</th></tr></thead><tbody>${[['Futures curves', 'Model-derived', 'Front price × exp(carry + inventory-driven convenience yield) with seasonal delivery adjustments', 'Exchange settlement prices by contract (CME, ICE, LME, SGX)'], ['Inventories', 'Model-derived (weekly)', 'Seasonal norm × deviation linked to past price moves', 'EIA, USDA, LME/COMEX/SHFE, ICE certified stocks, MPOB, AGSI+'], ['Positioning', 'Model-derived (weekly, 3-day lag)', 'Managed-money net % of OI linked to 13-week returns', 'CFTC Commitments of Traders; ICE COT'], ['Supply-demand balances', 'Illustrative (actual/estimate/forecast labelled)', 'Trend consumption with modelled balance and revisions', 'EIA STEO, IEA, OPEC MOMR, USDA WASDE, ICSG, ICCO'], ['Weather & crop conditions', 'Simulated', 'Monthly random conditions by region and season', 'National met agencies, NOAA, ECMWF-based providers, GEOGLAM'], ['Trade flows', 'Approximate public figures, rounded', 'Annual inter-regional matrices', 'Energy Institute Statistical Review, UN Comtrade; Kpler/S&P for cargo-level'], ['Freight, ports, facilities, cargoes', 'Illustrative / simulated', 'Generated series and anonymised records', 'Baltic Exchange, AIS providers, company disclosures'], ['Cost curves', 'Illustrative, anonymised', 'Random producers around the current price', 'Licensed cost models (with methodology labels)']].map(r => `<tr><td><b>${r[0]}</b></td><td><span class="gy-q ind">${r[1]}</span></td><td class="sub" style="white-space:normal">${r[2]}</td><td class="sub" style="white-space:normal">${r[3]}</td></tr>`).join('')}</tbody></table></div></div></section>
    <section class="panel"><header class="ph"><span class="pt">Data-quality rules applied</span></header><div class="pb"><ul class="mv-its"><li>Every price shows grade, unit, currency, delivery location, contract or methodology, source and timestamp.</li><li>Exchange futures, assessed physical prices, spot prices and indices are labelled separately and never combined into one series.</li><li>Actual, estimate, forecast and model-derived values are labelled; balances in flow units are not silently reconciled with inventories in stock units or different coverage.</li><li>Continuous futures roll without back-adjustment; roll rules are stated.</li><li>Approximate public figures (production shares, chokepoint flows, concentration) are marked approximate with the publisher to verify against.</li><li>Not connected: implied volatility and options, real CFTC/EIA/USDA releases, AIS vessel tracking, licensed price assessments, live news and weather feeds.</li></ul></div></section>`;
}

/* ---------- AI facts & page ---------- */
function cmFacts() { const r = v => v == null || !isFinite(v) ? null : Math.round(v * 100) / 100; return { commodities_tab: CM_TABS.find(t => t[0] === CM.tab)?.[1], note: 'Prices simulated; curves, inventories, positioning and balances modelled; weather simulated; flows, shares and capacities approximate.', markets: CM_IDS.filter(id => CMX[id].s !== 'ix').map(id => { const iv = CMX[id].inv ? cmInvStat(id) : null; const ps = cmPosStat(id); return { name: cmN(id), sector: CMS[CMX[id].s], unit: cmU(id), grade: CMX[id].g, location: CMX[id].loc, price: r(cmP(id)), ret_1w: r(cmRet(id, 5)), ret_1m: r(cmRet(id, 21)), ret_1y: r(cmRet(id, 252)), pctl_5y: r(cmPct5(id)), vol_3m: r(cmVol(id)), curve_m1_m12_pct: r(cmSlope(id)), inventory: iv ? { name: iv.name, level: r(iv.last), unit: iv.unit, seasonal_pctl: r(iv.pct), change_4w: r(iv.ch4) } : undefined, managed_money_pct_oi: ps ? r(ps.last) : undefined }; }), crack_321: r(cmCrack()), insights: cmInsights().slice(0, 10).map(c => ({ category: CM_CAT[c.cat], headline: c.head, evidence: c.ev, confidence: c.conf })), weather: CM_REG.map((_, i) => cmWx(i)).filter(w => w.cond >= 2 && w.cond < 5).map(w => ({ region: w.name, condition: CM_COND[w.cond][0], markets: w.ids.map(cmTk) })) }; }
{ const _ffc = factsFor; factsFor = function (r, p) { const f = _ffc(r, p); if (r === 'cmd') { try { Object.assign(f, cmFacts()); } catch (e) { f.note = 'Some commodity figures could not be computed.'; } } return f; }; }
Object.assign(CM_FN, { ov: cmOv, px: cmPx, sd: cmSD, wx: cmWxTab, sec: cmSec, phys: cmPhys, co: cmCo, af: cmAf, scen: cmScen, ai: cmAI, data: cmData });
const CM_OLD = PAGES.cmd;
PAGES.cmd = pg => {
  if (S.cmWatch) CM.watch = S.cmWatch.filter(id => BY[id]); if (state.p && CM_TABS.some(t => t[0] === state.p)) CM.tab = state.p; else if (state.p && BY[state.p]) { CM.id = state.p; CM.tab = 'px'; }
  pg.innerHTML = hdr('cmd', `Commodities intelligence: connect prices to the physical economy across ${CM_IDS.length} markets: observe prices, curves and inventories; explain supply, demand, weather and policy; trace assets, routes and companies; evaluate scenarios. ${simB('SIM EOD')} Simulated prices; model and illustrative data labelled.`, '') + `
    <nav class="gy-nav" role="tablist">${[1, 2, 3, 4].map(lv => `<div class="gy-lv"><span class="gy-lvh"><b>${lv}</b>${CM_LV[lv][0]}<i>${CM_LV[lv][1]}</i></span><div>${CM_TABS.filter(t => t[2] === lv).map(([k, l]) => `<button role="tab" class="${CM.tab === k ? 'on' : ''}" data-cmt="${k}">${l}</button>`).join('')}</div></div>`).join('')}</nav>
    <section class="panel fi-askp"><div class="pb"><form class="nx-ask" id="cmAsk"><span class="nx-lab">AI commodities analyst</span><input class="inp" id="cmAq" maxlength="300" placeholder="Why is copper rising this week?" aria-label="Ask about commodities"><button class="btn pri" type="submit">Ask Superfinancials</button><button class="btn" type="button" data-cmx="write" data-v="daily">Daily briefing</button></form></div></section><div id="cmBody" class="gy-body cm-body"></div>`;
  const body = $('#cmBody', pg);
  const draw = () => { $$('[data-cmt]', pg).forEach(b => b.classList.toggle('on', b.dataset.cmt === CM.tab)); destroyCharts(); for (const k in CM_MAPS) delete CM_MAPS[k]; try { if (CM.tab === 'old') { CM_OLD(body); $('.phd', body)?.remove(); } else (CM_FN[CM.tab] || cmOv)(body); cmMapsHydrate(body); } catch (e) { console.error(e); body.innerHTML = `<div class="callout">This view failed to load: ${esc(e.message)}</div>`; } };
  const ask = q => { const el = $$('.aip', pg)[0]; if (!el) return toast('AI insights are turned off for your account by your organization', true); el.scrollIntoView({ behavior: 'smooth', block: 'start' }); runInsight(el, q); };
  CM.draw = draw; CM.ask = ask; CM.go = k => { CM.tab = k; state.p = k; try { history.replaceState(null, '', '#cmd.' + k); } catch (x) { } draw(); $('.gy-nav', pg)?.scrollIntoView({ block: 'start', behavior: 'smooth' }); };
  draw();
  on(pg, 'click', '[data-cmt]', (e, b) => CM.go(b.dataset.cmt));
  on(pg, 'click', '[data-seg] button', (e, b) => { const k = b.closest('[data-seg]').dataset.seg; if (CM_SEG[k]) { CM_SEG[k](b.dataset.v); draw(); } });
  on(pg, 'click', '[data-cmx]', (e, b) => { if (CM_X[b.dataset.cmx]) { e.preventDefault(); e.stopPropagation(); CM_X[b.dataset.cmx](b, e); } });
  on(pg, 'change', '[data-cmc]', (e, b) => { if (CM_X[b.dataset.cmc]) CM_X[b.dataset.cmc](b, e); });
  on(pg, 'click', '[data-gogo]', (e, b) => { e.preventDefault(); const [r, p] = b.dataset.gogo.split('|'); GX.tab = p; go(r, p); });
  $('#cmAsk', pg).onsubmit = e => { e.preventDefault(); const q = $('#cmAq', pg).value.trim(); if (q) ask(q); };
  pg.addEventListener('keydown', e => { if (e.key === 'Escape' && $('#gyDrawer') && !$('#gyDrawer').hidden) $('#gyClose').click(); });
};

