EC_X.gcc = b => { EC.cc = b.value; EC.draw(); }; EC_X.ovl = b => { const k = b.dataset.v, i = EC.ovl.indexOf(k); if (i >= 0) EC.ovl.splice(i, 1); else EC.ovl.push(k); EC.draw(); }; EC_X.lead = b => { EC.lead = b.dataset.v; EC.draw(); };

