function ecRF(cc) { const g = mcGen(cc), M = mcM(), R = mcRegime(cc).rows; const tgt = MCC[cc][5]; const X = [], y = []; for (let i = 18; i < M.length - 6; i++) { const p0 = mcAt(cc, 'POL', M[i]), p6 = mcAt(cc, 'POL', M[i + 6]), c = mcAt(cc, 'CPI', M[i]), gz = R[i]?.gz; if ([p0, p6, c, gz].some(v => v == null)) continue; X.push([1, c - tgt, gz, p0 - (tgt + EC_RSTAR(cc))]); y.push(p6 - p0); } if (X.length < 24) return null; const o = gxMOLS(X, y); if (!o) return null; const sd = j => gySd(X.map(r => r[j])); const now = [1, (mcLast(cc, 'CPI')?.v ?? tgt) - tgt, mcRegime(cc).cur?.gz ?? 0, (mcLast(cc, 'POL')?.v ?? 0) - (tgt + EC_RSTAR(cc))]; const pred = now.reduce((s, v, j) => s + v * o.coef[j], 0); return { o, n: X.length, imp: [['Inflation gap', o.coef[1], o.coef[1] * sd(1)], ['Growth composite', o.coef[2], o.coef[2] * sd(2)], ['Rate level vs neutral', o.coef[3], o.coef[3] * sd(3)]].sort((a, b) => Math.abs(b[2]) - Math.abs(a[2])), pred }; }
function ecCB(el) {
  const set = EC.cbSet === 'dm' ? EC_CBDM : EC.cbSet === 'em' ? EC_CBEM : [...EC_CBDM, ...EC_CBEM]; const rows = set.map(cc => ({ cc, p: ecPolInfo(cc) })).filter(x => x.p); const cc = MCC[EC.cbc] ? EC.cbc : 'US'; const P = ecPolInfo(cc); const RF = ecRF(cc); const M = mcM(); const M5 = M.slice(-60);
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Central bank policy rates</span><span class="pm">${seg('eccbs', [['dm', 'Developed'], ['em', 'Emerging & frontier'], ['all', 'All']], EC.cbSet)}</span></header><div class="pb"><div id="ecPr"></div>${gxLeg(rows.map((r, i) => [PAL[i % 8], `${MCC[r.cc][4]} (${r.cc})`, i >= 8]))}<p class="note">Month-end policy rates (U.S.: midpoint of the Fed funds target range; Nigeria: CBN MPR series; others: approximate historical paths drawn from public decisions, simplified; verify).</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Policy monitor</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Central bank</th><th class="r">Policy rate</th><th>Last change</th><th class="r">3m</th><th class="r">12m</th><th class="r">CPI vs target</th><th class="r">Real rate</th><th>Stance (model)</th><th class="r">Implied 12m</th><th>Next meeting</th></tr></thead><tbody>${rows.map(({ cc, p }) => `<tr class="${cc === EC.cbc ? 'gy-cur' : ''}"><td><a href="#" data-ecx="cbc" data-v="${cc}"><b>${esc(MCC[cc][4])}</b></a> <span class="sub">${esc(mcN(cc))}</span></td><td class="r"><b>${nf(p.v, 2)}%</b></td><td class="sub">${p.lc ? `${p.lc.sz > 0 ? '+' : ''}${nf(p.lc.sz * 100, 0)} bp · ${fd(p.lc.t, { month: 'short', year: 'numeric' })}` : 'none in 10 years'}</td><td class="r ${cls(-p.d3)}">${p.d3 ? bpf(p.d3 * 100, 0) : '—'}</td><td class="r ${cls(-p.d12)}">${p.d12 ? bpf(p.d12 * 100, 0) : '—'}</td><td class="r">${p.cpi == null ? '—' : `${nf(p.cpi, 1)}% <span class="sub">/ ${p.tgt}%</span>`}</td><td class="r ${p.real != null && p.real < 0 ? 'dn' : ''}">${p.real == null ? '—' : sgn(p.real, 1) + '%'}</td><td>${p.st == null ? '—' : p.st > 1 ? '<span class="ec-st r">Restrictive</span>' : p.st < -1 ? '<span class="ec-st a">Accommodative</span>' : '<span class="ec-st n">Near neutral</span>'}</td><td class="r">${p.imp?.m12 != null ? bpf((p.imp.m12 - p.v) * 100, 0) : '<span class="sub">no curve</span>'}</td><td class="sub">${p.next ? fd(p.next, { day: '2-digit', month: 'short' }) : 'not in calendar'}</td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Real rate = policy rate − headline CPI y/y (ex-post). Stance compares the real rate with an assumed neutral real rate (${EC_RSTAR('US')}% developed, ${EC_RSTAR('BR')}% emerging, ${EC_RSTAR('NG')}% frontier); a modelling assumption, not an official estimate. Market-implied changes come from simulated bill and short-bond curves and are not forecasts.</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Policy expectations vs economic reality</span><span class="pm">${ecSel(cc, 'cbc2', MC_IDS)}</span></header><div class="pb"><div id="ecPe"></div>${gxLeg([['#7e57c2', 'Policy rate'], ['#7e57c2', 'Market-implied path', 1], ['#e8803a', 'Headline CPI'], ['#c0392b', 'Core inflation'], ['#2e9e4f', 'Wage growth'], ['#2e6bd9', 'Unemployment (right)']])}<p class="note">Compares where markets expect policy to go with the latest inflation, wages and labour data. If markets price cuts while inflation is persistent, investigate whether expectations are running ahead of the data.</p></div></section>
    <div class="grid"><section class="panel c7"><header class="ph"><span class="pt">Reaction function · ${esc(MCC[cc][4])}</span><span class="pm">historical, model-estimated</span></header><div class="pb">${RF ? `<div class="tw"><table class="t dense"><thead><tr><th>Driver (at decision time)</th><th class="r">Coefficient</th><th class="r">Effect of 1 sd, pp over 6m</th></tr></thead><tbody>${RF.imp.map(([n, b, e]) => `<tr><td>${n}</td><td class="r">${nf(b, 2)}</td><td class="r"><b>${sgn(e, 2)}</b></td></tr>`).join('')}</tbody></table></div><p class="note">Regression of the 6-month change in the policy rate on the inflation gap, the growth composite and the rate level vs neutral (${RF.n} monthly observations, R² ${nf(RF.o.r2, 2)}). Ordered by historical importance.</p>` : '<p class="note">Not enough policy history to estimate.</p>'}
      <div class="ec-3"><div><span class="nx-lab">Market-implied</span><b>${P?.imp?.m12 != null ? `${bpf((P.imp.m12 - P.v) * 100, 0)} over 12m` : 'not available'}</b><small>from simulated curves</small></div><div><span class="nx-lab">Model-estimated</span><b>${RF ? `${bpf(RF.pred * 100, 0)} over 6m` : '—'}</b><small>historical reaction function applied to today's data</small></div><div><span class="nx-lab">Official guidance</span><b>not connected</b><small>statements, minutes and projections</small></div></div><p class="note">The three are kept separate: none is a certain forecast of the next decision.</p><button class="btn sm" data-ecx="cbask">Ask Superfinancials: what changed in ${esc(MCC[cc][4])} communication?</button></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">Policy divergence vs the Fed</span></header><div class="pb"><div id="ecDv"></div><div class="tw"><table class="t dense"><thead><tr><th>Central bank</th><th class="r">Gap vs Fed</th><th class="r">12m change</th></tr></thead><tbody>${rows.filter(r => r.cc !== 'US').map(({ cc: c, p }) => { const us = ecPolInfo('US'); return `<tr><td>${MCC[c][4]}</td><td class="r">${sgn(p.v - us.v, 2)} pp</td><td class="r ${cls(p.d12 - us.d12)}">${bpf((p.d12 - us.d12) * 100, 0)}</td></tr>`; }).join('')}</tbody></table></div><p class="note">Widening gaps change carry and currency dynamics. <a href="#" data-gogo="fx|carry">FX carry →</a></p></div></section></div>`;
  gxChart($('#ecPr', el), { h: 320, x: M, series: rows.map((r, i) => ({ v: M.map(t => mcAt(r.cc, 'POL', t)), c: PAL[i % 8], label: MCC[r.cc][4], dash: i >= 8 ? '4 3' : null })), fl: v => nf(v, 0) + '%', zero: true });
  if (P) { const fut = [3, 6, 12].map(m => M.at(-1) + m * 30.4 * DAY); const X = [...M5, ...fut]; const n5 = M5.length; const s = k => [...M5.map(t => mcAt(cc, k, t)), null, null, null]; const ip = P.imp ? [...M5.map((_, i) => i === n5 - 1 ? P.v : null), P.imp.m3, P.imp.m6, P.imp.m12] : []; gxChart($('#ecPe', el), { h: 300, x: X, split: n5 - 1, splitLab: 'today', series: [{ v: s('POL'), c: '#7e57c2', label: 'Policy rate', w: 2.4 }, ...(P.imp ? [{ v: ip, c: '#7e57c2', label: 'Market-implied', dash: '5 4', pts: [X.length - 1], lab: v => nf(v, 2) + '%' }] : []), { v: s('CPI'), c: '#e8803a', label: 'CPI' }, ...(mcHas(cc, 'CORE') ? [{ v: s('CORE'), c: '#c0392b', label: 'Core' }] : []), ...(mcHas(cc, 'WAGE') ? [{ v: s('WAGE'), c: '#2e9e4f', label: 'Wages' }] : []), ...(mcHas(cc, 'UR') ? [{ v: s('UR'), c: '#2e6bd9', label: 'Unemployment', ax: 'r' }] : [])], fl: v => nf(v, 1) + '%', fr: v => nf(v, 1) + '%' }); }
  const others = rows.filter(r => r.cc !== 'US').slice(0, 8); gxChart($('#ecDv', el), { h: 200, x: M5, series: others.map((r, i) => ({ v: M5.map(t => mcAt(r.cc, 'POL', t) - mcAt('US', 'POL', t)), c: PAL[(i + 1) % 8], label: MCC[r.cc][4] })), zero: true, fl: v => sgn(v, 1) });
}
EC_SEG.eccbs = v => EC.cbSet = v; EC_X.cbc = b => { EC.cbc = b.dataset.v; EC.draw(); }; EC_X.cbc2 = b => { EC.cbc = b.value; EC.draw(); };
EC_X.cbask = () => { const cc = EC.cbc; const P = ecPolInfo(cc); EC.ask(`Analyse ${MCC[cc][3]} policy: rate ${nf(P.v, 2)}%, last change ${P.lc ? bpf(P.lc.sz * 100, 0) + ' in ' + fd(P.lc.t, { month: 'short', year: 'numeric' }) : 'none'}, CPI ${nf(P.cpi, 1)}% vs target ${P.tgt}%, real rate ${sgn(P.real, 1)}%. Separate market-implied expectations, model estimates and official guidance (statements are not connected here). Explain where expectations diverge from recent data and which releases could change the outlook.`); };

/* ---------- COUNTRY COMPARISON ---------- */
const EC_GEO = { US: ['United States of America'], EU: ['Germany', 'France', 'Italy', 'Spain', 'Netherlands', 'Belgium', 'Austria', 'Portugal', 'Ireland', 'Finland', 'Greece', 'Slovakia', 'Slovenia', 'Lithuania', 'Latvia', 'Estonia', 'Luxembourg', 'Croatia', 'Cyprus'], UK: ['United Kingdom'], JP: ['Japan'], CA: ['Canada'], AU: ['Australia'], CN: ['China'], IN: ['India'], ID: ['Indonesia'], BR: ['Brazil'], MX: ['Mexico'], TR: ['Turkey'], ZA: ['South Africa'], NG: ['Nigeria'], EG: ['Egypt'], KE: ['Kenya'], GH: ['Ghana'], CI: ["Côte d'Ivoire"], ZM: ['Zambia'], MA: ['Morocco'] };
const EC_HMC = [['GDP', 'Growth'], ['MPMI', 'Mfg PMI'], ['CPI', 'Inflation'], ['CORE', 'Core'], ['UR', 'Unempl.'], ['POL', 'Policy'], ['REAL', 'Real rate'], ['BAL', 'Budget bal.'], ['DEBT', 'Debt'], ['CA', 'Curr. acct'], ['RES', 'Reserves'], ['Y10', '10Y yield'], ['FX', 'FX 1Y'], ['EQ', 'Equities 1Y'], ['RG', 'Regime']];
function ecCell(cc, k, mode) { if (k === 'RG') { const r = mcRegime(cc).cur; return r ? { v: r.k, txt: MC_RG[r.k][0].split(' ')[0], c: MC_RG[r.k][1] } : null; } const A = mcAssets(cc); if (k === 'Y10') { if (!A.y10) return null; const v = valAt(A.y10, END), v3 = valAt(A.y10, gyD(63)); return { v: mode === 'chg' || mode === 'yoy' ? (v - (mode === 'yoy' ? valAt(A.y10, gyD(252)) : v3)) * 100 : v, txt: mode === 'chg' || mode === 'yoy' ? bpf((v - (mode === 'yoy' ? valAt(A.y10, gyD(252)) : v3)) * 100, 0) : nf(v, 2) + '%', dir: -1 }; } if (k === 'FX') { if (!A.fx || cc === 'US') return null; const v = mcFxRet(A.fx, gyD(252), END); return { v, txt: pc(v, 1), dir: 1 }; } if (k === 'EQ') { if (!A.eq) return null; const v = (valAt(A.eq, END) / valAt(A.eq, gyD(252)) - 1) * 100; return { v, txt: pc(v, 1), dir: 1 }; }
  const L = mcLast(cc, k); if (!L) return null; const dir = MI[k][5]; const raw = { lvl: L.v, chg: L.chg, yoy: L.yoyCh, pct: L.pct, z: L.hz, surp: L.z }[mode]; if (raw == null) return { v: null, txt: '—', dir }; return { v: raw, txt: mode === 'pct' ? ordn(raw) : mode === 'z' || mode === 'surp' ? sgn(raw, 1) + (mode === 'surp' ? 'σ' : '') : mcFmt(k, raw, mode !== 'lvl'), dir, lvl: L.v, ctx: `${mcFmt(k, L.v)} ${ecU(k)} · ${ordn(L.pct)} pctl of own 10-year history · z ${sgn(L.hz, 1)}` }; }
function ecCC(el) {
  const grp = EC.hg; const ccs = MC_IDS.filter(cc => grp === 'all' || MCC[cc][2] === grp || MCC[cc][1] === grp); const mode = EC.hm;
  const cols = EC_HMC.map(([k, l]) => { const cells = ccs.map(cc => ecCell(cc, k, mode)); const vals = cells.map(c => c?.v).filter(v => typeof v === 'number' && isFinite(v)); const sorted = vals.slice().sort((a, b) => a - b); return { k, l, cells, rank: v => sorted.length > 1 ? sorted.indexOf(v) / (sorted.length - 1) * 2 - 1 : 0 }; });
  const color = (col, c) => { if (!c || c.v == null) return ''; if (col.k === 'RG') return `background:color-mix(in srgb,${c.c} 28%,var(--panel))`; let sc = mode === 'pct' ? (c.v - 50) / 50 : mode === 'z' || mode === 'surp' ? Math.max(-1, Math.min(1, c.v / 2)) : col.rank(c.v); const d = c.dir ?? 0; if (!d) return `background:color-mix(in srgb,#2e6bd9 ${Math.round(Math.abs(sc) * 40)}%,var(--panel))`; sc *= d; return `background:color-mix(in srgb,${sc >= 0 ? 'var(--up)' : 'var(--dn)'} ${Math.round(Math.abs(sc) * 45)}%,var(--panel))`; };
  const mk = EC.mapK; const mm = EC.mapM; const mv = MC_IDS.map(cc => ({ cc, c: ecCell(cc, mk, mm) })).filter(x => x.c && typeof x.c.v === 'number'); const ms = mv.map(x => x.c.v).sort((a, b) => a - b); const mr = v => ms.length > 1 ? ms.indexOf(v) / (ms.length - 1) : .5; const mdir = MI[mk]?.[5] || 0;
  const fill = name => { const cc = Object.keys(EC_GEO).find(c => EC_GEO[c].includes(name)); const x = mv.find(y => y.cc === cc); if (!x) return null; const t = mr(x.c.v); const sc = mdir ? (t * 2 - 1) * mdir : null; return { c: sc == null ? `color-mix(in srgb,#b5532a ${Math.round(15 + t * 85)}%,#f3e2d8)` : `color-mix(in srgb,${sc >= 0 ? '#2e9e4f' : '#c0392b'} ${Math.round(20 + Math.abs(sc) * 70)}%,var(--panel))`, op: .9, tip: `${mcN(cc)}: ${MI[mk][0]} ${x.c.txt}${x.c.ctx ? ' · ' + x.c.ctx : ''}`, act: 'gocc', v: cc }; };
  const Q = MC_IDS.map(cc => { const R = mcRegime(cc).rows; const c = R.at(-1), p3 = R.at(-4), p6 = R.at(-7); return c && { cc, c, p3, p6 }; }).filter(Boolean).filter(q => grp === 'all' || MCC[q.cc][2] === grp || MCC[q.cc][1] === grp);
  const div = MC_IDS.map(cc => { const R = mcRegime(cc).rows; const c = R.at(-1), p6 = R.at(-7); if (!c || !p6) return null; const peers = MC_IDS.filter(x => x !== cc && (MCC[x][1] === MCC[cc][1] || MCC[x][2] === MCC[cc][2])); const pg = ecMed(peers.map(x => { const r = mcRegime(x).rows; return r.at(-1) && r.at(-7) ? r.at(-1).gz - r.at(-7).gz : null; })), pi = ecMed(peers.map(x => { const a = mcLast(x, 'CPI'); const b = mcAt(x, 'CPI', mcM().at(-7)); return a && b != null ? a.v - b : null; })); const dg = (c.gz - p6.gz) - (pg ?? 0); const ci = (c.cpi ?? 0) - (mcAt(cc, 'CPI', mcM().at(-7)) ?? 0); const di = ci - (pi ?? 0); const drivers = ['MPMI', 'IP', 'RET', 'GDP', 'EMP', 'CPI', 'CORE'].filter(k => mcHas(cc, k)).map(k => { const L = mcLast(cc, k); const b = mcAt(cc, k, mcM().at(-7)); return { k, d: L && b != null ? (L.v - b) / (gySd(mcGen(cc)[k].v) || 1) : 0 }; }).sort((a, b) => Math.abs(b.d) - Math.abs(a.d)).slice(0, 3); const pers = mcRegime(cc).rows.slice(-13).filter((r, i, a) => r && a[0] && Math.sign(r.gz - (mcRegime(cc).rows.at(-25)?.gz ?? r.gz)) === Math.sign(dg)).length; return { cc, dg, di, drivers, peers, kind: pers > 9 ? 'Persistent (possibly structural)' : 'Recent (likely cyclical)' }; }).filter(x => x && (Math.abs(x.dg) > .8 || Math.abs(x.di) > 1.5)).sort((a, b) => (Math.abs(b.dg) + Math.abs(b.di) / 2) - (Math.abs(a.dg) + Math.abs(a.di) / 2));
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Global economic indicators map</span><span class="pm">click a country</span></header><div class="pb"><div class="row" style="gap:8px;flex-wrap:wrap;margin-bottom:8px"><select class="inp sm" data-ecc="mapk">${['GDP', 'MPMI', 'CPI', 'CORE', 'UR', 'POL', 'REAL', 'BAL', 'DEBT', 'INTR', 'CA', 'RES', 'EXTD'].map(k => `<option value="${k}" ${k === mk ? 'selected' : ''}>${MI[k][0]}</option>`).join('')}</select>${seg('ecmm', [['lvl', 'Latest level'], ['yoy', 'Change vs year ago'], ['pct', 'Own-history percentile'], ['z', 'z vs own history']], mm)}</div>
      ${cmMap({ aria: 'Macro indicator choropleth', ax: 'ecx', regions: ['world', 'americas', 'europe', 'africa', 'asia'], badge: `${MI[mk][0]} · simulated`, fill, pts: [], legend: `<span><i style="background:${mdir ? '#c0392b' : '#f3e2d8'}"></i>${mdir ? 'Worse' : 'Low'}</span><span><i style="background:${mdir ? '#2e9e4f' : '#b5532a'}"></i>${mdir ? 'Better' : 'High'}</span><span class="note">Colour by rank across the ${mv.length} economies covered; grey = not covered. Hover for the raw value and its own-history context.</span>` })}</div></section>
    <section class="panel"><header class="ph"><span class="pt">Global macro heatmap</span><span class="pm">${ccs.length} economies</span></header><div class="pb"><div class="row" style="gap:8px;flex-wrap:wrap">${seg('echm', [['lvl', 'Latest level'], ['chg', 'Change vs prior'], ['yoy', 'Change vs year ago'], ['pct', 'Historical percentile'], ['z', 'z vs own history'], ['surp', 'Actual vs consensus']], mode)}${seg('echg', [['all', 'All'], ['Developed', 'Developed'], ['Emerging', 'Emerging'], ['Frontier', 'Frontier'], ['Africa', 'Africa']], grp)}</div></div><div class="pb flush"><div class="tw"><table class="t dense ec-hm"><thead><tr><th>Economy</th>${cols.map(c => `<th class="r">${c.l}</th>`).join('')}</tr></thead><tbody>${ccs.map((cc, i) => `<tr><td><a href="#" data-ecx="gocc" data-v="${cc}"><b>${esc(mcN(cc))}</b></a><div class="sub">${MCC[cc][2]}</div></td>${cols.map(col => { const c = col.cells[i]; return `<td class="r" style="${color(col, c)}" title="${esc(c?.ctx || '')}">${c ? c.txt : '<span class="sub">n/a</span>'}</td>`; }).join('')}</tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Green = better, red = worse, relative to the other economies shown (or to the country's own history in percentile and z modes); blue = no good/bad direction (rates). Normalisation matters: 5% inflation can be an improvement for one country and a deterioration for another, so hover for each value's own-history context. Market columns (yield, FX, equities) always show market data.</p></div></section>
    <div class="grid"><section class="panel c7"><header class="ph"><span class="pt">Growth–inflation quadrant</span><span class="pm">trails: 6 and 3 months ago</span></header><div class="pb">${ecQuad(Q)}<p class="note">x: growth composite (z vs own history); y: inflation gap scaled by target (0 = at target). Points beyond ±4 are clipped (arrowheads). Descriptive quadrants, distinct from the regime engine which also uses momentum and stress.</p></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">Country divergence detector</span></header><div class="pb">${div.slice(0, 7).map(d => `<div class="ec-dv"><b><a href="#" data-ecx="gocc" data-v="${d.cc}">${esc(mcN(d.cc))}</a></b><span>${Math.abs(d.dg) > .8 ? `growth ${d.dg > 0 ? 'strengthening' : 'weakening'} vs peers (${sgn(d.dg, 1)} z, 6m)` : ''}${Math.abs(d.dg) > .8 && Math.abs(d.di) > 1.5 ? '; ' : ''}${Math.abs(d.di) > 1.5 ? `inflation ${d.di > 0 ? 'rising faster' : 'falling faster'} than peers (${sgn(d.di, 1)} pp)` : ''}</span><small>Drivers: ${d.drivers.map(x => `${MI[x.k][0]} ${sgn(x.d, 1)}σ`).join(', ')} · ${d.kind}</small></div>`).join('') || '<p class="note">No large divergences.</p>'}<p class="note">Peers: same region or same development tier. "Persistent" if the divergence has held for most of the last year; that is a heuristic, not proof of structural change.</p></div></section></div>`;
}
function ecQuad(Q) { const W = 640, H = 380, L = 40, R = 14, T = 14, B = 30; const cl = v => Math.max(-4, Math.min(4, v)); const xs = Q.flatMap(q => [q.c.gz, q.p6?.gz]).filter(v => v != null); const x0 = Math.min(-2, ...xs) - .2, x1 = Math.max(2, ...xs) + .2; const y0 = -2.5, y1 = 4.3; const tx = v => L + (v - x0) / (x1 - x0) * (W - L - R), ty = v => T + (y1 - cl(v)) / (y1 - y0) * (H - T - B); let s = `<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="Growth inflation quadrant"><defs><marker id="ecAr" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10z" style="fill:var(--fg3)"/></marker></defs>`;
  [[x0, 0, 0, y1, 'Stagflation risk', '#c0392b'], [0, x1, 0, y1, 'Overheating', '#e8803a'], [x0, 0, y0, 0, 'Slowdown / disinflation', '#7e57c2'], [0, x1, y0, 0, 'Expansion, low inflation', '#2e9e4f']].forEach(([a, b, c, d, l, col]) => { s += `<rect x="${tx(a)}" y="${ty(d)}" width="${tx(b) - tx(a)}" height="${ty(c) - ty(d)}" style="fill:${col};opacity:.07"/><text x="${a < 0 ? tx(a) + 6 : tx(b) - 6}" y="${d > 0 ? ty(d) + 14 : ty(c) - 6}" text-anchor="${a < 0 ? 'start' : 'end'}" class="gy-zl" style="fill:${col}">${l}</text>`; });
  s += `<line x1="${tx(0)}" x2="${tx(0)}" y1="${T}" y2="${H - B}" style="stroke:var(--fg3)"/><line x1="${L}" x2="${W - R}" y1="${ty(0)}" y2="${ty(0)}" style="stroke:var(--fg3)"/><text x="${(L + W) / 2}" y="${H - 6}" text-anchor="middle" class="gy-axl">Growth composite (z) →</text><text transform="translate(12 ${(T + H - B) / 2}) rotate(-90)" text-anchor="middle" class="gy-axl">Inflation vs target →</text>`;
  Q.forEach(q => { const col = MC_RG[q.c.k][1]; const pts = [q.p6, q.p3, q.c].filter(Boolean); s += `<path d="M${pts.map(p => `${tx(p.gz).toFixed(1)} ${ty(p.infl).toFixed(1)}`).join('L')}" style="fill:none;stroke:${col};stroke-width:1.4;opacity:.55" marker-end="url(#ecAr)"/>`; const off = Math.abs(q.c.infl) > 4; s += `<g class="ec-qp" data-ecx="gocc" data-v="${q.cc}"><circle cx="${tx(q.c.gz).toFixed(1)}" cy="${ty(q.c.infl).toFixed(1)}" r="6" style="fill:${col};stroke:var(--panel);stroke-width:1.5"><title>${esc(mcN(q.cc))}: growth ${sgn(q.c.gz, 2)} z, CPI ${nf(q.c.cpi, 1)}% vs target ${MCC[q.cc][5]}%${off ? ' (off scale)' : ''}</title></circle><text x="${tx(q.c.gz) + 8}" y="${ty(q.c.infl) + 4}" class="gy-pl">${q.cc}${off ? ' ↑' : ''}</text></g>`; }); return s + '</svg>'; }
Object.assign(EC_SEG, { echm: v => EC.hm = v, echg: v => EC.hg = v, ecmm: v => EC.mapM = v }); EC_X.mapk = b => { EC.mapK = b.value; EC.draw(); };

/* ---------- FISCAL & SOVEREIGN RISK ---------- */
const EC_REV = { Developed: 38, Emerging: 25, Frontier: 15 }; const EC_REVC = { US: 30, EU: 46, UK: 39, JP: 37, CA: 40, AU: 36, CN: 27, IN: 20, ID: 14, BR: 40, MX: 23, TR: 30, ZA: 27, NG: 10, EG: 20, KE: 17, GH: 16, CI: 16, ZM: 21, MA: 25 }; const ecRevR = cc => EC_REVC[cc] ?? EC_REV[MCC[cc][2]];
const ecFxShare = cc => { const k = cc === 'EU' ? 'DE' : cc; return SOV[k]?.fxShare ?? SOV2[k]?.[3] ?? { CI: 55, ZM: 70, MA: 25, EG: 35 }[cc] ?? null; };
function ecFis(el) {
  const V = ecVuln(); const ax = { fisc: ['Fiscal vulnerability index', v => v.fisc], ext: ['External financing pressure index', v => v.ext], debt: ['Debt, % GDP', v => v.debt], intr: ['Interest / revenue, %', v => v.intr], res: ['Reserves, months of imports', v => v.res], real: ['Real 10Y borrowing cost, %', v => { const A = mcAssets(v.cc); const c = mcLast(v.cc, 'CPI')?.v; return A.y10 && c != null ? valAt(A.y10, END) - c : null; }], fx: ['Currency 1Y, %', v => v.fx1y], ca: ['Current account, % GDP', v => v.ca] };
  const ew = MC_IDS.map(cc => { const A = mcAssets(cc); const s = []; const y = A.y10 ? (valAt(A.y10, END) - valAt(A.y10, gyD(126))) * 100 : null; if (y != null && y > 75) s.push(['Borrowing costs up', `10Y +${nf(y, 0)} bp in 6 months`]); const b = mcRel(cc, 'BAL')?.past; if (b && b.length > 1 && b.at(-1).act < b.at(-2).act - .5) s.push(['Fiscal balance weakening', `${nf(b.at(-2).act, 1)} → ${nf(b.at(-1).act, 1)}% GDP`]); const ir = mcLast(cc, 'INTR')?.v; if (ir != null && ir > 30) s.push(['High interest burden', `${nf(ir, 0)}% of revenue`]); const r = mcRel(cc, 'RES')?.past; if (r && r.length > 6 && r.at(-1).act < r.at(-7).act - .3) s.push(['Reserves declining', `${nf(r.at(-7).act, 1)} → ${nf(r.at(-1).act, 1)} months`]); const fx = A.fx && cc !== 'US' ? mcFxRet(A.fx, gyD(63), END) : null; if (fx != null && fx < -5) s.push(['Currency pressure', `${pc(fx, 1)} in 3 months`]); const fs = ecFxShare(cc); if (fs != null && fs > 40) s.push(['High FX share of debt', `≈${fs}% (approx.)`]); const mit = []; const ca = mcLast(cc, 'CA')?.v; if (ca != null && ca > 1) mit.push(`current-account surplus ${nf(ca, 1)}% GDP`); const rs = mcLast(cc, 'RES')?.v; if (rs != null && rs > 6) mit.push(`reserves ${nf(rs, 1)} months of imports`); if (fs != null && fs < 20) mit.push('mostly local-currency debt'); return { cc, s, mit }; }).filter(x => x.s.length).sort((a, b) => b.s.length - a.s.length);
  const cc = MCC[EC.dsc] ? EC.dsc : 'NG'; const d0 = mcLast(cc, 'DEBT')?.v ?? 60; const A0 = mcAssets(cc); const rev = ecRevR(cc); const ir = mcLast(cc, 'INTR')?.v ?? 10; const intG = ir * rev / 100; const D0 = { i: +(intG / d0 * 100).toFixed(1), g: +(mcLast(cc, 'GDP')?.v ?? 2).toFixed(1), pi: +(Math.min(40, mcLast(cc, 'CPI')?.v ?? 2)).toFixed(1), pb: +((mcLast(cc, 'BAL')?.v ?? -3) + intG).toFixed(1), fxs: ecFxShare(cc) ?? 20, dep: Math.max(0, Math.round(-(A0.fx && cc !== 'US' ? (mcFxRet(A0.fx, gyD(252), END) ?? 0) : 0))) }; const P = EC.ds && EC.ds.cc === cc ? EC.ds : (EC.ds = { cc, ...D0 }); const path = p => { const o = [d0]; let d = d0; for (let y = 1; y <= 6; y++) { d = d * (1 + p.i / 100) / ((1 + p.g / 100) * (1 + p.pi / 100)) - p.pb + d * p.fxs / 100 * p.dep / 100; o.push(d); } return o; }; const pt = path(P), pbase = path(D0); const pbStar = d0 * ((1 + P.i / 100) / ((1 + P.g / 100) * (1 + P.pi / 100)) - 1 + P.fxs / 100 * P.dep / 100);
  el.innerHTML = `<section class="panel"><header class="ph"><span class="pt">Fiscal sustainability and external vulnerability</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Economy</th><th class="r">Debt % GDP</th><th class="r">Budget balance</th><th class="r">Primary balance (est.)</th><th class="r">Interest / revenue</th><th class="r">FX share of debt</th><th class="r">Reserves (months)</th><th class="r">External debt</th><th class="r">Current account</th><th class="r">Real 10Y cost</th><th class="r">10Y, 3m</th><th class="r">FX, 3m</th></tr></thead><tbody>${V.map(v => { const A = mcAssets(v.cc); const c = mcLast(v.cc, 'CPI')?.v; const y = A.y10 ? valAt(A.y10, END) : null; const dy = A.y10 ? (y - valAt(A.y10, gyD(63))) * 100 : null; const fx = A.fx && v.cc !== 'US' ? mcFxRet(A.fx, gyD(63), END) : null; const pb = v.bal != null && v.intr != null ? v.bal + v.intr * ecRevR(v.cc) / 100 : null; return `<tr><td><b>${esc(mcN(v.cc))}</b></td><td class="r">${v.debt == null ? '—' : nf(v.debt, 0)}</td><td class="r ${cls(v.bal)}">${v.bal == null ? '—' : sgn(v.bal, 1)}</td><td class="r ${cls(pb)}">${pb == null ? '—' : sgn(pb, 1)}</td><td class="r ${v.intr > 30 ? 'dn' : ''}">${v.intr == null ? '—' : nf(v.intr, 0) + '%'}</td><td class="r">${ecFxShare(v.cc) == null ? '—' : '≈' + ecFxShare(v.cc) + '%'}</td><td class="r">${v.res == null ? '<span class="sub">reserve ccy</span>' : nf(v.res, 1)}</td><td class="r">${v.extd == null ? '—' : nf(v.extd, 0) + '%'}</td><td class="r ${cls(v.ca)}">${v.ca == null ? '—' : sgn(v.ca, 1)}</td><td class="r">${y != null && c != null ? sgn(y - c, 1) + '%' : '—'}</td><td class="r ${cls(-dy)}">${dy == null ? '—' : bpf(dy, 0)}</td><td class="r ${cls(fx)}">${fx == null ? '—' : pc(fx, 1)}</td></tr>`; }).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Annual fiscal and external data are simulated around approximate recent public figures (IMF WEO, national sources; verify). Primary balance estimated from interest/revenue and an approximate revenue-to-GDP ratio per country (e.g. Nigeria ≈10%, United States ≈30%). FX share of debt approximate. Sovereign ratings are not connected.</p></div></section>
    <div class="grid"><section class="panel c7"><header class="ph"><span class="pt">Sovereign vulnerability map</span></header><div class="pb"><div class="row" style="gap:8px;flex-wrap:wrap"><label class="note">x <select class="inp sm" data-ecc="vx">${Object.entries(ax).map(([k, v]) => `<option value="${k}" ${k === EC.vx ? 'selected' : ''}>${v[0]}</option>`).join('')}</select></label><label class="note">y <select class="inp sm" data-ecc="vy">${Object.entries(ax).map(([k, v]) => `<option value="${k}" ${k === EC.vy ? 'selected' : ''}>${v[0]}</option>`).join('')}</select></label></div><div id="ecVm"></div><p class="note">Fiscal index: average z of debt, interest/revenue (×1.2) and deficit. External index: z of current-account deficit, external debt, low reserves and 1-year currency weakness (reserve-currency issuers use current account and FX only). Identifies outliers for investigation; it does not label any country insolvent.</p></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">Sovereign stress early-warning agent</span></header><div class="pb">${ew.slice(0, 8).map(x => `<div class="ec-ew"><b>${esc(mcN(x.cc))} <span class="ec-cnt ${x.s.length >= 3 ? 'hi' : ''}">${x.s.length}</span></b><ul>${x.s.map(([a, b]) => `<li>${a}: <span class="sub">${esc(b)}</span></li>`).join('')}</ul>${x.mit.length ? `<small>Mitigating: ${esc(x.mit.join('; '))}</small>` : ''}</div>`).join('') || '<p class="note">No combinations of deteriorating indicators.</p>'}<p class="note">Combinations matter more than single metrics. Limitations: annual fiscal data lag; debt maturity schedules and upcoming financing events are not connected; IMF programmes and official support are not modelled.</p><button class="btn sm" data-ecx="ewask">Ask Superfinancials for a sovereign stress brief</button></div></section></div>
    <section class="panel"><header class="ph"><span class="pt">Debt dynamics simulator</span><span class="pm">${ecSel(cc, 'dsc', MC_IDS.filter(c => mcHas(c, 'DEBT')))}</span></header><div class="pb"><div class="gy-sliders">${[['i', 'Effective interest rate on debt, %', 0, 40, .1], ['g', 'Real GDP growth, %', -5, 10, .1], ['pi', 'GDP deflator / inflation, %', -2, 40, .1], ['pb', 'Primary balance, % GDP', -8, 8, .1], ['fxs', 'FX share of debt, %', 0, 100, 1], ['dep', 'Annual depreciation, %', -10, 60, 1]].map(([k, l, a, b, st]) => `<label><span>${l} <b id="ecds_${k}">${P[k]}</b></span><input type="range" min="${a}" max="${b}" step="${st}" value="${P[k]}" data-ecds="${k}"></label>`).join('')}</div><div class="gx-kpis s"><div><span>Debt today</span><b>${nf(d0, 0)}% GDP</b></div><div><span>Debt in 6 years</span><b class="${cls(d0 - pt.at(-1))}">${nf(pt.at(-1), 0)}% GDP</b><small>baseline ${nf(pbase.at(-1), 0)}%</small></div><div><span>Debt-stabilising primary balance</span><b>${sgn(pbStar, 1)}% GDP</b><small>vs assumed ${sgn(P.pb, 1)}%</small></div></div><div id="ecDs"></div><p class="note">d<sub>t+1</sub> = d<sub>t</sub>·(1+i)/((1+g)(1+π)) − primary balance + FX share × depreciation × d<sub>t</sub>. Defaults derived from the latest (simulated) data with an assumed revenue ratio; a teaching tool, not a debt sustainability analysis. <button class="btn sm ghost" data-ecx="dsreset">Reset</button></p></div></section>`;
  const pts = V.map(v => ({ x: ax[EC.vx][1](v), y: ax[EC.vy][1](v), r: 6, c: { Developed: 'var(--s1)', Emerging: 'var(--s2)', Frontier: 'var(--s4)' }[MCC[v.cc][2]], lab: v.cc, name: mcN(v.cc) })).filter(p => p.x != null && p.y != null);
  gyScatter($('#ecVm', el), { h: 320, pts, xlab: ax[EC.vx][0], ylab: ax[EC.vy][0], xf: v => nf(v, 1), yf: v => nf(v, 1), zeroX: EC.vx === 'fisc' || EC.vx === 'ext', zeroY: EC.vy === 'fisc' || EC.vy === 'ext', zones: EC.vx === 'fisc' && EC.vy === 'ext' ? [{ x0: .5, y0: .5, fill: 'var(--dn)', label: 'Investigate first', al: 'r' }] : [], onPick: p => { EC.dsc = p.lab; EC.ds = null; EC.draw(); } });
  const y0 = new Date(END).getUTCFullYear(); const yrs = Array.from({ length: 7 }, (_, i) => i); gxChart($('#ecDs', el), { h: 220, x: yrs, series: [{ v: pt, c: 'var(--dn)', label: 'Your assumptions', w: 2.4, pts: [6], lab: v => nf(v, 0) + '%' }, { v: pbase, c: 'var(--fg3)', label: 'Defaults', dash: '5 4' }], fl: v => nf(v, 0) + '%', xf: v => String(y0 + Math.round(v)) });
  $$('[data-ecds]', el).forEach(i => { i.oninput = () => { $('#ecds_' + i.dataset.ecds).textContent = i.value; }; i.onchange = () => { EC.ds[i.dataset.ecds] = +i.value; EC.draw(); }; });
}
EC_X.vx = b => { EC.vx = b.value; EC.draw(); }; EC_X.vy = b => { EC.vy = b.value; EC.draw(); }; EC_X.dsc = b => { EC.dsc = b.value; EC.ds = null; EC.draw(); }; EC_X.dsreset = () => { EC.ds = null; EC.draw(); };
EC_X.ewask = () => EC.ask('Write a sovereign stress early-warning brief using the fiscal and external data on this page: which countries show combinations of rising borrowing costs, weakening revenue, high interest burdens, declining reserves and currency pressure; mitigating factors; data limitations and alternative interpretations. Do not label any country insolvent.');

/* ---------- NOWCASTING & FORECASTS ---------- */
function ecNow(cc) {
  const g = mcGen(cc); if (!g.GDP || g.GDP.f !== 'Q') return null; const F = ['MPMI', 'SPMI', 'IP', 'RET', 'EMP'].filter(k => g[k] && g[k].f === 'M'); if (F.length < 2) return null; const GR = mcRel(cc, 'GDP'); const Q = g.GDP.d; const qm = qe => [2, 1, 0].map(k => Date.UTC(new Date(qe).getUTCFullYear(), new Date(qe).getUTCMonth() - k + 1, 0));
  const feat = (qe, tau) => F.map(k => { const R = mcRel(cc, k); const ms = qm(qe); const vals = ms.map(m => { const x = R.all.find(r => r.ref === m); if (tau == null) return x?.act ?? null; if (x && x.t <= tau && !x.miss) return x.first; return null; }); if (tau != null) { const av = R.all.filter(r => r.t <= tau && !r.miss); const last = av.at(-1)?.first ?? null; return { k, v: gyM(vals.map(v => v ?? last).filter(v => v != null)), have: vals.filter(v => v != null).length }; } return { k, v: gyM(vals.filter(v => v != null)), have: 3 }; });
  const fit = upto => { const X = [], y = []; Q.forEach((qe, i) => { if (qe >= upto || i < 4) return; const f = feat(qe); if (f.some(x => !isFinite(x.v))) return; X.push([1, ...f.map(x => x.v)]); y.push(g.GDP.v[i]); }); return X.length > 10 ? gxMOLS(X, y) : null; };
  const est = (o, qe, tau) => { const f = feat(qe, tau); if (f.some(x => !isFinite(x.v))) return null; const have = f.reduce((s, x) => s + x.have, 0) / (F.length * 3); return { v: [1, ...f.map(x => x.v)].reduce((s, v, j) => s + v * o.coef[j], 0), sd: o.se * (1 + .9 * (1 - have)), have, f }; };
  const back = GR.past.slice(-8).map(r => { const o = fit(r.ref - 80 * DAY); if (!o) return null; const e = est(o, r.ref, r.t - DAY); const prevQ = GR.past.find(x => x.ref === Q[Q.indexOf(r.ref) - 1]); return e && { ref: r.ref, now: e.v, first: r.first, act: r.act, naive: prevQ?.act }; }).filter(Boolean); const rmse = a => Math.sqrt(gyM(a.map(v => v * v))); const err = rmse(back.map(b => b.now - b.first)), nerr = rmse(back.filter(b => b.naive != null).map(b => b.naive - b.first));
  const last = GR.last; const pend = []; let qe = Date.UTC(new Date(last.ref).getUTCFullYear(), new Date(last.ref).getUTCMonth() + 4, 0); while (qe - 92 * DAY < END) { pend.push(qe); qe = Date.UTC(new Date(qe).getUTCFullYear(), new Date(qe).getUTCMonth() + 4, 0); }
  const o = fit(END); const cur = pend.map(qe => { const qs = qe - 91 * DAY; const ds = [qs - 25 * DAY]; F.forEach(k => mcRel(cc, k).all.forEach(r => { if (r.t > qs - 25 * DAY && r.t <= END && !r.miss) ds.push(r.t); })); const tau = [...new Set(ds)].sort((a, b) => a - b); let prev = null; const path = tau.map(t => { const e = est(o, qe, t); const who = F.map(k => mcRel(cc, k).all.find(r => r.t === t && !r.miss)).filter(Boolean).map((r, j) => F.find(k => mcRel(cc, k).all.includes(r))); const step = e && prev ? e.v - prev.v : 0; prev = e || prev; return e && { t, ...e, step, who }; }).filter(Boolean); return { qe, path, rel: (() => { let t = qe + mcLag(cc, 'GDP', 'Q') * DAY; while ([0, 6].includes(new Date(t).getUTCDay())) t += DAY; return t; })() }; });
  return { F, o, back, err, nerr, cur, Q, g }; }
function ecFcVint(cc, k) { const r = rng(hash('fcv' + cc + k)); const L = mcLast(cc, k); if (!L) return null; const tgt = MCC[cc][5]; const base = k === 'CPI' ? L.v * .55 + tgt * .45 : L.v * .6 + gyM(mcGen(cc)[k].v.slice(-20)) * .4; const yr = new Date(END).getUTCFullYear() + 1; const V = []; let f = base; for (let j = 0; j < 7; j++) { const t = END - j * 91 * DAY; const ago = mcAt(cc, k, t - 60 * DAY); V.unshift({ t, v: f }); f = f - (ago != null ? (L.v - ago) * .25 / 7 : 0) + (r() - .5) * (k === 'CPI' ? .3 + Math.abs(L.v) * .03 : .25); } return { yr, V, now: V.at(-1).v, ago6: V.at(-3).v }; }
function ecFan(cc) { const s = mcGen(cc).CPI; if (!s || s.f !== 'M') return null; const tgt = MCC[cc][5]; const y = s.v; const dev = y.map(v => v - tgt); const o = gyOLS(dev.slice(0, -1), dev.slice(1)); const phi = Math.max(.6, Math.min(.99, o?.b ?? .9)); const H = 24; const errs = Array.from({ length: H }, () => []); for (let i = 36; i < y.length - 1; i++) { let d = dev[i]; for (let h = 1; h <= H && i + h < y.length; h++) { d *= phi; errs[h - 1].push(dev[i + h] - d); } } const sd = errs.map(e => e.length > 3 ? Math.sqrt(gyM(e.map(v => v * v))) : null); const fc = []; let d = dev.at(-1); for (let h = 1; h <= H; h++) { d *= phi; fc.push(tgt + d); } return { phi, fc, sd, tgt, d: s.d, v: y }; }
function ecNowTab(el) {
  const ok = MC_IDS.filter(c => ecNow(c)); const cc = ok.includes(EC.ncc) ? EC.ncc : ok[0]; const N = ecNow(cc); const fcc = MC_IDS.includes(EC.fcc) ? EC.fcc : 'US'; const FV = ['GDP', 'CPI'].map(k => ({ k, v: ecFcVint(fcc, k) })); const FAN = ecFan(fcc);
  const rev = MC_IDS.map(c => ({ c, g: ecFcVint(c, 'GDP'), p: ecFcVint(c, 'CPI') })).filter(x => x.g);
  const cq = N.cur.at(-1), pq = N.cur.length > 1 ? N.cur[0] : null; const lastStep = cq?.path.slice(-6).filter(p => Math.abs(p.step) > .005) || [];
  const lead = [['Manufacturing PMI', 'MPMI'], ['Services PMI', 'SPMI'], ['Consumer confidence', 'CONF'], ['Private credit growth', 'CRED'], ['Financial conditions', 'FCI']].filter(([, k]) => mcHas(cc, k)).map(([n, k]) => { const L = mcLast(cc, k); return [n, mcFmt(k, L.v), (L.mom3 || 0) * (MI[k][5] || 1) > 0 ? 'improving' : (L.mom3 || 0) * (MI[k][5] || 1) < 0 ? 'deteriorating' : 'flat']; });
  el.innerHTML = `<div class="fi-tb"><div class="row" style="gap:8px">${ecSel(cc, 'ncc', ok)}</div><span class="note">Bridge-equation nowcast of real GDP y/y from ${N.F.map(k => MI[k][0]).join(', ')} · model estimate</span></div>
    <div class="grid"><section class="panel c7"><header class="ph"><span class="pt">Nowcast vs official data</span></header><div class="pb"><div id="ecNw"></div>${gxLeg([['var(--fg)', 'Official GDP (latest vintage)'], ['var(--fg3)', 'First print', 1], ['#2e6bd9', 'Nowcast the day before release (point-in-time inputs)']])}<p class="note">Backtest over the last ${N.back.length} quarters: nowcast RMSE ${nf(N.err, 2)} pp vs ${nf(N.nerr, 2)} pp for a naive "same as last quarter" rule. Inputs use first prints available at each date; the regression is estimated on latest-vintage history before each quarter (a full real-time backtest would also use historical vintages, as in ALFRED).</p></div></section>
      <section class="panel c5"><header class="ph"><span class="pt">Current-quarter estimate</span></header><div class="pb">${cq?.path.length ? `<div class="gx-kpis s"><div><span>${mcRef(cq.qe, 'Q')} nowcast</span><b>${nf(cq.path.at(-1).v, 1)}%</b><small>± ${nf(cq.path.at(-1).sd, 1)} pp (68%) · ${nf(cq.path.at(-1).have * 100, 0)}% of monthly inputs released</small></div>${pq?.path.length ? `<div><span>${mcRef(pq.qe, 'Q')} (awaiting release)</span><b>${nf(pq.path.at(-1).v, 1)}%</b><small>official due ${fd(pq.rel)}</small></div>` : ''}</div><div id="ecNp"></div><p class="gy-interp">${lastStep.length ? `Since ${fd(lastStep[0].t, { day: '2-digit', month: 'short' })} the estimate has ${cq.path.at(-1).v < lastStep[0].v - lastStep[0].step ? 'weakened' : 'strengthened'}, mainly due to ${lastStep.slice().sort((a, b) => Math.abs(b.step) - Math.abs(a.step)).slice(0, 2).map(p => `${(p.who || []).map(k => MI[k]?.[0]).filter(Boolean).join(' / ') || 'new data'} (${sgn(p.step, 2)} pp)`).join(' and ')}.` : 'No new inputs have moved the estimate recently.'}</p>` : '<p class="note">No pending quarter.</p>'}<p class="note">Estimates are labelled model output. Uncertainty widens when fewer months of data are available.</p></div></section></div>
    <div class="grid"><section class="panel c5"><header class="ph"><span class="pt">Leading and high-frequency indicators</span></header><div class="pb"><dl class="kl">${lead.map(([a, b, c]) => `<div><dt>${a}</dt><dd>${b} <span class="${c === 'improving' ? 'up' : c === 'deteriorating' ? 'dn' : 'sub'}">${c}</span></dd></div>`).join('')}<div><dt>Freight (dry bulk)</dt><dd>${pc(cmRet('CM.BDIX', 21), 1)} 1M <span class="sub">illustrative</span></dd></div><div><dt>Electricity demand, card spending, port activity, satellite proxies</dt><dd>not connected</dd></div></dl></div></section>
      <section class="panel c7"><header class="ph"><span class="pt">Forecast revision tracker</span><span class="pm">next-year forecasts · simulated vintages</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Economy</th><th class="r">GDP ${rev[0].g.yr} now</th><th class="r">6 months ago</th><th class="r">Revision</th><th class="r">CPI ${rev[0].g.yr} now</th><th class="r">6 months ago</th><th class="r">Revision</th></tr></thead><tbody>${rev.sort((a, b) => Math.abs(b.g.now - b.g.ago6) - Math.abs(a.g.now - a.g.ago6)).map(x => `<tr><td><a href="#" data-ecx="fcc" data-v="${x.c}">${esc(mcN(x.c))}</a></td><td class="r">${nf(x.g.now, 1)}%</td><td class="r sub">${nf(x.g.ago6, 1)}%</td><td class="r ${cls(x.g.now - x.g.ago6)}">${sgn(x.g.now - x.g.ago6, 1)}</td><td class="r">${x.p ? nf(x.p.now, 1) + '%' : '—'}</td><td class="r sub">${x.p ? nf(x.p.ago6, 1) + '%' : '—'}</td><td class="r ${x.p ? cls(-(x.p.now - x.p.ago6)) : ''}">${x.p ? sgn(x.p.now - x.p.ago6, 1) : '—'}</td></tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Simulated institutional-style forecast vintages, quarterly (production: IMF WEO, OECD, consensus surveys). Sorted by size of growth revision.</p></div></section></div>
    <div class="grid"><section class="panel c6"><header class="ph"><span class="pt">Forecast vintages · ${esc(mcN(fcc))}</span><span class="pm">${ecSel(fcc, 'fcc2')}</span></header><div class="pb"><div id="ecFv"></div>${gxLeg([['var(--s3)', 'Real GDP forecast'], ['var(--s2)', 'CPI forecast']])}</div></section>
      <section class="panel c6"><header class="ph"><span class="pt">Inflation forecast fan chart</span><span class="pm">model projection · 24 months</span></header><div class="pb">${FAN ? `<div id="ecFan"></div><div class="tw"><table class="t dense"><thead><tr><th>Horizon</th><th class="r">3m</th><th class="r">6m</th><th class="r">12m</th><th class="r">24m</th></tr></thead><tbody><tr><td>Projection</td>${[3, 6, 12, 24].map(h => `<td class="r">${nf(FAN.fc[h - 1], 1)}%</td>`).join('')}</tr><tr><td>Past forecast error (RMSE)</td>${[3, 6, 12, 24].map(h => `<td class="r">${FAN.sd[h - 1] == null ? '—' : '±' + nf(FAN.sd[h - 1], 1)}</td>`).join('')}</tr></tbody></table></div><p class="note">AR(1) reversion toward the ${FAN.tgt}% target (persistence ${nf(FAN.phi, 2)}), bands from this model's own backtested errors. Official and consensus projections are not connected; compare the model against them before relying on it.</p>` : '<p class="note">No monthly CPI series.</p>'}</div></section></div>`;
  const back = N.back; const Qx = N.Q.slice(-12); const bi = q => back.find(b => b.ref === q); gxChart($('#ecNw', el), { h: 260, x: Qx, series: [{ v: Qx.map(q => mcAt(cc, 'GDP', q)), c: 'var(--fg)', label: 'Official (latest)', w: 2 }, { v: Qx.map(q => mcRel(cc, 'GDP').all.find(r => r.ref === q)?.first ?? null), c: 'var(--fg3)', label: 'First print', dash: '4 3' }, { v: Qx.map(q => bi(q)?.now ?? null), c: '#2e6bd9', label: 'Nowcast', pts: Qx.map((q, i) => bi(q) ? i : null).filter(i => i != null) }], fl: v => nf(v, 1) + '%' });
  if (cq?.path.length) { const p = cq.path; gxChart($('#ecNp', el), { h: 200, x: p.map(q => q.t), series: [{ v: p.map(q => q.v), c: '#2e6bd9', label: 'Nowcast', w: 2.2 }], bands: [{ lo: p.map(q => q.v - q.sd), hi: p.map(q => q.v + q.sd), c: '#2e6bd9', op: .14, label: '±1 sd' }], fl: v => nf(v, 1) + '%', marks: p.filter(q => Math.abs(q.step) > .05).map(q => ({ t: q.t, label: `${(q.who || []).map(k => MI[k]?.[0]).join(', ')}: ${sgn(q.step, 2)} pp`, c: q.step > 0 ? 'var(--up)' : 'var(--dn)' })) }); }
  const fx = FV[0].v.V.map(x => x.t); gxChart($('#ecFv', el), { h: 220, x: fx, series: FV.filter(f => f.v).map((f, i) => ({ v: f.v.V.map(x => x.v), c: i ? 'var(--s2)' : 'var(--s3)', label: `${MI[f.k][0]} ${f.v.yr}`, pts: [fx.length - 1], lab: v => nf(v, 1) + '%' })), fl: v => nf(v, 1) + '%' });
  if (FAN) { const h0 = FAN.d.slice(-36); const fut = FAN.fc.map((_, i) => Date.UTC(new Date(h0.at(-1)).getUTCFullYear(), new Date(h0.at(-1)).getUTCMonth() + i + 2, 0)); const X = [...h0, ...fut]; const n0 = h0.length; const sd = i => FAN.sd[i] ?? FAN.sd.filter(Boolean).at(-1); gxChart($('#ecFan', el), { h: 230, x: X, split: n0 - 1, splitLab: 'latest', series: [{ v: [...FAN.v.slice(-36), ...fut.map(() => null)], c: 'var(--fg)', label: 'CPI y/y' }, { v: [...h0.map((_, i) => i === n0 - 1 ? FAN.v.at(-1) : null), ...FAN.fc], c: 'var(--s2)', label: 'Projection', dash: '5 3' }], bands: [{ lo: [...h0.map(() => null), ...FAN.fc.map((v, i) => v - 1.64 * sd(i))], hi: [...h0.map(() => null), ...FAN.fc.map((v, i) => v + 1.64 * sd(i))], c: 'var(--s2)', op: .1, label: '90%' }, { lo: [...h0.map(() => null), ...FAN.fc.map((v, i) => v - sd(i))], hi: [...h0.map(() => null), ...FAN.fc.map((v, i) => v + sd(i))], c: 'var(--s2)', op: .16, label: '68%' }], hl: [{ y: FAN.tgt, c: 'var(--fg3)' }], fl: v => nf(v, 1) + '%' }); }
}
EC_X.ncc = b => { EC.ncc = b.value; EC.draw(); }; EC_X.fcc = b => { EC.fcc = b.dataset.v; EC.draw(); }; EC_X.fcc2 = b => { EC.fcc = b.value; EC.draw(); };

/* ---------- MACRO-TO-MARKET ---------- */
const ecBeta = (asset, drv, n = 750) => gyOLS(gyDx(drv, n), gyDx(asset, n));
function ecES(cc, k, id, win = 5) { const R = mcRel(cc, k); if (!R || !id) return null; const D = NX_D(); const ev = R.past.filter(x => x.z != null && x.t > END - 1460 * DAY); const isY = /^YD\.|^MM\./.test(id); const val = t => valAt(id, t); const fxs = /^FX\.USD/.test(id) ? -1 : 1; const path = x => { const i = bsLE(D, x.t); if (i < win + 1 || i + win >= D.length) return null; const b = val(D[i - 1]); return Array.from({ length: 2 * win + 1 }, (_, j) => { const v = val(D[i - win + j]); return isY ? (v - b) * 100 : (v / b - 1) * 100 * (/^FX\./.test(id) ? fxs : 1); }); }; const P = ev.map(x => ({ x, p: path(x) })).filter(e => e.p); const pos = P.filter(e => e.x.z > .5), neg = P.filter(e => e.x.z < -.5); const avg = a => a.length ? Array.from({ length: 2 * win + 1 }, (_, j) => gyM(a.map(e => e.p[j]))) : null; const d0 = P.map(e => ({ z: e.x.z, r: e.p[win] })); const o = gyOLS(d0.map(e => e.z), d0.map(e => e.r)); const cpiUp = e => { const t = e.x.t; const a = mcAt(cc, k === 'CPI' || MI[k][1] === 'in' ? 'CPI' : 'MPMI', t - 20 * DAY), b = mcAt(cc, k === 'CPI' || MI[k][1] === 'in' ? 'CPI' : 'MPMI', t - 110 * DAY); return a != null && b != null && a > b; }; const up = P.filter(cpiUp), dn = P.filter(e => !cpiUp(e)); const oU = gyOLS(up.map(e => e.x.z), up.map(e => e.p[win])), oD = gyOLS(dn.map(e => e.x.z), dn.map(e => e.p[win])); return { win, pos: avg(pos), neg: avg(neg), np: pos.length, nn: neg.length, o, d0, oU, oD, nU: up.length, nD: dn.length, isY, regK: MI[k][1] === 'in' ? 'inflation' : 'manufacturing PMI' }; }
const EC_TH = { usEase: ['Falling inflation and resilient employment will support a gradual U.S. easing cycle', 'US', [['Core inflation falling over 3 months', t => ecChg('US', 'CORE', t) < 0], ['Unemployment within 0.4 pp of its 12-month low', t => ecUrGap('US', t) < .4], ['Fed held or cut over 3 months', t => ecChg('US', 'POL', t) <= 0], ['2-year Treasury yield lower over 3 months', t => ecYC('YD.US2', t) < 0], ['Growth momentum positive', t => (mcRegime('US').rows[bsLE(mcM(), t)]?.gm ?? 0) > 0]], ['CPI', 'NFP', 'POL'], ['ET.TLT', 'ET.XLRE', 'IX.SPX']], ngReal: ['Positive real interest rates in Nigeria will support the naira', 'NG', [['Real policy rate above zero', t => (mcAt('NG', 'POL', t) - mcAt('NG', 'CPI', t)) > 0], ['Headline inflation falling over 3 months', t => ecChg('NG', 'CPI', t) < 0], ['Naira (official) stable or stronger over 3 months', t => (mcFxRet('FX.USDNGN', t - 91 * DAY, t) ?? -1) >= -1], ['Reserves rising over 6 months', t => ecChg('NG', 'RES', t, 6) > 0], ['Oil above $65', t => (valAt('CM.CO1', Math.min(t, END)) ?? 0) > 65]], ['CPI', 'POL', 'RES'], ['FX.USDNGN', 'YD.NG10', 'IX.NGSEINDX']], brEase: ['Disinflation will let Brazil ease aggressively', 'BR', [['Headline inflation falling over 3 months', t => ecChg('BR', 'CPI', t) < 0], ['Real policy rate above 5%', t => (mcAt('BR', 'POL', t) - mcAt('BR', 'CPI', t)) > 5], ['Real stable over 3 months (> −3%)', t => (mcFxRet('FX.USDBRL', t - 91 * DAY, t) ?? -9) > -3], ['BCB cut over 3 months', t => ecChg('BR', 'POL', t) < 0]], ['CPI', 'POL'], ['FX.USDBRL', 'YD.BR10', 'IX.IBOV']], cnStim: ['Chinese stimulus will lift manufacturing', 'CN', [['Manufacturing PMI above 50', t => (mcAt('CN', 'MPMI', t) ?? 0) > 50], ['PMI rising over 3 months', t => ecChg('CN', 'MPMI', t) > 0], ['Credit growth accelerating over 6 months', t => ecChg('CN', 'CRED', t, 6) > 0], ['Producer prices improving over 3 months', t => ecChg('CN', 'PPI', t) > 0], ['Copper higher over 3 months', t => (valAt('CM.HG1', Math.min(t, END)) / valAt('CM.HG1', t - 91 * DAY) - 1) > 0]], ['MPMI', 'IP', 'CPI'], ['CM.HG1', 'IX.SHCOMP', 'FX.USDCNH']], euRec: ['Euro-area growth will recover without reigniting inflation', 'EU', [['Manufacturing PMI rising over 3 months', t => ecChg('EU', 'MPMI', t) > 0], ['GDP growth higher than a quarter ago', t => ecChg('EU', 'GDP', t) > 0], ['Core inflation at or below 2.5%', t => (mcAt('EU', 'CORE', t) ?? 9) <= 2.5], ['ECB not tightening', t => ecChg('EU', 'POL', t) <= 0]], ['MPMI', 'CPI', 'GDP'], ['IX.SX5E', 'FX.EURUSD', 'YD.DE10']] };
const ecChg = (cc, k, t, m = 3) => { const a = mcAt(cc, k, t), b = mcAt(cc, k, t - m * 30.5 * DAY); return a == null || b == null ? 0 : a - b; };
const ecUrGap = (cc, t) => { const s = mcGen(cc).UR; if (!s) return 0; const i = bsLE(s.d, t); return s.v[i] - Math.min(...s.v.slice(Math.max(0, i - 12), i + 1)); };
const ecYC = (id, t) => { const a = valAt(id, Math.min(t, END)), b = valAt(id, t - 91 * DAY); return a == null || b == null ? 0 : a - b; };
function ecMkt(el) {
  const sh = EC.shock; const cc = 'US'; const es = (k, id) => ecES(cc, k, id)?.o; const bp = (o, s = 1) => o ? bpf(o.b * s, 1) : '—', pp = (o, s = 1) => o ? pc(o.b * s, 2) : '—';
  const SEC = SECTORS.filter(o => BY[o.id]); const drv = [['YD.US10', '10Y +10bp', 10, 'bp'], ['FX.DXY', 'USD +1%', 1, '%'], ['CM.CO1', 'Oil +10%', 10, '%'], ['SP.HYOAS', 'HY spread +10bp', 10, 'bp'], ['IX.SPX', 'S&P 500 +1%', 1, '%']].filter(d => BY[d[0]]); const SB = SEC.map(o => ({ o, b: drv.map(d => ecBeta(o.id, d[0])?.b * d[2]) })); const sm = drv.map((_, j) => Math.max(...SB.map(r => Math.abs(r.b[j] || 0))) || 1);
  const cpiES = ecES('US', 'CPI', 'YD.US2'), pmiES = ecES('US', 'MPMI', 'YD.US2'); const RF = ecRF("US"); const oilCpi = (() => { const M = mcM().slice(-96); const oy = M.map(t => { const a = valAt('CM.CO1', Math.min(t, END)), b = valAt('CM.CO1', t - 365 * DAY); return a && b ? (a / b - 1) * 100 : null; }); const c = M.map(t => mcAt('US', 'CPI', t + 60 * DAY)); const ok = oy.map((v, i) => v != null && c[i] != null); return gyOLS(oy.filter((_, i) => ok[i]), c.filter((_, i) => ok[i])); })();
  const nodes = { infl: [`U.S. CPI surprise of +1σ`, `Policy: reaction-function weight on inflation gap ${RF ? nf(RF.o.coef[1], 2) : '—'} pp per 1 pp over 6m; 2Y yield ${bp(cpiES?.o)} on release day`, `2Y ${bp(cpiES?.o)}, dollar index ${pp(es('CPI', 'FX.DXY'))}, S&P 500 ${pp(es('CPI', 'IX.SPX'))}, gold ${pp(es('CPI', 'CM.GC1'))} per 1σ (release day, 4 years)`, `Rate-sensitive sectors: ${SB.slice().sort((a, b) => (a.b[0] || 0) - (b.b[0] || 0)).slice(0, 2).map(r => r.o.tk).join(', ')} most hurt by higher yields; input costs and pricing power vary`, 'Duration exposure, real-rate sensitivity of holdings, valuation multiples'], grow: ['U.S. manufacturing PMI surprise of −1σ', `Policy: reaction-function weight on growth ${RF ? nf(RF.o.coef[2], 2) : '—'} pp per 1 z; 2Y ${bp(pmiES?.o, -1)} per −1σ PMI surprise`, `2Y ${bp(pmiES?.o, -1)}, S&P 500 ${pp(es('MPMI', 'IX.SPX'), -1)}, dollar ${pp(es('MPMI', 'FX.DXY'), -1)}, copper ${pp(es('MPMI', 'CM.HG1'), -1)} per −1σ`, `Cyclical sectors with highest market beta: ${SB.slice().sort((a, b) => (b.b[4] || 0) - (a.b[4] || 0)).slice(0, 3).map(r => r.o.tk).join(', ')}; demand and revenue sensitivity`, 'Earnings revisions, credit risk, cyclical vs defensive tilt'], oil: ['Oil +10%', `Inflation pass-through: CPI y/y ${oilCpi ? sgn(oilCpi.b * 10, 2) : '—'} pp per +10% oil y/y (2-month lag, r ${oilCpi ? nf(oilCpi.r, 2) : '—'}); central banks may look through supply shocks`, `Betas to oil: ${['FX.USDCAD', 'FX.USDNGN', 'IX.SPX', 'YD.US10', 'FX.USDJPY'].filter(id => BY[id]).map(id => `${BY[id].tk || id} ${(() => { const o = ecBeta(id, 'CM.CO1'); return o ? (/^YD/.test(id) ? bpf(o.b * 10, 1) : pc(o.b * 10 * (/^FX\.USD/.test(id) ? -1 : 1), 2)) : '—'; })()}`).join(', ')} (FX: + = local currency stronger)`, `Energy (XLE) +${nf((ecBeta('ET.XLE', 'CM.CO1')?.b || 0) * 10, 1)}%; airlines, chemicals and transport face higher input costs`, 'Exporters vs importers (see Commodities → Africa & Nigeria), inflation hedges'], fisc: ['Fiscal expansion', 'Higher deficits can raise term premia and policy-rate expectations; the effect depends on credibility and financing', 'Historical relationship not estimable here: annual fiscal data give too few observations (insufficient data). Use the debt simulator for scenarios.', 'Government-contract and infrastructure sectors may benefit; crowding out raises funding costs', 'Sovereign spreads, currency, duration'], trade: ['Trade disruption (freight +25%, export route closed)', 'Supply shock: higher goods and food prices, weaker activity; central banks face a trade-off', `Dry-bulk freight 1M ${pc(cmRet('CM.BDIX', 21), 1)} (illustrative); EM currencies and commodity importers most exposed`, 'Margins of importers and manufacturers; inventory and sourcing costs', 'Supply-chain exposure (see Commodities → Physical markets & trade flows)'] }[sh];
  const ESX = EC.es; const ESR = ecES(ESX.cc, ESX.k, mcAssets(ESX.cc)[ESX.a] || ESX.a); const consK = MC_IDS.flatMap(c => mcKeys(c).filter(k => mcRel(c, k)?.hasC || mcRel(c, k)?.eco).map(k => [c, k]));
  const port = S.ecPort || (S.ecPort = [['ET.XLK', 30000], ['ET.XLF', 20000], ['ET.XLE', 15000], ['ET.TLT', 20000], ['ET.GLD', 10000], ['ET.EMB', 5000]].filter(([id]) => BY[id]).map(([id, v]) => ({ id, v }))); const shocks = [['Rates +25bp', 'YD.US10', 25], ['USD +2%', 'FX.DXY', 2], ['Oil +10%', 'CM.CO1', 10], ['Credit spreads +50bp', 'SP.HYOAS', 50], ['Equities −5%', 'IX.SPX', -5]].filter(s => BY[s[1]]); const PX = port.map(h => ({ ...h, e: shocks.map(s => { const o = ecBeta(h.id, s[1]); return o ? h.v * o.b * s[2] / 100 : 0; }) })); const tot = shocks.map((_, j) => PX.reduce((s, h) => s + h.e[j], 0)); const tv = port.reduce((s, h) => s + h.v, 0);
  const ths = (S.ecTh || (S.ecTh = ['usEase', 'ngReal'])).filter(k => EC_TH[k]);
  el.innerHTML = `<section class="panel" id="ecTMs"></section>
    <section class="panel"><header class="ph"><span class="pt">Asset sensitivity explorer · event study</span></header><div class="pb"><div class="row" style="gap:8px;flex-wrap:wrap"><select class="inp sm" data-ecc="esk">${consK.map(([c, k]) => `<option value="${c}|${k}" ${c === ESX.cc && k === ESX.k ? 'selected' : ''}>${esc(mcN(c) + ' · ' + MI[k][0])}</option>`).join('')}</select><select class="inp sm" data-ecc="esa">${[['y2', 'Local 2Y yield'], ['y10', 'Local 10Y yield'], ['fx', 'Local currency'], ['eq', 'Local equity index'], ['CM.GC1', 'Gold'], ['CM.CO1', 'Brent'], ['IX.SPX', 'S&P 500'], ['FX.DXY', 'Dollar index']].map(([k, l]) => `<option value="${k}" ${k === ESX.a ? 'selected' : ''}>${l}</option>`).join('')}</select></div>${ESR && ESR.d0.length > 3 ? `<div class="grid"><div class="c6"><div id="ecEp"></div>${gxLeg([['var(--up)', `Surprise > +0.5σ (n=${ESR.np})`], ['var(--dn)', `Surprise < −0.5σ (n=${ESR.nn})`]])}</div><div class="c6"><div id="ecEs"></div></div></div><dl class="kl"><div><dt>Release-day move per 1σ surprise</dt><dd>${ESR.isY ? bpf(ESR.o?.b, 2) : pc(ESR.o?.b, 3)} (t ${nf(ESR.o?.tb, 1)}, r ${nf(ESR.o?.r, 2)}, n ${ESR.o?.n})</dd></div><div><dt>When ${ESR.regK} was rising beforehand</dt><dd>${ESR.oU ? `${ESR.isY ? bpf(ESR.oU.b, 2) : pc(ESR.oU.b, 3)} per 1σ (n ${ESR.nU})` : 'too few events'}</dd></div><div><dt>When ${ESR.regK} was falling</dt><dd>${ESR.oD ? `${ESR.isY ? bpf(ESR.oD.b, 2) : pc(ESR.oD.b, 3)} per 1σ (n ${ESR.nD})` : 'too few events'}</dd></div></dl>` : '<p class="note">Not enough events with surprises and market data for this combination.</p>'}<p class="note">Cumulative close-to-close moves from the day before the release (day 0 = release date), 4 years of simulated data. Small samples: check n and t-stat before drawing conclusions. Currency: + = local currency stronger. Simulated market prices do not react to simulated releases, so expect insignificant results here.</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Sector exposure map</span><span class="pm">daily betas, 3 years</span></header><div class="pb flush"><div class="tw"><table class="t dense"><thead><tr><th>Sector</th>${drv.map(d => `<th class="r">${d[1]}</th>`).join('')}</tr></thead><tbody>${SB.map(r => `<tr><td><b>${esc(r.o.tk)}</b> <span class="sub">${esc(r.o.short || r.o.sector || '')}</span></td>${r.b.map((v, j) => `<td class="r" style="background:color-mix(in srgb,${v >= 0 ? 'var(--up)' : 'var(--dn)'} ${Math.round(Math.abs(v || 0) / sm[j] * 45)}%,var(--panel))">${v == null || !isFinite(v) ? '—' : pc(v, 2)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="note" style="padding:0 20px">Each cell: expected sector move for the stated macro move, from univariate daily regressions (simulated). Drivers are correlated, so effects are not additive. Earnings sensitivity from segment disclosures is not connected.</p></div></section>
    <section class="panel"><header class="ph"><span class="pt">Portfolio macro dashboard</span></header><div class="pb"><div class="tw"><table class="t dense"><thead><tr><th>Holding</th><th class="r">Value</th>${shocks.map(s => `<th class="r">${s[0]}</th>`).join('')}<th></th></tr></thead><tbody>${PX.map((h, i) => `<tr><td><b>${esc(BY[h.id].tk)}</b> <span class="sub">${esc(BY[h.id].name)}</span></td><td class="r"><input class="inp sm" type="number" step="1000" value="${h.v}" data-ecpf="${i}" style="width:95px"></td>${h.e.map(v => `<td class="r ${cls(v)}">${big(v, '$')}</td>`).join('')}<td><button class="btn sm ghost" data-ecx="pfrm" data-v="${i}" aria-label="Remove">✕</button></td></tr>`).join('')}<tr><td><b>Total</b></td><td class="r"><b>${big(tv, '$')}</b></td>${tot.map(v => `<td class="r ${cls(v)}"><b>${big(v, '$')}</b><div class="sub">${pc(v / tv * 100, 2)}</div></td>`).join('')}<td></td></tr></tbody></table></div><div class="row" style="gap:6px;margin-top:8px"><select class="inp sm" data-ecs="pfadd">${[...SECTORS, ...STYLE, ...FI.filter(o => o.type === 'etf'), ...CMD.filter(o => o.type === 'etf')].filter(o => BY[o.id]).map(o => `<option value="${o.id}">${esc(o.tk)} · ${esc(o.name)}</option>`).join('')}</select><button class="btn sm" data-ecx="pfadd">Add</button></div><p class="note">Sensitivity = value × daily beta to each macro variable × shock (3 years, simulated). Shocks are applied one at a time; real episodes combine them.</p></div></section>
      <section class="panel"><header class="ph"><span class="pt">Macro thesis monitor</span><span class="pm">evidence for and against your theses, updated with each release</span></header><div class="pb"><div class="ec-ths2">${ths.map(k => ecThesis(k)).join('')}</div><div class="row" style="gap:6px;margin-top:8px"><select class="inp sm" data-ecs="thadd">${Object.entries(EC_TH).filter(([k]) => !ths.includes(k)).map(([k, v]) => `<option value="${k}">${esc(v[0])}</option>`).join('')}</select><button class="btn sm" data-ecx="thadd">Track thesis</button></div></div></section>`;
  ecTMRender($('#ecTMs', el));
  if (ESR && ESR.d0.length > 3) { const xs = Array.from({ length: 2 * ESR.win + 1 }, (_, j) => j - ESR.win); gxChart($('#ecEp', el), { h: 220, x: xs, xf: v => (v > 0 ? '+' : '') + v, series: [...(ESR.pos ? [{ v: ESR.pos, c: 'var(--up)', label: 'Positive surprises' }] : []), ...(ESR.neg ? [{ v: ESR.neg, c: 'var(--dn)', label: 'Negative surprises' }] : [])], zero: true, fl: v => ESR.isY ? nf(v, 1) + 'bp' : nf(v, 2) + '%', marks: [{ t: 0, label: 'Release day', c: 'var(--fg3)' }] }); gyScatter($('#ecEs', el), { h: 220, pts: ESR.d0.map(e => ({ x: e.z, y: e.r, r: 4, c: e.z > 0 ? 'var(--up)' : 'var(--dn)' })), fits: ESR.o ? [{ o: ESR.o, color: 'var(--fg2)', ci: true }] : [], xlab: 'Surprise (σ)', ylab: 'Release-day move', xf: v => sgn(v, 1), yf: v => nf(v, 1), zeroX: true, zeroY: true }); }
  $$('[data-ecpf]', el).forEach(i => i.onchange = () => { S.ecPort[+i.dataset.ecpf].v = +i.value; save(); EC.draw(); });
}
function ecThesis(k) { const [t, cc, checks, nx, exp] = EC_TH[k]; const now = checks.map(([n, f]) => ({ n, ok: !!f(END), was: !!f(END - 30 * DAY) })); const sup = now.filter(c => c.ok), con = now.filter(c => !c.ok), flip = now.filter(c => c.ok !== c.was); const st = sup.length / now.length >= .75 ? ['Supported', 'up'] : sup.length / now.length <= .35 ? ['Contradicted', 'dn'] : ['Mixed evidence', '']; const nx2 = nx.filter(q => !EC_NOREL.includes(q) && mcRel(cc, q)); const ev = nx2.map(q => `${MI[q][0]} ${fd(mcRel(cc, q).next.t, { day: '2-digit', month: 'short' })}`); const pi = ecPolInfo(cc); if (pi?.next) ev.push(`${MCC[cc][4]} meeting ${fd(pi.next, { day: '2-digit', month: 'short' })}`);
  return `<article class="ec-th"><header><b>${esc(t)}</b><span class="ec-ths ${st[1]}">${st[0]} · ${sup.length}/${now.length}</span><button class="btn sm ghost" data-ecx="thrm" data-v="${k}" aria-label="Stop tracking">✕</button></header><ul>${sup.map(c => `<li class="up">✓ ${esc(c.n)}</li>`).join('')}${con.map(c => `<li class="dn">✗ ${esc(c.n)}</li>`).join('')}</ul><small>${flip.length ? `Changed in the last month: ${flip.map(c => `${c.n} (${c.ok ? 'now supports' : 'no longer supports'})`).join('; ')}. ` : 'No assumption changed status in the last month. '}Next: ${ev.join(', ')}. Exposures: ${exp.filter(id => BY[id]).map(id => `${/^FX\.USD/.test(id) ? id.slice(6) + ' vs USD' : BY[id].tk || id} ${pc((valAt(id, END) / valAt(id, gyD(63)) - 1) * 100 * (/^FX\.USD/.test(id) ? -1 : 1), 1)} 3m`).join(', ')}</small></article>`; }
EC_SEG.ecsh = v => EC.shock = v; EC_X.esk = b => { const [cc, k] = b.value.split('|'); EC.es.cc = cc; EC.es.k = k; EC.draw(); }; EC_X.esa = b => { EC.es.a = b.value; EC.draw(); };
EC_X.pfrm = b => { S.ecPort.splice(+b.dataset.v, 1); save(); EC.draw(); }; EC_X.pfadd = () => { const v = $('[data-ecs="pfadd"]').value; S.ecPort.push({ id: v, v: 10000 }); save(); EC.draw(); };
EC_X.thadd = () => { const v = $('[data-ecs="thadd"]')?.value; if (v && !S.ecTh.includes(v)) { S.ecTh.push(v); save(); } EC.draw(); }; EC_X.thrm = b => { S.ecTh = S.ecTh.filter(k => k !== b.dataset.v); save(); EC.draw(); };

