  const keep = cur && mode === 'merge' ? Object.fromEntries(['cc', 'code', 'name', 'cat', 'unit', 'freq', 'src', 'url', 'notes', 'mi'].map(k => [k, cur[k]])) : {};
  const M = { kind: 'eco', ...keep, ...Object.fromEntries(Object.entries(meta).filter(([, v]) => v != null && v !== '')) };
