  if (kind === 'news') { for (const r of recs) { const id = admId(iso(r.t) + '-' + r.title.toLowerCase()).slice(0, 80); if (r.body) await admWriteBody('n-' + id, /<\w/.test(r.body) ? r.body : stuMdHtml(r.body)); await W('adm_news', id, { title: r.title, date: admIso(r.t), sum: r.sum, cc: r.cc, cat: r.cat || 'Markets', imp: r.imp, ids: r.ids, srcName: r.src || '', url: r.url, hasBody: !!r.body }); } return `${recs.length} news items`; }
  if (kind === 'cal') { for (const r of recs) { const id = admId(iso(r.t) + '-' + r.title.toLowerCase()).slice(0, 80); const cat = ADM_CALCAT[r.cat] ? r.cat : Object.keys(ADM_CALCAT).find(k => ADM_CALCAT[k].toLowerCase().includes(String(r.cat || '').toLowerCase()) && r.cat) || 'oth'; await W('adm_cal', id, { title: r.title, date: admIso(r.t), time: /^\d{1,2}:\d{2}$/.test(r.time) ? r.time.padStart(5, '0') : '', cc: r.cc[0] || '', cat, imp: r.imp, cons: r.cons, prior: r.prior, actual: r.actual, unit: r.unit, ids: r.ids, srcName: r.src, url: r.url, notes: r.notes }); } return `${recs.length} events`; }
  if (kind === 'res') { for (const r of recs) { const id = admId((r.t ? iso(r.t) : 'undated') + '-' + r.title.toLowerCase()).slice(0, 80); if (r.body) await admWriteBody('r-' + id, /<\w/.test(r.body) ? r.body : stuMdHtml(r.body)); await W('adm_res', id, { title: r.title, date: r.t ? admIso(r.t) : '', author: r.author, type: r.type || 'Research note', cc: r.cc, tags: r.tags, ids: r.ids, sum: r.sum, url: r.url, hasBody: !!r.body }); } return `${recs.length} research items`; }
  if (kind === 'pco') { for (const r of recs) { const id = 'co-' + admId(r.name.toLowerCase()); const cur = ADM.raw.adm_priv[id]; await W('adm_priv', id, { kind: 'co', ...r, rounds: cur?.rounds || [] }); } return `${recs.length} companies`; }
