async function stuRun(fn) { if (STU.busy) return; STU.busy = true; stuProg('Saving…'); try { const msg = await fn(); STU.busy = false; toast(msg ? 'Saved: ' + msg : 'Saved'); admPersist(); admApply(false); render(); } catch (e) { STU.busy = false; console.error(e); const c = e && e.code; toast(c === 'quota_exceeded' ? 'Database is full: delete old items or split large series' : c === 'invalid_argument' ? 'Not saved: only the platform owner can write data-desk content, or a document is too large' : (e && e.message) || 'Save failed', true); stuProg(''); } }
