const fT = (n, l, v = '', rows = 6, ph = '') => `<label class="stu-f wide"><span>${esc(l)}</span><textarea class="inp sm mono" name="${n}" rows="${rows}" placeholder="${esc(ph)}">${esc(v ?? '')}</textarea></label>`;
