const stuCur = () => { const f = STU.files[STU.fi]; return f?.sheets?.[STU.si] || { rows: [], hi: 0 }; };
function stuSheetInit() { const s = stuCur(); if (s.hi == null) s.hi = stuHeader(s.rows); STU.kind = stuGuess(s.rows[s.hi] || [], s.name); STU.map = stuAutoMap(STU.kind, s.rows[s.hi] || []); }
