/* ---------- capitalization table ---------- */
/* holders: [{name, cls, kind:'common'|'pool'|'pref'|'safe', shares, invested, liq, part:'none'|'full'|'capped', cap, sen}] */
PM.fd = h => h.reduce((a, x) => a + (x.kind === 'safe' ? 0 : x.shares), 0);
