  const newI = Array(i.years + 1).fill(0), foI = Array(i.years + 1).fill(0); D.deals.forEach(d => { if (d.y0 <= i.years) (d.kind === 'fo' ? foI : newI)[d.y0] += d.amt; });
  const byOut = i.outs.map((o, j) => { const ds = D.deals.filter(d => d.out === j); return { l: o.l, n: ds.filter(d => d.kind === 'new').length, cost: ds.reduce((a, d) => a + d.amt, 0), proceeds: ds.reduce((a, d) => a + d.amt * d.mult, 0) }; });
