const $m = (v, dp = 1) => { if (v == null || !isFinite(v)) return '—'; const a = Math.abs(v), s = v < 0 ? MINUS : ''; return a >= 1000 ? `${s}$${nf(a / 1000, 2)}bn` : a >= 1 ? `${s}$${nf(a, dp)}m` : a >= .001 ? `${s}$${nf(a * 1000, 0)}k` : `${s}$0`; };
