const pmClone = o => JSON.parse(JSON.stringify(o));
function pmIn(k, label, v, o = {}) { return `<label class="f pm-f"><span>${esc(label)}${o.hint ? ` <i class="pm-hint" title="${esc(o.hint)}">?</i>` : ''}</span><div class="pm-iw"><input class="inp sm" type="number" data-k="${esc(k)}" value="${v}" step="${o.step ?? 'any'}"${o.min != null ? ` min="${o.min}"` : ''}${o.max != null ? ` max="${o.max}"` : ''} inputmode="decimal">${o.suf ? `<em>${esc(o.suf)}</em>` : ''}</div></label>`; }
