  let g = `<svg width="100%" style="display:block;max-width:100%" viewBox="0 0 ${W} ${H}" height="${H}" role="img" aria-label="${esc(label)}">`;
  for (const t of niceTicks(0, mx, 4)) g += `<line x1="${L}" x2="${W - R}" y1="${ty(t)}" y2="${ty(t)}" style="stroke:var(--line)"/><text x="${L - 6}" y="${ty(t) + 3.5}" text-anchor="end" style="fill:var(--muted);font:10.5px var(--f-num)">${nf(t, 0)}</text>`;
