  for (const t of niceTicks(lo, hi, Math.max(3, Math.floor(W / 120)))) { if (t < lo || t > hi) continue; g += `<text x="${tx(t)}" y="${H - B + 14}" text-anchor="middle" style="fill:var(--muted);font:10.5px var(--f-num)">${esc(xf(t))}</text>`; }
  lines.forEach((l, k) => { if (l.v == null || l.v < lo || l.v > hi) return; const x = tx(l.v); g += `<line x1="${x}" x2="${x}" y1="${T}" y2="${H - B}" style="stroke:${l.c || 'var(--fg)'};stroke-width:1.5${l.dash ? ';stroke-dasharray:4 3' : ''}"/><text x="${x + 4}" y="${T + 10 + (k % 4) * 12}" style="fill:${l.c || 'var(--fg)'};font:600 10.5px var(--f-ui)">${esc(l.l)}</text>`; });
