  const tot = rows.reduce((a, r) => a + Math.max(0, r.v), 0) || 1; const R = size / 2, r0 = R * .58; let a0 = -Math.PI / 2; let g = `<svg width="${size}" height="${size}" viewBox="0 0 ${size} ${size}" role="img" aria-label="${esc(label)}">`;
