  if (l2.length) for (const t of niceTicks(z0, z1, 4)) g += `<text x="${W - R + 6}" y="${tz(t) + 3.5}" style="fill:var(--muted);font:10.5px var(--f-num)">${esc(y2f(t))}</text>`;
  g += `<line x1="${L}" x2="${W - R}" y1="${ty(0)}" y2="${ty(0)}" style="stroke:var(--fg2)"/>`;
  const step = Math.max(1, Math.ceil(n / Math.floor((W - L - R) / 46))); xs.forEach((x, k) => { if (k % step === 0) g += `<text x="${tx(k)}" y="${H - B + 14}" text-anchor="middle" style="fill:var(--muted);font:10.5px var(--f-num)">${esc(xf(x))}</text>`; });
