    on($('#vcpt', el), 'change', '[data-peer]', (e, b) => { const ex = new Set(i.excl || []); b.checked ? ex.delete(b.dataset.peer) : ex.add(b.dataset.peer); i.excl = [...ex]; save(); inp.dispatchEvent(new Event('change')); });
