    const paid = -fI.reduce((a, x) => a + x.v, 0), dist = fD.reduce((a, x) => a + x.v, 0), fee = -fF.reduce((a, x) => a + x.v, 0);
    const yr = x => (q - x.t) / (365.25 * DAY); const pr = terms.pref / 100; const prefOwed = Math.max(0, [...fI, ...fF].reduce((a, x) => a + -x.v * (Math.pow(1 + pr, yr(x)) - 1), 0) - fD.reduce((a, x) => a + x.v * (Math.pow(1 + pr, yr(x)) - 1), 0));
    const o = PM.tier({ U: paid + fee, Q: prefOwed, lpP: 0, gp: 0 }, dist + nav, { carry: terms.carry / 100, cu: terms.cu / 100 }); const carry = o.toGP;
