  const H = pmHold(); const all = H.map(h => pmPos(h)).filter(Boolean); const ex = all.some(x => x.h.example); const T = pmTerms();
  pg.innerHTML = hdr('pport', `Value, returns, cash flows, operating KPIs, risk and benchmarks for your direct private holdings. ${ex ? pmTag('ill', 'Example holdings') + ' Example positions in fictional companies are loaded; add your own to replace them.' : ''}`, `${seg('pmark', [['last', 'Mark: last round'], ['model', 'Saved model'], ['rev', 'Revenue multiple']], PORT.mark)}<button class="btn pri" id="phAdd">Add holding</button>`) + `<div class="pm-tabs">${seg('ptab', PT_TABS, PT.tab)}</div><div id="ptb"></div>`;
  onSeg(pg, 'pmark', v => { PORT.mark = v; render(); }); onSeg(pg, 'ptab', v => { PT.tab = v; draw(); }); $('#phAdd', pg).onclick = () => pmAddHolding();
  const draw = () => { const b = $('#ptb', pg); b.innerHTML = ''; try { PT_DRAW[PT.tab](b, all, T); } catch (e) { console.error(e); b.innerHTML = `<div class="callout">This view hit an error: ${esc(e.message)}</div>`; } };
  on(pg, 'click', '[data-phd]', (e, b) => { const P = pmPriv(); P.holdings = P.holdings.filter(h => h.id !== b.dataset.phd); save(); render(); });
  on(pg, 'click', '[data-phr]', (e, b) => { const h = pmHold().find(x => x.id === b.dataset.phr); modal('Record a distribution', `${pmIn('rv', 'Amount received', 0, { suf: '$m' })}<label class="f"><span>Date</span><input class="inp sm" type="date" id="rdt" value="${iso(END)}"></label><p class="note">Distributions count as realised value in MOIC and IRR. Reduce ownership separately if shares were sold.</p>`, { actions: [{ label: 'Cancel', fn: x => x() }, { label: 'Save', cls: 'pri', fn: (x, mb) => { const v = +$('[data-k="rv"]', mb).value; const t = Date.parse($('#rdt', mb).value); if (!(v > 0) || !t) return toast('Enter an amount and date', true); (h.real ||= []).push({ v, t }); save(); x(); render(); } }] }); });
