  const costU = pos.filter(p => p.fv > 0).reduce((a, p) => a + p.h.cost, 0), costR = pos.filter(p => p.status === 'Realised').reduce((a, p) => a + p.h.cost, 0);
  el.innerHTML = `<div class="pm-tiles">${pmTile('Total invested', $m(cost), `${pos.length} holdings`)}${pmTile('Committed', $m(committed), 'cost + follow-on reserves')}${pmTile('Available for drawdown', $m(committed - cost))}${pmTile('Fair value', $m(fv), 'unrealised')}${pmTile('Realised', $m(real))}${pmTile('Gross IRR', pF(L.gIrr), '', cls(L.gIrr))}${pmTile('Net IRR', pF(L.nIrr), 'after illustrative fees & carry', cls(L.nIrr))}${pmTile('TVPI · gross / net', `${xF(L.tvpi, 2)} / ${xF(L.ntvpi, 2)}`)}${pmTile('DPI', xF(L.dpi, 2))}</div>
    <div class="grid">${panelH('Value bridge', { cls: 'c7', id: 'pov1' })}${panelH('Terms used for net returns', { cls: 'c5', id: 'pov0' })}${panelH('Cash flows by year · USD m', { cls: 'c6', id: 'pov2' })}${panelH('Interim IRR · realised and unrealised', { cls: 'c6', id: 'pov3' })}${panelH('Performance ratios', { cls: 'c6', id: 'pov4', foot: '<span>Paid-in capital as a share of commitments; DPI, RVPI and TVPI gross of fees and carry. Quarterly; positions marked at the last round on each date (current mark at the latest point).</span>' })}${panelH('NAV evolution · USD m', { cls: 'c6', id: 'pov5' })}${panelH('Exposure', { cls: 'c12', id: 'pov6' })}${panelH('Holdings', { cls: 'c12', id: 'pov7', flush: true })}</div>`;
  pmBridge($('#pov1', el), { steps: [{ l: 'Invested', v: cost, total: true }, { l: 'Unrealised gain', v: fv - costU }, { l: 'Realised gain', v: real - costR }, { l: 'Gross value', v: fv + real, total: true }, { l: 'Fees', v: -L.fee }, { l: 'Accrued carry', v: -L.carry }, { l: 'Net value', v: fv + real - L.fee - L.carry, total: true }] });
  $('#pov0', el).innerHTML = `<div class="pm-2" id="ptT">${pmIn('fee', 'Management fee', T.fee, { suf: '% p.a. on cost' })}${pmIn('carry', 'Carried interest', T.carry, { suf: '%' })}${pmIn('pref', 'Preferred return', T.pref, { suf: '% p.a.' })}${pmIn('cu', 'GP catch-up', T.cu, { suf: '%' })}</div><p class="note">${pmTag('ill')} Net figures apply these terms to the holdings' dated cash flows: fees on unrealised cost each quarter, carry accrued on total value above the hurdle (whole-portfolio waterfall). Use your fund documents for reported net returns.</p>`;
  $('#ptT', el).addEventListener('change', () => { pmRead($('#ptT', el), T); save(); PT_DRAW.ov(el, pos, T); });
  const yrs = [...new Set(S.qs.map(q => new Date(q).getUTCFullYear()))]; const byY = (arr, sgnv) => yrs.map(y => arr.filter(x => new Date(x.t).getUTCFullYear() === y).reduce((a, x) => a + x.v, 0) * sgnv);
  const inv = S.fl.filter(x => x.v < 0), dis = S.fl.filter(x => x.v > 0), fe = S.netFl.filter(x => x.v < 0 && !S.fl.includes(x)); let cum = 0; const net = yrs.map((y, k) => (cum += byY(inv, 1)[k] + byY(fe, 1)[k] + byY(dis, 1)[k]));
