  pmLines($('#pov5', el), { xs, xf: qf, yf: v => $m(v, 0), stack: true, series: [{ label: 'NAV (unrealised value)', values: S.pts.map(x => x.nav) }, { label: 'Cumulative distributions', values: S.pts.map(x => x.dist), c: 'var(--up)' }] });
