  const dn = () => { const w = p => PT.exp === 'fv' ? p.fv : p.h.cost; const grp = f => { const m = {}; pos.forEach(p => { const k = f(p); m[k] = (m[k] || 0) + w(p); }); return Object.entries(m).filter(x => x[1] > 0).sort((a, b) => b[1] - a[1]).map(([l, v]) => ({ l, v })); }; pmDonut($('#pd1', E), { rows: grp(p => p.c.sector) }); pmDonut($('#pd2', E), { rows: grp(p => COUNTRY[p.c.cc]?.n || p.c.cc) }); pmDonut($('#pd3', E), { rows: grp(p => pmCcy(p.c.cc)) }); };
