  on(el, 'click', '[data-ped]', (e, b) => { const h = pmHold().find(x => x.id === b.dataset.ped); modal('Edit investment', `<label class="f"><span>Deal source</span><select class="inp" id="eS">${['Founder', 'Referral', 'Co-investment', 'Limited auction', 'Auction', 'Secondary'].map(x => `<option ${x === h.src ? 'selected' : ''}>${x}</option>`).join('')}</select></label><label class="f"><span>Vehicle</span><input class="inp" id="eV" value="${esc(h.vehicle || '')}"></label>${pmIn('eR', 'Follow-on reserve', h.reserve || 0, { suf: '$m' })}`, { actions: [{ label: 'Cancel', fn: x => x() }, { label: 'Save', cls: 'pri', fn: (x, mb) => { h.src = $('#eS', mb).value; h.vehicle = $('#eV', mb).value.trim() || 'Direct portfolio'; h.reserve = +$('[data-k="eR"]', mb).value || 0; save(); x(); render(); } }] }); });
