  const gmP = gp.map((v, k) => rev[k] ? v / rev[k] * 100 : null); const card = (t, v, d, sub) => `<div class="pm-tile"><span>${esc(t)}</span><b>${v}</b><em>${d == null ? '' : `<span class="${cls(d)}">${d >= 0 ? '↑' : '↓'} ${nf(Math.abs(d), 1)}${sub || '%'}</span> from prior quarter`}</em></div>`;
  el.innerHTML = `<div class="row" style="gap:10px;margin-bottom:12px;flex-wrap:wrap">${seg('pkper', [[4, '4Q'], [8, '8Q'], [12, '12Q'], [24, 'All']].map(([a, b]) => [String(a), b]), String(PT.per))}${seg('pkw', [['0', 'Company totals'], ['1', 'Ownership-weighted']], PT.kw ? '1' : '0')}<span class="note">${pmTag('sim')} Quarterly operating data for ${pos.length} unrealised holdings, generated by the simulator; shown in USD.</span><button class="btn sm" id="pkAI" style="margin-left:auto">AI summary</button></div>
    <div class="pm-tiles">${card('Revenue · last quarter', $m(rev[L]), ch(rev[L], rev[L - 1]))}${card('EBITDA · LTM', $m(ltm(eb)), ch(ltm(eb), ltmP(eb)) == null ? null : (ltm(eb) - ltmP(eb)) / Math.abs(ltmP(eb) || 1) * 100)}${card('Gross margin · revenue-weighted', pF(gmP[L]), gmP[L] - gmP[L - 1], 'pt')}${card('Cash · portfolio companies', $m(cash[L]), ch(cash[L], cash[L - 1]))}</div>
    <div class="grid"><div class="c12" id="pkAIo"></div>${panelH('Revenue by company and gross margin', { cls: 'c7', id: 'pk1' })}${panelH('Gross margin · latest quarter', { cls: 'c5', id: 'pk2' })}${panelH('EBITDA and revenue', { cls: 'c12', id: 'pk3' })}${panelH('Company detail · actual vs budget', { cls: 'c12', id: 'pk4' })}</div>`;
